void scenarioLogicalTimeFactory(Options const& options, rti::CallbackModel model) {
  Session session(options, model, "time");
  requireException(
      [&] { static_cast<void>(session.rtiAmbassador().getTimeFactory()); },
      L"NotConnected",
      "getting the logical-time factory before connect");
  session.connect();
  requireException(
      [&] { static_cast<void>(session.rtiAmbassador().getTimeFactory()); },
      L"FederateNotExecutionMember",
      "getting the logical-time factory before joining");
  auto const federation = federationName(options, "logical-time-factory");
  session.rtiAmbassador().createFederationExecution(
      federation,
      options.fom.wstring(),
      options.logicalTimeImplementationName);
  session.join(options.ownerFederateName, options.federateType, federation);

  auto time = makeTimeContext(session);
  verifyReferenceTimeTypes();
  verifyLogicalTimeDataElements(session, time);
  require(
      time.factory->getName() == time.initial->implementationName(),
      "logical-time factory name did not match the returned logical-time implementation");

  auto const initialEncoding = encodeTime(*time.initial);
  auto const initialEncodedValue = time.initial->encode();
  auto decodedInitial = time.factory->decodeLogicalTime(time.initial->encode());
  require(decodedInitial != nullptr, "logical-time factory returned no decoded initial time");
  requireTimeEquals(
      *decodedInitial,
      *time.initial,
      "logical-time initial encode/decode");
  auto decodedInitialFromBuffer = time.factory->decodeLogicalTime(
      initialEncodedValue.data(),
      time.initial->encodedLength());
  require(decodedInitialFromBuffer != nullptr,
          "logical-time factory returned no buffer-decoded initial time");
  requireTimeEquals(
      *decodedInitialFromBuffer,
      *time.initial,
      "logical-time initial buffer decode");
  require(
      initialEncoding.size() == time.initial->encodedLength(),
      "logical-time encoded length did not match the encoded value");
  requireDirectTimeEncoding(
      *time.initial,
      "logical-time initial value");
  requireDirectTimeEncoding(
      *time.finalTime,
      "logical-time final value");

  auto directDecodedInitial = time.factory->makeFinal();
  directDecodedInitial->decode(
      initialEncoding.data(),
      initialEncoding.size());
  requireTimeEquals(
      *directDecodedInitial,
      *time.initial,
      "logical-time direct buffer decode");
  if (initialEncoding.size() > 1U) {
    std::vector<rti::Octet> truncatedInitial(
        initialEncoding.begin(),
        initialEncoding.end() - 1);
    requireException(
        [&] {
          static_cast<void>(
              time.factory->decodeLogicalTime(
                  truncatedInitial.data(),
                  truncatedInitial.size()));
        },
        L"CouldNotDecode",
        "truncated logical-time buffer");
  }

  auto decodedZero = time.factory->decodeLogicalTimeInterval(time.zero->encode());
  require(decodedZero != nullptr, "logical-time factory returned no decoded zero interval");
  require(*decodedZero == *time.zero, "logical-time zero interval did not round-trip");
  auto const epsilonEncodedValue = time.epsilon->encode();
  auto decodedEpsilon = time.factory->decodeLogicalTimeInterval(
      epsilonEncodedValue.data(),
      time.epsilon->encodedLength());
  require(decodedEpsilon != nullptr,
          "logical-time factory returned no buffer-decoded epsilon interval");
  require(*decodedEpsilon == *time.epsilon,
          "logical-time epsilon interval did not round-trip");

  requireDirectTimeEncoding(
      *time.zero,
      "logical-time zero interval");
  requireDirectTimeEncoding(
      *time.epsilon,
      "logical-time epsilon interval");

  auto zeroEncoding = copyBytes(time.zero->encode());
  auto directDecodedZero = time.factory->makeEpsilon();
  directDecodedZero->decode(zeroEncoding.data(), zeroEncoding.size());
  require(
      *directDecodedZero == *time.zero,
      "logical-time interval direct buffer decode");
  if (zeroEncoding.size() > 1U) {
    std::vector<rti::Octet> truncatedZero(
        zeroEncoding.begin(),
        zeroEncoding.end() - 1);
    requireException(
        [&] {
          static_cast<void>(
              time.factory->decodeLogicalTimeInterval(
                  truncatedZero.data(),
                  truncatedZero.size()));
        },
        L"CouldNotDecode",
        "truncated logical-time interval buffer");
  }

  auto boundary = time.factory->makeInitial();
  boundary->setFinal();
  require(boundary->isFinal(), "logical-time setFinal did not create final time");
  boundary->setInitial();
  require(boundary->isInitial(), "logical-time setInitial did not restore initial time");
  auto intervalArithmetic = time.factory->makeZero();
  *intervalArithmetic += *time.epsilon;
  require(
      *intervalArithmetic == *time.epsilon,
      "logical-time interval addition did not advance from zero");
  *intervalArithmetic -= *time.epsilon;
  require(
      *intervalArithmetic == *time.zero,
      "logical-time interval subtraction did not return to zero");
  require(
      *time.epsilon > *time.zero && *time.zero < *time.epsilon,
      "logical-time interval ordering did not place epsilon after zero");

  auto first = timeAfter(*time.factory, *time.initial, *time.epsilon, 1U);
  auto second = timeAfter(*time.factory, *time.initial, *time.epsilon, 2U);
  require(*first > *time.initial, "epsilon did not advance logical time");
  require(*second > *first, "logical-time values did not preserve ordering");
  require(*first <= *second && *second >= *first,
          "logical-time comparison operators were inconsistent");
  auto difference = time.factory->makeZero();
  difference->setToDifference(*second, *first);
  require(*difference == *time.epsilon,
          "logical-time difference did not recover one epsilon interval");
  auto copied = time.factory->makeInitial();
  *copied = *second;
  require(*copied == *second, "logical-time assignment did not preserve the value");
  auto underflow = time.factory->makeInitial();
  requireException(
      [&] { *underflow -= *time.epsilon; },
      L"IllegalTimeArithmetic",
      "logical-time subtraction before initial");
  auto finalBoundary = time.factory->makeFinal();
  *finalBoundary += *time.epsilon;
  require(finalBoundary->isFinal(),
          "logical-time addition to final did not preserve final");
  *finalBoundary -= *time.epsilon;
  require(finalBoundary->isFinal(),
          "logical-time subtraction from final did not preserve final");

  requireException(
      [&] { static_cast<void>(time.factory->decodeLogicalTime(rti::VariableLengthData{})); },
      L"CouldNotDecode",
      "empty logical-time encoding");
  requireException(
      [&] {
        static_cast<void>(
            time.factory->decodeLogicalTimeInterval(rti::VariableLengthData{}));
      },
      L"CouldNotDecode",
      "empty logical-time interval encoding");

  session.resign(rti::NO_ACTION);
  session.rtiAmbassador().destroyFederationExecution(federation);
  session.disconnect();
}

void scenarioTimeAdvance(Options const& options, rti::CallbackModel model) {
  Session regulator(options, model, "owner");
  Session constrained(options, model, "member");
  Session lookaheadLifecycle(options, model, "lookahead-lifecycle");
  auto const federation = federationName(options, "time-advance");
  connectAndJoin(regulator, constrained, options, federation, options.fom);

  auto regulatorTime = makeTimeContext(regulator);
  auto constrainedTime = makeTimeContext(constrained);
  auto lifecycleLogicalTime = regulatorTime.factory->makeInitial();
  auto lifecycleGalt = regulatorTime.factory->makeInitial();
  auto lifecycleLits = regulatorTime.factory->makeInitial();
  auto lifecycleLookahead = regulatorTime.factory->makeZero();
  auto requireTimeServiceLifecycle = [&](std::wstring const& expected,
                                         std::string const& phase) {
    requireException(
        [&] {
          lookaheadLifecycle.rtiAmbassador().enableTimeRegulation(
              *regulatorTime.epsilon);
        },
        expected,
        "enabling time regulation " + phase);
    requireException(
        [&] { lookaheadLifecycle.rtiAmbassador().disableTimeRegulation(); },
        expected,
        "disabling time regulation " + phase);
    requireException(
        [&] { lookaheadLifecycle.rtiAmbassador().enableTimeConstrained(); },
        expected,
        "enabling time constrained " + phase);
    requireException(
        [&] { lookaheadLifecycle.rtiAmbassador().disableTimeConstrained(); },
        expected,
        "disabling time constrained " + phase);
    requireException(
        [&] {
          lookaheadLifecycle.rtiAmbassador().timeAdvanceRequest(
              *regulatorTime.initial);
        },
        expected,
        "requesting a time advance " + phase);
    requireException(
        [&] {
          lookaheadLifecycle.rtiAmbassador().timeAdvanceRequestAvailable(
              *regulatorTime.initial);
        },
        expected,
        "requesting an available time advance " + phase);
    requireException(
        [&] {
          lookaheadLifecycle.rtiAmbassador().nextMessageRequest(
              *regulatorTime.initial);
        },
        expected,
        "requesting the next message " + phase);
    requireException(
        [&] {
          lookaheadLifecycle.rtiAmbassador().nextMessageRequestAvailable(
              *regulatorTime.initial);
        },
        expected,
        "requesting the next message when available " + phase);
    requireException(
        [&] {
          lookaheadLifecycle.rtiAmbassador().flushQueueRequest(
              *regulatorTime.initial);
        },
        expected,
        "requesting a queue flush " + phase);
    requireException(
        [&] {
          static_cast<void>(lookaheadLifecycle.rtiAmbassador().queryGALT(
              *lifecycleGalt));
        },
        expected,
        "querying GALT " + phase);
    requireException(
        [&] {
          lookaheadLifecycle.rtiAmbassador().queryLogicalTime(
              *lifecycleLogicalTime);
        },
        expected,
        "querying logical time " + phase);
    requireException(
        [&] {
          static_cast<void>(lookaheadLifecycle.rtiAmbassador().queryLITS(
              *lifecycleLits));
        },
        expected,
        "querying LITS " + phase);
    requireException(
        [&] {
          lookaheadLifecycle.rtiAmbassador().queryLookahead(
              *lifecycleLookahead);
        },
        expected,
        "querying lookahead " + phase);
    requireException(
        [&] {
          lookaheadLifecycle.rtiAmbassador().modifyLookahead(
              *regulatorTime.epsilon);
        },
        expected,
        "modifying lookahead " + phase);
    requireException(
        [&] { lookaheadLifecycle.rtiAmbassador().enableAsynchronousDelivery(); },
        expected,
        "enabling asynchronous delivery " + phase);
    requireException(
        [&] { lookaheadLifecycle.rtiAmbassador().disableAsynchronousDelivery(); },
        expected,
        "disabling asynchronous delivery " + phase);
  };
  requireTimeServiceLifecycle(L"NotConnected", "before connect");
  lookaheadLifecycle.connect();
  requireTimeServiceLifecycle(
      L"FederateNotExecutionMember",
      "after connect before joining");
  lookaheadLifecycle.disconnect();
  requireException(
      [&] { regulator.rtiAmbassador().modifyLookahead(*regulatorTime.epsilon); },
      L"TimeRegulationIsNotEnabled",
      "modifying lookahead before enabling time regulation");
  require(
      regulatorTime.factory->getName() == constrainedTime.factory->getName(),
      "joined federates selected different logical-time factories");

  regulator.rtiAmbassador().enableTimeRegulation(*regulatorTime.epsilon);
  waitFor(
      regulator,
      [&] { return regulator.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "time regulation enabled callback");
  auto const regulationCallbacks = regulator.recorder().timeRegulationEnabled();
  require(regulationCallbacks.size() == 1U,
          "time regulation enabled callback was delivered more than once");
  require(regulationCallbacks.front().encoded == encodeTime(*regulatorTime.initial),
          "time regulation enabled callback returned the wrong initial time");
  requireException(
      [&] {
        regulator.rtiAmbassador().enableTimeRegulation(*regulatorTime.epsilon);
      },
      L"TimeRegulationAlreadyEnabled",
      "enabling time regulation twice after its callback");

  constrained.rtiAmbassador().enableTimeConstrained();
  waitFor(
      constrained,
      [&] { return constrained.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "time constrained enabled callback");
  auto const constrainedCallbacks = constrained.recorder().timeConstrainedEnabled();
  require(constrainedCallbacks.size() == 1U,
          "time constrained enabled callback was delivered more than once");
  require(constrainedCallbacks.front().encoded == encodeTime(*constrainedTime.initial),
          "time constrained enabled callback returned the wrong initial time");
  requireException(
      [&] { constrained.rtiAmbassador().enableTimeConstrained(); },
      L"TimeConstrainedAlreadyEnabled",
      "enabling time constrained twice after its callback");

  auto queriedRegulatorTime = regulatorTime.factory->makeInitial();
  regulator.rtiAmbassador().queryLogicalTime(*queriedRegulatorTime);
  requireTimeEquals(
      *queriedRegulatorTime,
      *regulatorTime.initial,
      "initial regulator logical-time query");
  auto queriedConstrainedTime = constrainedTime.factory->makeInitial();
  constrained.rtiAmbassador().queryLogicalTime(*queriedConstrainedTime);
  requireTimeEquals(
      *queriedConstrainedTime,
      *constrainedTime.initial,
      "initial constrained logical-time query");

  auto queriedLookahead = regulatorTime.factory->makeZero();
  regulator.rtiAmbassador().queryLookahead(*queriedLookahead);
  require(*queriedLookahead == *regulatorTime.epsilon,
          "initial lookahead did not match the requested epsilon");
  auto changedLookahead = timeAfter(
      *regulatorTime.factory,
      *regulatorTime.initial,
      *regulatorTime.epsilon,
      2U);
  auto changedInterval = regulatorTime.factory->makeZero();
  changedInterval->setToDifference(*changedLookahead, *regulatorTime.initial);
  regulator.rtiAmbassador().modifyLookahead(*changedInterval);
  auto queriedChangedLookahead = regulatorTime.factory->makeZero();
  regulator.rtiAmbassador().queryLookahead(*queriedChangedLookahead);
  require(*queriedChangedLookahead == *changedInterval,
          "modified lookahead did not cross the standard query boundary");
  regulator.rtiAmbassador().modifyLookahead(*regulatorTime.epsilon);
  auto deferredLookahead = regulatorTime.factory->makeZero();
  regulator.rtiAmbassador().queryLookahead(*deferredLookahead);
  require(*deferredLookahead == *changedInterval,
          "lookahead decrease took effect before logical time advanced");

  auto regulatorTarget = timeAfter(
      *regulatorTime.factory,
      *regulatorTime.initial,
      *regulatorTime.epsilon,
      4U);
  auto constrainedTarget = timeAfter(
      *constrainedTime.factory,
      *constrainedTime.initial,
      *constrainedTime.epsilon,
      4U);
  regulator.rtiAmbassador().timeAdvanceRequest(*regulatorTarget);
  if (model == rti::HLA_EVOKED) {
    requireException(
        [&] { regulator.rtiAmbassador().timeAdvanceRequest(*regulatorTarget); },
        L"InTimeAdvancingState",
        "second time advance request while the first is pending");
  }
  constrained.rtiAmbassador().timeAdvanceRequest(*constrainedTarget);
  if (model == rti::HLA_EVOKED) {
    regulator.rtiAmbassador().queryLogicalTime(*queriedRegulatorTime);
    requireTimeEquals(
        *queriedRegulatorTime,
        *regulatorTime.initial,
        "pending regulator logical-time query before Time Advance Grant");
    constrained.rtiAmbassador().queryLogicalTime(*queriedConstrainedTime);
    requireTimeEquals(
        *queriedConstrainedTime,
        *constrainedTime.initial,
        "pending constrained logical-time query before Time Advance Grant");
  }
  waitFor(
      regulator,
      constrained,
      [&] {
        return regulator.recorder().timeAdvanceGrants().size() >= 1U &&
            constrained.recorder().timeAdvanceGrants().size() >= 1U;
      },
      options,
      "time advance grants");
  auto const regulatorGrants = regulator.recorder().timeAdvanceGrants();
  auto const constrainedGrants = constrained.recorder().timeAdvanceGrants();
  require(regulatorGrants.size() == 1U && constrainedGrants.size() == 1U,
          "time advance delivered more than one grant per request");
  require(regulatorGrants.front().encoded == encodeTime(*regulatorTarget),
          "regulator time advance grant returned the wrong time");
  require(constrainedGrants.front().encoded == encodeTime(*constrainedTarget),
          "constrained time advance grant returned the wrong time");
  auto appliedLookahead = regulatorTime.factory->makeZero();
  regulator.rtiAmbassador().queryLookahead(*appliedLookahead);
  require(*appliedLookahead == *regulatorTime.epsilon,
          "lookahead decrease did not take effect after logical time advanced");
  auto queriedRegulatorTarget = regulatorTime.factory->makeInitial();
  regulator.rtiAmbassador().queryLogicalTime(*queriedRegulatorTarget);
  requireTimeEquals(
      *queriedRegulatorTarget,
      *regulatorTarget,
      "advanced regulator logical-time query");
  auto queriedConstrainedTarget = constrainedTime.factory->makeInitial();
  constrained.rtiAmbassador().queryLogicalTime(*queriedConstrainedTarget);
  requireTimeEquals(
      *queriedConstrainedTarget,
      *constrainedTarget,
      "advanced constrained logical-time query");
  auto earlierRegulatorTarget = timeAfter(
      *regulatorTime.factory,
      *regulatorTime.initial,
      *regulatorTime.epsilon,
      3U);
  requireException(
      [&] { regulator.rtiAmbassador().timeAdvanceRequest(*earlierRegulatorTarget); },
      L"LogicalTimeAlreadyPassed",
      "time advance request behind the granted logical time");

  constrained.rtiAmbassador().disableTimeConstrained();
  requireException(
      [&] { constrained.rtiAmbassador().disableTimeConstrained(); },
      L"TimeConstrainedIsNotEnabled",
      "disabling time constrained twice");
  regulator.rtiAmbassador().disableTimeRegulation();
  requireException(
      [&] { regulator.rtiAmbassador().disableTimeRegulation(); },
      L"TimeRegulationIsNotEnabled",
      "disabling time regulation twice");
  constrained.resign(rti::NO_ACTION);
  regulator.resign(rti::NO_ACTION);
  regulator.rtiAmbassador().destroyFederationExecution(federation);
  constrained.disconnect();
  regulator.disconnect();
}

