void scenarioCustomTransportationTimestampedRegionalAttributeDelivery(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.modelFom.empty(),
      "Custom transportation timestamped regional attribute testing requires an adapter-supplied rich FOM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Custom transportation timestamped regional attribute testing requires an adapter-supplied logical-time implementation");
  require(
      options.ddmDimensionNames.size() >= 2U,
      "Custom transportation timestamped regional attribute testing requires two adapter-supplied dimensions");

  // Reuse the complete standard regional timestamp/retraction oracle while
  // selecting every declaration from adapter-supplied names and the rich FOM.
  // The core oracle is intentionally shared with the ordinary regional slice
  // so the custom-transport extension cannot drift from the standard route.
  auto regional = options;
  regional.ddmFom = regional.modelFom;
  regional.objectClassName = regional.customRegionalObjectClassName;
  regional.attributeName = regional.customRegionalAttributeName;
  regional.interactionClassName = regional.customRegionalInteractionClassName;
  regional.parameterName = regional.customRegionalParameterName;
  regional.requireCustomTransportation = true;
  scenarioTimestampedRegionalAttributeUpdate(regional, model);
}

