void scenarioResignDeleteObjects(Options const& options, rti::CallbackModel model) {
  Session owner(options, model, "resign-delete-owner");
  Session member(options, model, "resign-delete-member");
  auto const federation = federationName(options, "resign-delete-objects");
  connectAndJoin(owner, member, options, federation, options.fom);

  rti::ObjectClassHandle objectClass;
  rti::AttributeHandle attribute;
  rti::InteractionClassHandle interactionClass;
  rti::ParameterHandle parameter;
  handles(owner, options, objectClass, attribute, interactionClass, parameter);
  rti::AttributeHandleSet attributes;
  attributes.insert(attribute);
  owner.rtiAmbassador().publishObjectClassAttributes(objectClass, attributes);
  member.rtiAmbassador().subscribeObjectClassAttributes(objectClass, attributes);

  auto const object = owner.rtiAmbassador().registerObjectInstance(objectClass);
  require(object.isValid(), "Resign-delete registration returned an invalid handle");
  auto const name = owner.rtiAmbassador().getObjectInstanceName(object);
  require(!name.empty(), "Resign-delete registration returned an empty name");
  waitFor(member, [&] { return member.recorder().discovery().present; }, options,
          "resign-delete object discovery");
  auto const discovery = member.recorder().discovery();
  require(discovery.object == object, "Resign-delete discovery returned the wrong object");
  require(discovery.objectClass == objectClass,
          "Resign-delete discovery returned the wrong object class");
  require(discovery.name == name, "Resign-delete discovery returned the wrong object name");

  requireException(
      [&] { owner.resign(rti::NO_ACTION); },
      L"FederateOwnsAttributes",
      "resigning without deleting a delete-privileged object");

  member.recorder().clearRemovals();
  owner.resign(rti::DELETE_OBJECTS);
  waitFor(member,
          [&] {
            return member.recorder().hasRemoval(
                object, {}, owner.federateHandle());
          },
          options,
          "resign-delete object removal");
  auto const removals = member.recorder().removals();
  require(removals.size() == 1U,
          "resign-delete delivered a duplicate object removal callback");
  require(removals.front().object == object && removals.front().tag.empty() &&
              removals.front().producer == owner.federateHandle(),
          "resign-delete returned the wrong removal metadata");
  requireException(
      [&] { static_cast<void>(member.rtiAmbassador().getObjectInstanceHandle(name)); },
      L"ObjectInstanceNotKnown",
      "looking up an object after resign-time deletion");

  member.resign(rti::NO_ACTION);
}

void scenarioResignDeleteObjectsContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioResignDeleteObjects(options, model);
}

void scenarioPrivilegeToDeletePublicationEligibility(
    Options const& options,
    rti::CallbackModel model) {
  Session owner(options, model, "owner");
  Session acquirer(options, model, "member");
  auto const federation = federationName(
      options,
      "privilege-to-delete-publication-eligibility");
  connectAndJoin(owner, acquirer, options, federation, options.fom);

  auto const ownerClass = owner.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const acquirerClass = acquirer.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const ownerValue = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.attributeName);
  auto const acquirerValue = acquirer.rtiAmbassador().getAttributeHandle(
      acquirerClass,
      options.attributeName);
  auto const ownerPrivilege = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      L"HLAprivilegeToDeleteObject");
  auto const acquirerPrivilege = acquirer.rtiAmbassador().getAttributeHandle(
      acquirerClass,
      L"HLAprivilegeToDeleteObject");
  require(
      ownerClass.isValid() && acquirerClass.isValid() && ownerValue.isValid() &&
          acquirerValue.isValid() && ownerPrivilege.isValid() &&
          acquirerPrivilege.isValid(),
      "Delete-privilege eligibility could not resolve the adapter class or standard attributes");

  rti::AttributeHandleSet const ownerValues{ownerValue};
  rti::AttributeHandleSet const acquirerValues{acquirerValue};
  rti::AttributeHandleSet const ownerPrivileges{ownerPrivilege};
  rti::AttributeHandleSet const acquirerPrivileges{acquirerPrivilege};
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerValues);
  acquirer.rtiAmbassador().subscribeObjectClassAttributes(
      acquirerClass,
      acquirerValues);
  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(object.isValid(), "Delete-privilege eligibility registration returned an invalid handle");
  waitFor(
      acquirer,
      [&] { return acquirer.recorder().hasDiscovery(object); },
      options,
      "delete-privilege eligibility object discovery");
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerPrivilege) &&
          !acquirer.rtiAmbassador().isAttributeOwnedByFederate(object, acquirerPrivilege),
      "delete privilege did not initially belong only to the object registrant");

  // Publishing another attribute implicitly publishes this standard
  // privilege. Explicitly remove only the privilege while the class remains
  // published so the acquisition tests the attribute-level eligibility gate.
  acquirer.rtiAmbassador().publishObjectClassAttributes(
      acquirerClass,
      acquirerValues);
  acquirer.rtiAmbassador().unpublishObjectClassAttributes(
      acquirerClass,
      acquirerPrivileges);
  std::vector<std::uint8_t> const acquisitionTagBytes{0xE1U, 0x25U};
  rti::VariableLengthData const acquisitionTag(
      acquisitionTagBytes.data(),
      acquisitionTagBytes.size());
  acquirer.recorder().clearOwnershipRecords();
  requireException(
      [&] {
        acquirer.rtiAmbassador().attributeOwnershipAcquisition(
            object,
            acquirerPrivileges,
            acquisitionTag);
      },
      L"AttributeNotPublished",
      "acquiring delete privilege while it is explicitly unpublished");
  require(
      !acquirer.recorder().ownershipAcquisition().has_value() &&
          owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerPrivilege) &&
          !acquirer.rtiAmbassador().isAttributeOwnedByFederate(object, acquirerPrivilege),
      "rejected delete-privilege acquisition notified the acquirer or changed ownership");

  acquirer.rtiAmbassador().publishObjectClassAttributes(
      acquirerClass,
      acquirerPrivileges);
  acquirer.rtiAmbassador().attributeOwnershipAcquisition(
      object,
      acquirerPrivileges,
      acquisitionTag);
  rti::AttributeHandleSet divested;
  rti::VariableLengthData const divestitureTag;
  owner.rtiAmbassador().attributeOwnershipDivestitureIfWanted(
      object,
      ownerPrivileges,
      divestitureTag,
      divested);
  require(
      divested == ownerPrivileges,
      "eligible delete-privilege transfer returned the wrong divested set");
  waitFor(
      acquirer,
      [&] { return acquirer.recorder().ownershipAcquisition().has_value(); },
      options,
      "eligible delete-privilege acquisition notification");
  auto const acquisition = acquirer.recorder().ownershipAcquisition();
  require(
      acquisition->object == object &&
          acquisition->attributes == acquirerPrivileges &&
          acquisition->tag.empty(),
      "eligible delete-privilege notification returned the wrong object, set, or tag");
  require(
      !owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerPrivilege) &&
          acquirer.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              acquirerPrivilege),
      "eligible delete-privilege acquisition did not transfer ownership");

  rti::VariableLengthData const deletionTag;
  acquirer.rtiAmbassador().deleteObjectInstance(object, deletionTag);
  acquirer.resign(rti::NO_ACTION);
  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  acquirer.disconnect();
  owner.disconnect();
}

void scenarioPrivilegeToDeletePublicationEligibilityContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioPrivilegeToDeletePublicationEligibility(options, model);
}

void scenarioResignUnconditionalDivestiture(
    Options const& options,
    rti::CallbackModel model) {
  Session owner(options, model, "resign-divest-owner");
  Session peer(options, model, "resign-divest-peer");
  auto const federation = federationName(options, "resign-unconditional-divestiture");
  connectAndJoin(owner, peer, options, federation, options.fom);

  rti::ObjectClassHandle objectClass;
  rti::AttributeHandle attribute;
  rti::InteractionClassHandle interactionClass;
  rti::ParameterHandle parameter;
  handles(owner, options, objectClass, attribute, interactionClass, parameter);
  auto const privilegeToDelete = owner.rtiAmbassador().getAttributeHandle(
      objectClass, L"HLAprivilegeToDeleteObject");
  require(privilegeToDelete.isValid(),
          "Resign-divestiture could not resolve HLAprivilegeToDeleteObject");

  rti::AttributeHandleSet ownerAttributes{attribute};
  rti::AttributeHandleSet peerAttributes{
      peer.rtiAmbassador().getAttributeHandle(
          peer.rtiAmbassador().getObjectClassHandle(options.objectClassName),
          options.attributeName)};
  require(peerAttributes.begin() != peerAttributes.end() &&
              peerAttributes.begin()->isValid(),
          "Resign-divestiture peer attribute lookup returned an invalid handle");
  owner.rtiAmbassador().publishObjectClassAttributes(objectClass, ownerAttributes);
  peer.rtiAmbassador().publishObjectClassAttributes(
      objectClass, peerAttributes);
  peer.rtiAmbassador().subscribeObjectClassAttributes(
      objectClass, peerAttributes);

  auto const object = owner.rtiAmbassador().registerObjectInstance(objectClass);
  require(object.isValid(), "Resign-divestiture registration returned an invalid handle");
  waitFor(peer, [&] { return peer.recorder().discovery().present; }, options,
          "resign-divestiture object discovery");
  require(peer.recorder().discovery().object == object,
          "Resign-divestiture discovery returned the wrong object");

  requireException(
      [&] { owner.resign(rti::NO_ACTION); },
      L"FederateOwnsAttributes",
      "resigning without divesting owned attributes");

  peer.recorder().clearOwnershipRecords();
  owner.resign(rti::UNCONDITIONALLY_DIVEST_ATTRIBUTES);
  waitFor(peer,
          [&] { return peer.recorder().ownershipAssumption().has_value(); },
          options,
          "resign-divestiture ownership assumption");
  auto const assumption = peer.recorder().ownershipAssumption();
  rti::AttributeHandleSet expectedDivestiture{
      *peerAttributes.begin(), privilegeToDelete};
  require(assumption->object == object &&
              assumption->attributes == expectedDivestiture && assumption->tag.empty(),
          "Resign-divestiture offered the wrong attributes or tag");

  std::vector<std::uint8_t> acquisitionTagBytes{0xD1U, 0x25U};
  rti::VariableLengthData acquisitionTag(
      acquisitionTagBytes.data(), acquisitionTagBytes.size());
  peer.recorder().clearOwnershipRecords();
  peer.rtiAmbassador().attributeOwnershipAcquisition(
      object, peerAttributes, acquisitionTag);
  waitFor(peer,
          [&] { return peer.recorder().ownershipAcquisition().has_value(); },
          options,
          "resign-divestiture acquisition notification");
  auto const acquisition = peer.recorder().ownershipAcquisition();
  require(acquisition->object == object &&
              acquisition->attributes == peerAttributes &&
              acquisition->tag == acquisitionTagBytes,
          "Resign-divestiture acquisition returned the wrong metadata");
  require(peer.rtiAmbassador().isAttributeOwnedByFederate(
              object, *peerAttributes.begin()),
          "Resign-divestiture peer did not acquire the value attribute");

  peer.resign(rti::UNCONDITIONALLY_DIVEST_ATTRIBUTES);
}

void scenarioResignUnconditionalDivestitureContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioResignUnconditionalDivestiture(options, model);
}

void scenarioAttributeUpdate(Options const& options, rti::CallbackModel model) {
  Session owner(options, model, "owner");
  Session member(options, model, "member");
  Session passive(options, model, "passive");
  auto const federation = federationName(options, "attribute-update");
  connectAndJoin(owner, member, options, federation, options.fom);
  passive.connect();
  passive.join(
      options.memberFederateName + L"-passive",
      options.federateType,
      federation);

  rti::ObjectClassHandle objectClass;
  rti::AttributeHandle attribute;
  rti::InteractionClassHandle interactionClass;
  rti::ParameterHandle parameter;
  handles(owner, options, objectClass, attribute, interactionClass, parameter);
  rti::AttributeHandleSet attributes;
  attributes.insert(attribute);
  owner.rtiAmbassador().publishObjectClassAttributes(objectClass, attributes);
  member.rtiAmbassador().subscribeObjectClassAttributes(objectClass, attributes, true, L"");
  auto const passiveClass = passive.rtiAmbassador().getObjectClassHandle(options.objectClassName);
  auto const passiveAttribute =
      passive.rtiAmbassador().getAttributeHandle(passiveClass, options.attributeName);
  require(passiveClass.isValid() && passiveAttribute.isValid(),
          "Passive attribute-update handle lookup returned an invalid handle");
  rti::AttributeHandleSet passiveAttributes;
  passiveAttributes.insert(passiveAttribute);
  passive.rtiAmbassador().subscribeObjectClassAttributes(
      passiveClass, passiveAttributes, false, L"");
  auto const object = owner.rtiAmbassador().registerObjectInstance(objectClass);
  require(object.isValid(), "Attribute update registration returned an invalid handle");
  waitFor(member, [&] { return member.recorder().discovery().present; }, options,
          "attribute update object discovery");
  for (int pass = 0; pass != 8; ++pass) {
    passive.pump();
  }
  auto const passiveDiscovery = passive.recorder().discovery();
  require(passiveDiscovery.present,
          "Passive object subscription did not receive active-relevance discovery");
  require(passiveDiscovery.object == object,
          "Passive discovery returned the wrong object handle");

  std::vector<std::uint8_t> value{0x10U, 0x20U, 0x30U};
  std::vector<std::uint8_t> tagBytes{0x54U, 0x43U, 0x4BU};
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
  rti::AttributeHandleValueMap values;
  values.emplace(attribute, rti::VariableLengthData(value.data(), value.size()));
  owner.rtiAmbassador().updateAttributeValues(object, values, tag);

  waitFor(member, [&] { return member.recorder().reflection().present; }, options,
          "ordinary attribute reflection");
  auto const reflected = member.recorder().reflection();
  require(reflected.object == object, "Reflection returned the wrong object handle");
  require(reflected.values.size() == 1U && reflected.values.count(attribute) == 1U,
          "Reflection returned the wrong attribute set");
  require(copyBytes(reflected.values.at(attribute)) == value,
          "Reflection returned the wrong attribute value");
  require(reflected.tag == tagBytes, "Reflection returned the wrong user tag");
  require(reflected.producer == owner.federateHandle(),
          "Reflection returned the wrong producing federate");
  require(reflected.transportation.isValid(),
          "Reflection returned an invalid transportation handle");
  for (int pass = 0; pass != 8; ++pass) {
    passive.pump();
  }
  auto const passiveReflection = passive.recorder().reflection();
  require(passiveReflection.present,
          "Passive object subscription did not receive active-relevance reflection");
  require(passiveReflection.object == object &&
              passiveReflection.values.size() == 1U &&
              passiveReflection.values.count(passiveAttribute) == 1U &&
              copyBytes(passiveReflection.values.at(passiveAttribute)) == value,
          "Passive reflection returned the wrong object or attribute value");
  require(passiveReflection.tag == tagBytes,
          "Passive reflection returned the wrong user tag");

  owner.resign(rti::DELETE_OBJECTS);
  member.resign(rti::NO_ACTION);
  passive.resign(rti::NO_ACTION);
}

void scenarioInteractionSubscriptionLifecycle(
    Options const& options,
    rti::CallbackModel model) {
  Session publisher(options, model, "publisher");
  Session subscriber(options, model, "subscriber");
  auto const federation = federationName(
      options,
      "interaction-subscription-lifecycle");
  connectAndJoin(publisher, subscriber, options, federation, options.fom);

  auto const publisherInteraction =
      publisher.rtiAmbassador().getInteractionClassHandle(
          options.interactionClassName);
  auto const subscriberInteraction =
      subscriber.rtiAmbassador().getInteractionClassHandle(
          options.interactionClassName);
  auto const publisherParameter = publisher.rtiAmbassador().getParameterHandle(
      publisherInteraction,
      options.parameterName);
  auto const subscriberParameter = subscriber.rtiAmbassador().getParameterHandle(
      subscriberInteraction,
      options.parameterName);
  require(
      publisherInteraction.isValid() && subscriberInteraction.isValid() &&
          publisherParameter.isValid() && subscriberParameter.isValid(),
      "interaction subscription lifecycle lookup returned an invalid handle");

  publisher.rtiAmbassador().publishInteractionClass(publisherInteraction);

  auto send = [&](std::vector<std::uint8_t> const& value,
                  std::vector<std::uint8_t> const& tagBytes) {
    rti::ParameterHandleValueMap parameters;
    parameters.emplace(
        publisherParameter,
        rti::VariableLengthData(value.data(), value.size()));
    rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
    publisher.rtiAmbassador().sendInteraction(
        publisherInteraction,
        parameters,
        tag);
  };

  // A passive declaration is retained but does not make the member eligible
  // for delivery. No callback should be queued for this interaction.
  subscriber.rtiAmbassador().subscribeInteractionClass(
      subscriberInteraction,
      false);
  std::vector<std::uint8_t> const passiveValue{0x50U, 0x41U, 0x53U};
  std::vector<std::uint8_t> const passiveTag{0x50U, 0x30U};
  send(passiveValue, passiveTag);
  for (int pass = 0; pass != 8; ++pass) {
    subscriber.pump();
  }
  require(
      !subscriber.recorder().interaction().present,
      "passive interaction subscription unexpectedly received an interaction");

  // Replacing the passive declaration with an active one enables ordinary
  // receive-order delivery, without replaying the earlier passive send.
  subscriber.rtiAmbassador().subscribeInteractionClass(
      subscriberInteraction,
      true);
  require(
      !subscriber.recorder().interaction().present,
      "activating an interaction subscription replayed a passive send");
  std::vector<std::uint8_t> const activeValue{0x41U, 0x43U, 0x54U};
  std::vector<std::uint8_t> const activeTag{0x41U, 0x31U};
  send(activeValue, activeTag);
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().interaction().present; },
      options,
      "active interaction subscription delivery");
  auto const received = subscriber.recorder().interaction();
  require(
      received.interaction == subscriberInteraction,
      "active interaction subscription returned the wrong class handle");
  require(
      received.parameters.size() == 1U &&
          received.parameters.count(subscriberParameter) == 1U,
      "active interaction subscription returned the wrong parameter set");
  require(
      copyBytes(received.parameters.at(subscriberParameter)) == activeValue,
      "active interaction subscription returned the wrong parameter value");
  require(
      received.tag == activeTag,
      "active interaction subscription returned the wrong user tag");
  require(
      received.producer == publisher.federateHandle(),
      "active interaction subscription returned the wrong producing federate");
  require(
      received.transportation.isValid(),
      "active interaction subscription returned an invalid transportation handle");

  // Downgrading an active declaration to passive suppresses later delivery.
  subscriber.recorder().clearInteraction();
  subscriber.rtiAmbassador().subscribeInteractionClass(
      subscriberInteraction,
      false);
  std::vector<std::uint8_t> const downgradedValue{0x44U, 0x4FU, 0x57U};
  std::vector<std::uint8_t> const downgradedTag{0x44U, 0x32U};
  send(downgradedValue, downgradedTag);
  for (int pass = 0; pass != 8; ++pass) {
    subscriber.pump();
  }
  require(
      !subscriber.recorder().interaction().present,
      "passive interaction downgrade did not suppress delivery");

  // Unsubscription removes the declaration entirely and remains a delivery
  // boundary for subsequent ordinary interactions.
  subscriber.rtiAmbassador().unsubscribeInteractionClass(subscriberInteraction);
  std::vector<std::uint8_t> const withdrawnValue{0x57U, 0x49U, 0x54U};
  std::vector<std::uint8_t> const withdrawnTag{0x57U, 0x33U};
  send(withdrawnValue, withdrawnTag);
  for (int pass = 0; pass != 8; ++pass) {
    subscriber.pump();
  }
  require(
      !subscriber.recorder().interaction().present,
      "unsubscribed interaction class unexpectedly received an interaction");

  subscriber.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  subscriber.disconnect();
  publisher.disconnect();
}

void scenarioInteractionPublicationSendFence(
    Options const& options,
    rti::CallbackModel model) {
  Session publisher(options, model, "publisher");
  Session subscriber(options, model, "subscriber");
  auto const federation = federationName(
      options,
      "interaction-publication-send-fence");
  connectAndJoin(publisher, subscriber, options, federation, options.fom);

  auto const publisherInteraction =
      publisher.rtiAmbassador().getInteractionClassHandle(
          options.interactionClassName);
  auto const subscriberInteraction =
      subscriber.rtiAmbassador().getInteractionClassHandle(
          options.interactionClassName);
  auto const publisherParameter = publisher.rtiAmbassador().getParameterHandle(
      publisherInteraction,
      options.parameterName);
  auto const subscriberParameter = subscriber.rtiAmbassador().getParameterHandle(
      subscriberInteraction,
      options.parameterName);
  require(
      publisherInteraction.isValid() && subscriberInteraction.isValid() &&
          publisherParameter.isValid() && subscriberParameter.isValid(),
      "interaction publication send fence lookup returned an invalid handle");

  publisher.rtiAmbassador().publishInteractionClass(publisherInteraction);
  subscriber.rtiAmbassador().subscribeInteractionClass(
      subscriberInteraction,
      true);
  publisher.rtiAmbassador().unpublishInteractionClass(publisherInteraction);

  std::vector<std::uint8_t> const fencedValue{
      0x46U, 0x45U, 0x4EU, 0x43U, 0x45U};
  std::vector<std::uint8_t> const fencedTag{0x50U, 0x55U, 0x42U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherParameter,
      rti::VariableLengthData(fencedValue.data(), fencedValue.size()));
  rti::VariableLengthData fencedTagData(fencedTag.data(), fencedTag.size());
  requireException(
      [&] {
        publisher.rtiAmbassador().sendInteraction(
            publisherInteraction,
            parameters,
            fencedTagData);
      },
      L"InteractionClassNotPublished",
      "sending an interaction after unpublication");
  require(
      !subscriber.recorder().interaction().present,
      "unpublished interaction unexpectedly delivered a callback");

  publisher.rtiAmbassador().publishInteractionClass(publisherInteraction);
  std::vector<std::uint8_t> const restoredValue{
      0x52U, 0x45U, 0x53U, 0x54U, 0x4FU, 0x52U, 0x45U};
  std::vector<std::uint8_t> const restoredTag{0x52U, 0x45U, 0x50U};
  rti::ParameterHandleValueMap restoredParameters;
  restoredParameters.emplace(
      publisherParameter,
      rti::VariableLengthData(restoredValue.data(), restoredValue.size()));
  rti::VariableLengthData restoredTagData(restoredTag.data(), restoredTag.size());
  publisher.rtiAmbassador().sendInteraction(
      publisherInteraction,
      restoredParameters,
      restoredTagData);
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().interaction().present; },
      options,
      "interaction publication send fence delivery after republication");
  auto const received = subscriber.recorder().interaction();
  require(
      received.interaction == subscriberInteraction,
      "interaction publication send fence returned the wrong class handle");
  require(
      received.parameters.size() == 1U &&
          received.parameters.count(subscriberParameter) == 1U &&
          copyBytes(received.parameters.at(subscriberParameter)) == restoredValue,
      "interaction publication send fence returned the wrong parameter value");
  require(
      received.tag == restoredTag &&
          received.producer == publisher.federateHandle() &&
          received.transportation.isValid(),
      "interaction publication send fence returned the wrong delivery metadata");

  subscriber.rtiAmbassador().unsubscribeInteractionClass(subscriberInteraction);
  publisher.rtiAmbassador().unpublishInteractionClass(publisherInteraction);
  subscriber.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  subscriber.disconnect();
  publisher.disconnect();
}

void scenarioInteraction(Options const& options, rti::CallbackModel model) {
  Session interactionLifecycle(options, model, "interaction-lifecycle");
  rti::InteractionClassHandle const invalidInteractionClass;
  rti::ParameterHandleValueMap const emptyParameters;
  rti::VariableLengthData const emptyInteractionTag;
  auto requireInteractionLifecycle = [&](std::wstring const& expected,
                                         std::string const& phase) {
    requireException(
        [&] {
          interactionLifecycle.rtiAmbassador().sendInteraction(
              invalidInteractionClass,
              emptyParameters,
              emptyInteractionTag);
        },
        expected,
        "sending an interaction " + phase);
  };
  requireInteractionLifecycle(L"NotConnected", "before connect");
  interactionLifecycle.connect();
  requireInteractionLifecycle(L"FederateNotExecutionMember", "after connect before join");
  interactionLifecycle.disconnect();

  Session owner(options, model, "owner");
  Session member(options, model, "member");
  Session passive(options, model, "passive");
  auto const federation = federationName(options, "interaction");
  connectAndJoin(owner, member, options, federation, options.fom);
  passive.connect();
  passive.join(
      options.memberFederateName + L"-passive",
      options.federateType,
      federation);

  rti::ObjectClassHandle objectClass;
  rti::AttributeHandle attribute;
  rti::InteractionClassHandle interactionClass;
  rti::ParameterHandle parameter;
  handles(owner, options, objectClass, attribute, interactionClass, parameter);
  owner.rtiAmbassador().publishInteractionClass(interactionClass);
  member.rtiAmbassador().subscribeInteractionClass(interactionClass, true);
  auto const passiveInteraction =
      passive.rtiAmbassador().getInteractionClassHandle(options.interactionClassName);
  require(passiveInteraction.isValid(),
          "Passive interaction handle lookup returned an invalid handle");
  passive.rtiAmbassador().subscribeInteractionClass(passiveInteraction, false);
  requireException(
      [&] {
        owner.rtiAmbassador().sendInteraction(
            invalidInteractionClass,
            rti::ParameterHandleValueMap{},
            rti::VariableLengthData{});
      },
      L"InteractionClassNotDefined",
      "ordinary interaction send with an invalid interaction class");

  std::vector<std::uint8_t> value{0x42U, 0x11U};
  std::vector<std::uint8_t> tagBytes{0x49U, 0x4EU, 0x54U};
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(parameter, rti::VariableLengthData(value.data(), value.size()));
  owner.rtiAmbassador().sendInteraction(interactionClass, parameters, tag);

  waitFor(member, [&] { return member.recorder().interaction().present; }, options,
          "ordinary interaction delivery");
  auto const received = member.recorder().interaction();
  require(received.interaction == interactionClass,
          "Interaction delivery returned the wrong class handle");
  require(received.parameters.size() == 1U && received.parameters.count(parameter) == 1U,
          "Interaction delivery returned the wrong parameter set");
  require(copyBytes(received.parameters.at(parameter)) == value,
          "Interaction delivery returned the wrong parameter value");
  require(received.tag == tagBytes, "Interaction delivery returned the wrong user tag");
  require(received.producer == owner.federateHandle(),
          "Interaction delivery returned the wrong producing federate");
  require(received.transportation.isValid(),
          "Interaction delivery returned an invalid transportation handle");
  for (int pass = 0; pass != 8; ++pass) {
    passive.pump();
  }
  auto const passiveReceived = passive.recorder().interaction();
  require(passiveReceived.present,
          "Passive interaction subscription did not receive active-relevance delivery");
  require(passiveReceived.interaction == passiveInteraction &&
              passiveReceived.parameters.size() == 1U &&
              passiveReceived.parameters.count(parameter) == 1U &&
              copyBytes(passiveReceived.parameters.at(parameter)) == value,
          "Passive interaction delivery returned the wrong class or parameter value");
  require(passiveReceived.tag == tagBytes,
          "Passive interaction delivery returned the wrong user tag");

  owner.resign(rti::NO_ACTION);
  member.resign(rti::NO_ACTION);
  passive.resign(rti::NO_ACTION);
}

void scenarioInteractionMultiRecipientFifo(
    Options const& options,
    rti::CallbackModel model) {
  Session publisher(options, model, "ordinary-interaction-fanout-publisher");
  Session first(options, model, "ordinary-interaction-fanout-first");
  Session second(options, model, "ordinary-interaction-fanout-second");
  auto const federation = federationName(
      options,
      "ordinary-interaction-multi-recipient-fifo");
  connectAndJoin(publisher, first, options, federation, options.fom);
  second.connect();
  second.join(
      options.memberFederateName + L"-second",
      options.federateType,
      federation);

  auto const publisherInteraction =
      publisher.rtiAmbassador().getInteractionClassHandle(
          options.interactionClassName);
  auto const firstInteraction =
      first.rtiAmbassador().getInteractionClassHandle(
          options.interactionClassName);
  auto const secondInteraction =
      second.rtiAmbassador().getInteractionClassHandle(
          options.interactionClassName);
  auto const publisherParameter = publisher.rtiAmbassador().getParameterHandle(
      publisherInteraction,
      options.parameterName);
  auto const firstParameter = first.rtiAmbassador().getParameterHandle(
      firstInteraction,
      options.parameterName);
  auto const secondParameter = second.rtiAmbassador().getParameterHandle(
      secondInteraction,
      options.parameterName);
  require(
      publisherInteraction.isValid() && firstInteraction.isValid() &&
          secondInteraction.isValid() && publisherParameter.isValid() &&
          firstParameter.isValid() && secondParameter.isValid(),
      "ordinary interaction multi-recipient FIFO lookup returned an invalid handle");

  publisher.rtiAmbassador().publishInteractionClass(publisherInteraction);
  first.rtiAmbassador().subscribeInteractionClass(firstInteraction, true);
  second.rtiAmbassador().subscribeInteractionClass(secondInteraction, true);
  publisher.recorder().clearInteraction();
  first.recorder().clearInteraction();
  second.recorder().clearInteraction();

  auto send = [&](std::vector<std::uint8_t> const& value,
                  std::vector<std::uint8_t> const& tagBytes) {
    rti::ParameterHandleValueMap parameters;
    parameters.emplace(
        publisherParameter,
        rti::VariableLengthData(value.data(), value.size()));
    rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
    publisher.rtiAmbassador().sendInteraction(
        publisherInteraction,
        parameters,
        tag);
  };

  std::vector<std::uint8_t> const firstValue{
      0x46U, 0x49U, 0x52U, 0x53U, 0x54U};
  std::vector<std::uint8_t> const firstTag{0x31U};
  std::vector<std::uint8_t> const secondValue{
      0x53U, 0x45U, 0x43U, 0x4FU, 0x4EU, 0x44U};
  std::vector<std::uint8_t> const secondTag{0x32U};
  send(firstValue, firstTag);
  send(secondValue, secondTag);

  waitForSessions(
      {&first, &second},
      [&] {
        return first.recorder().interactions().size() >= 2U &&
            second.recorder().interactions().size() >= 2U;
      },
      options,
      "ordinary interaction multi-recipient FIFO delivery");
  require(
      publisher.recorder().interactions().empty(),
      "ordinary interaction multi-recipient FIFO delivered an interaction back to its sender");

  auto assertDelivery = [&](Session& receiver,
                            rti::InteractionClassHandle const& interaction,
                            rti::ParameterHandle const& parameter,
                            std::string const& description) {
    auto const received = receiver.recorder().interactions();
    require(
        received.size() == 2U,
        description + " returned an unexpected callback count");
    auto assertRecord = [&](InteractionRecord const& record,
                            std::vector<std::uint8_t> const& expectedValue,
                            std::vector<std::uint8_t> const& expectedTag,
                            std::string const& orderDescription) {
      require(
          record.interaction == interaction && record.parameters.size() == 1U &&
              record.parameters.count(parameter) == 1U &&
              copyBytes(record.parameters.at(parameter)) == expectedValue,
          orderDescription + " returned the wrong interaction or parameter value");
      require(
          record.tag == expectedTag,
          orderDescription + " returned the wrong user tag");
      require(
          record.producer == publisher.federateHandle(),
          orderDescription + " returned the wrong producing federate");
      require(
          record.transportation.isValid() &&
              !receiver.rtiAmbassador()
                   .getTransportationTypeName(record.transportation)
                   .empty(),
          orderDescription + " returned an unknown transportation type");
    };
    assertRecord(
        received.front(),
        firstValue,
        firstTag,
        description + " first receive-order callback");
    assertRecord(
        received.back(),
        secondValue,
        secondTag,
        description + " second receive-order callback");
  };
  assertDelivery(
      first,
      firstInteraction,
      firstParameter,
      "first ordinary interaction recipient");
  assertDelivery(
      second,
      secondInteraction,
      secondParameter,
      "second ordinary interaction recipient");

  first.rtiAmbassador().unsubscribeInteractionClass(firstInteraction);
  second.rtiAmbassador().unsubscribeInteractionClass(secondInteraction);
  publisher.rtiAmbassador().unpublishInteractionClass(publisherInteraction);
  second.resign(rti::NO_ACTION);
  first.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  second.disconnect();
  first.disconnect();
  publisher.disconnect();
}

void scenarioAttributeMultiRecipientFifo(
    Options const& options,
    rti::CallbackModel model) {
  Session publisher(options, model, "ordinary-attribute-fanout-publisher");
  Session first(options, model, "ordinary-attribute-fanout-first");
  Session second(options, model, "ordinary-attribute-fanout-second");
  auto const federation = federationName(
      options,
      "ordinary-attribute-multi-recipient-fifo");
  connectAndJoin(publisher, first, options, federation, options.fom);
  second.connect();
  second.join(
      options.memberFederateName + L"-second",
      options.federateType,
      federation);

  auto const publisherClass = publisher.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const firstClass = first.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const secondClass = second.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const publisherAttribute = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass,
      options.attributeName);
  auto const firstAttribute = first.rtiAmbassador().getAttributeHandle(
      firstClass,
      options.attributeName);
  auto const secondAttribute = second.rtiAmbassador().getAttributeHandle(
      secondClass,
      options.attributeName);
  require(
      publisherClass.isValid() && firstClass.isValid() && secondClass.isValid() &&
          publisherAttribute.isValid() && firstAttribute.isValid() &&
          secondAttribute.isValid(),
      "ordinary attribute multi-recipient FIFO lookup returned an invalid handle");

  rti::AttributeHandleSet publisherAttributes{publisherAttribute};
  rti::AttributeHandleSet firstAttributes{firstAttribute};
  rti::AttributeHandleSet secondAttributes{secondAttribute};
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  first.rtiAmbassador().subscribeObjectClassAttributes(
      firstClass,
      firstAttributes,
      true,
      L"");
  second.rtiAmbassador().subscribeObjectClassAttributes(
      secondClass,
      secondAttributes,
      true,
      L"");

  auto const object = publisher.rtiAmbassador().registerObjectInstance(publisherClass);
  require(
      object.isValid(),
      "ordinary attribute multi-recipient FIFO registration returned an invalid object");
  waitForSessions(
      {&first, &second},
      [&] {
        return first.recorder().hasDiscovery(object) &&
            second.recorder().hasDiscovery(object);
      },
      options,
      "ordinary attribute multi-recipient FIFO discovery");
  first.recorder().clearReflection();
  second.recorder().clearReflection();

  auto send = [&](std::vector<std::uint8_t> const& value,
                  std::vector<std::uint8_t> const& tagBytes) {
    rti::AttributeHandleValueMap values;
    values.emplace(
        publisherAttribute,
        rti::VariableLengthData(value.data(), value.size()));
    rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
    publisher.rtiAmbassador().updateAttributeValues(object, values, tag);
  };

  std::vector<std::uint8_t> const firstValue{
      0x46U, 0x49U, 0x52U, 0x53U, 0x54U};
  std::vector<std::uint8_t> const firstTag{0x31U};
  std::vector<std::uint8_t> const secondValue{
      0x53U, 0x45U, 0x43U, 0x4FU, 0x4EU, 0x44U};
  std::vector<std::uint8_t> const secondTag{0x32U};
  send(firstValue, firstTag);
  send(secondValue, secondTag);

  waitForSessions(
      {&first, &second},
      [&] {
        return first.recorder().reflections().size() >= 2U &&
            second.recorder().reflections().size() >= 2U;
      },
      options,
      "ordinary attribute multi-recipient FIFO delivery");
  require(
      publisher.recorder().reflections().empty(),
      "ordinary attribute multi-recipient FIFO delivered a reflection back to its owner");

  auto assertDelivery = [&](Session& receiver,
                            rti::ObjectClassHandle const& objectClass,
                            rti::AttributeHandle const& attribute,
                            std::string const& description) {
    auto const discovery = receiver.recorder().discovery();
    require(
        discovery.present && discovery.object == object &&
            discovery.objectClass == objectClass &&
            discovery.producer == publisher.federateHandle(),
        description + " returned the wrong discovery metadata");
    auto const received = receiver.recorder().reflections();
    require(
        received.size() == 2U,
        description + " returned an unexpected callback count");
    auto assertRecord = [&](ReflectionRecord const& record,
                            std::vector<std::uint8_t> const& expectedValue,
                            std::vector<std::uint8_t> const& expectedTag,
                            std::string const& orderDescription) {
      require(
          record.object == object && record.values.size() == 1U &&
              record.values.count(attribute) == 1U &&
              copyBytes(record.values.at(attribute)) == expectedValue,
          orderDescription + " returned the wrong object or attribute value");
      require(
          record.tag == expectedTag,
          orderDescription + " returned the wrong user tag");
      require(
          record.producer == publisher.federateHandle(),
          orderDescription + " returned the wrong producing federate");
      require(
          record.transportation.isValid() &&
              !receiver.rtiAmbassador()
                   .getTransportationTypeName(record.transportation)
                   .empty(),
          orderDescription + " returned an unknown transportation type");
    };
    assertRecord(
        received.front(),
        firstValue,
        firstTag,
        description + " first receive-order reflection");
    assertRecord(
        received.back(),
        secondValue,
        secondTag,
        description + " second receive-order reflection");
  };
  assertDelivery(
      first,
      firstClass,
      firstAttribute,
      "first ordinary attribute recipient");
  assertDelivery(
      second,
      secondClass,
      secondAttribute,
      "second ordinary attribute recipient");

  first.rtiAmbassador().unsubscribeObjectClassAttributes(
      firstClass,
      firstAttributes);
  second.rtiAmbassador().unsubscribeObjectClassAttributes(
      secondClass,
      secondAttributes);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  second.resign(rti::NO_ACTION);
  first.resign(rti::NO_ACTION);
  publisher.resign(rti::DELETE_OBJECTS);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  second.disconnect();
  first.disconnect();
  publisher.disconnect();
}

void scenarioTimestampedInteractions(Options const& options, rti::CallbackModel model) {
  Session publisher(options, model, "owner");
  Session immediate(options, model, "member");
  Session constrained(options, model, "member");
  auto const federation = federationName(options, "timestamped-interactions");
  connectAndJoin(publisher, immediate, options, federation, options.fom);
  constrained.connect();
  constrained.join(
      options.memberFederateName + L"-timestamped-constrained",
      options.federateType,
      federation);

  rti::InteractionClassHandle publisherInteraction;
  rti::InteractionClassHandle immediateInteraction;
  rti::InteractionClassHandle constrainedInteraction;
  rti::ParameterHandle publisherParameter;
  rti::ParameterHandle immediateParameter;
  rti::ParameterHandle constrainedParameter;
  publisherInteraction = publisher.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  immediateInteraction = immediate.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  constrainedInteraction = constrained.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  publisherParameter = publisher.rtiAmbassador().getParameterHandle(
      publisherInteraction, options.parameterName);
  immediateParameter = immediate.rtiAmbassador().getParameterHandle(
      immediateInteraction, options.parameterName);
  constrainedParameter = constrained.rtiAmbassador().getParameterHandle(
      constrainedInteraction, options.parameterName);
  require(
      publisherInteraction.isValid() && immediateInteraction.isValid() &&
          constrainedInteraction.isValid(),
      "timestamped interaction lookup returned an invalid class handle");
  require(
      publisherParameter.isValid() && immediateParameter.isValid() &&
          constrainedParameter.isValid(),
      "timestamped interaction lookup returned an invalid parameter handle");

  publisher.rtiAmbassador().publishInteractionClass(publisherInteraction);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherInteraction, rti::TIMESTAMP);
  immediate.rtiAmbassador().subscribeInteractionClass(immediateInteraction, true);
  constrained.rtiAmbassador().subscribeInteractionClass(constrainedInteraction, true);

  auto publisherTime = makeTimeContext(publisher);
  auto constrainedTime = makeTimeContext(constrained);
  require(
      publisherTime.factory->getName() == constrainedTime.factory->getName(),
      "timestamped interaction members selected different logical-time factories");
  constrained.rtiAmbassador().enableTimeConstrained();
  waitFor(
      constrained,
      [&] { return constrained.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "timestamped interaction time-constrained callback");
  publisher.rtiAmbassador().enableTimeRegulation(*publisherTime.epsilon);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timestamped interaction time-regulation callback");
  rti::MessageRetractionHandle const invalidRetraction;
  requireException(
      [&] { publisher.rtiAmbassador().retract(invalidRetraction); },
      L"InvalidMessageRetractionHandle",
      "timestamped interaction retract with an invalid handle");
  rti::InteractionClassHandle const invalidInteractionClass;
  auto const invalidInteractionTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      3U);
  requireException(
      [&] {
        publisher.rtiAmbassador().sendInteraction(
            invalidInteractionClass,
            rti::ParameterHandleValueMap{},
            rti::VariableLengthData{},
            *invalidInteractionTime);
      },
      L"InteractionClassNotDefined",
      "timestamped interaction send with an invalid interaction class");

  auto assertInteraction = [&](TimedInteractionRecord const& record,
                               rti::InteractionClassHandle const& expectedInteraction,
                               rti::ParameterHandle const& expectedParameter,
                               std::vector<std::uint8_t> const& expectedValue,
                               std::vector<std::uint8_t> const& expectedTag,
                               std::vector<std::uint8_t> const& expectedTime,
                               rti::FederateHandle const& expectedProducer,
                               rti::OrderType expectedReceivedOrder,
                               Session& inspector) {
    require(record.interaction == expectedInteraction,
            "timestamped interaction callback returned the wrong class handle");
    require(record.parameters.size() == 1U &&
                record.parameters.count(expectedParameter) == 1U,
            "timestamped interaction callback returned the wrong parameter set");
    require(copyBytes(record.parameters.at(expectedParameter)) == expectedValue,
            "timestamped interaction callback returned the wrong parameter value");
    require(record.tag == expectedTag,
            "timestamped interaction callback did not preserve the user tag");
    require(record.producer == expectedProducer,
            "timestamped interaction callback returned the wrong producing federate");
    require(record.transportation.isValid() && !inspector.rtiAmbassador()
                .getTransportationTypeName(record.transportation).empty(),
            "timestamped interaction callback returned an unresolvable transportation type");
    require(record.time == expectedTime,
            "timestamped interaction callback returned the wrong logical time");
    require(!record.timeText.empty(),
            "timestamped interaction callback returned no logical-time representation");
    require(record.sentOrder == rti::TIMESTAMP,
            "timestamped interaction callback returned a non-timestamp sent order");
    require(record.receivedOrder == expectedReceivedOrder,
            "timestamped interaction callback returned the wrong received order");
  };

  auto firstTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      3U);
  auto firstConstrainedTime = timeAfter(
      *constrainedTime.factory,
      *constrainedTime.initial,
      *constrainedTime.epsilon,
      3U);
  std::vector<std::uint8_t> firstValueBytes{0x01U, 0x02U, 0x03U};
  std::vector<std::uint8_t> firstTagBytes{0x11U, 0x12U};
  rti::ParameterHandleValueMap firstParameters;
  firstParameters.emplace(
      publisherParameter,
      rti::VariableLengthData(firstValueBytes.data(), firstValueBytes.size()));
  rti::VariableLengthData firstTag(firstTagBytes.data(), firstTagBytes.size());
  auto firstRetraction = publisher.rtiAmbassador().sendInteraction(
      publisherInteraction,
      firstParameters,
      firstTag,
      *firstTime);
  require(firstRetraction.isValid(),
          "timestamped interaction send returned an invalid retraction handle");
  waitFor(
      immediate,
      [&] { return immediate.recorder().timedInteractions().size() >= 1U; },
      options,
      "non-constrained timestamped interaction delivery");
  auto const firstImmediate = immediate.recorder().timedInteractions();
  require(firstImmediate.size() == 1U,
          "non-constrained recipient received duplicate timestamped interaction delivery");
  assertInteraction(
      firstImmediate.front(),
      immediateInteraction,
      immediateParameter,
      firstValueBytes,
      firstTagBytes,
      encodeTime(*firstTime),
      publisher.federateHandle(),
      rti::RECEIVE,
      immediate);
  require(firstImmediate.front().retractionPresent,
          "timestamped interaction callback omitted its retraction handle");
  require(firstImmediate.front().retraction == copyBytes(firstRetraction.encode()),
          "timestamped interaction callback returned the wrong retraction handle");
  require(constrained.recorder().timedInteractions().empty(),
          "time-constrained recipient received a timestamped interaction before its grant");

  publisher.rtiAmbassador().retract(firstRetraction);
  waitFor(
      immediate,
      [&] { return immediate.recorder().retractions().size() >= 1U; },
      options,
      "retraction callback for delivered timestamped interaction");
  auto const firstRetractionCallbacks = immediate.recorder().retractions();
  require(firstRetractionCallbacks.size() == 1U,
          "delivered timestamped interaction produced duplicate retraction callbacks");
  require(firstRetractionCallbacks.front().valid &&
              firstRetractionCallbacks.front().encoded == copyBytes(firstRetraction.encode()),
          "retraction callback returned the wrong message handle");
  require(constrained.recorder().retractions().empty(),
          "pending timestamped interaction produced a retraction callback before delivery");

  constrained.rtiAmbassador().timeAdvanceRequest(*firstConstrainedTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*firstTime);
  waitFor(
      publisher,
      constrained,
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 1U &&
            constrained.recorder().timeAdvanceGrants().size() >= 1U;
      },
      options,
      "first timestamped interaction time advance grants");
  for (int pass = 0; pass != 8; ++pass) {
    constrained.pump();
  }
  require(constrained.recorder().timedInteractions().empty(),
          "retracted timestamped interaction was delivered at its grant");
  require(constrained.recorder().retractions().empty(),
          "retracted pending timestamped interaction produced a stale retraction callback");

  auto secondTime = timeAfter(
      *publisherTime.factory,
      *firstTime,
      *publisherTime.epsilon,
      3U);
  auto secondConstrainedTime = timeAfter(
      *constrainedTime.factory,
      *firstConstrainedTime,
      *constrainedTime.epsilon,
      3U);
  std::vector<std::uint8_t> secondValueBytes{0x21U, 0x22U, 0x23U};
  std::vector<std::uint8_t> secondTagBytes{0x31U, 0x32U};
  rti::ParameterHandleValueMap secondParameters;
  secondParameters.emplace(
      publisherParameter,
      rti::VariableLengthData(secondValueBytes.data(), secondValueBytes.size()));
  rti::VariableLengthData secondTag(secondTagBytes.data(), secondTagBytes.size());
  auto secondRetraction = publisher.rtiAmbassador().sendInteraction(
      publisherInteraction,
      secondParameters,
      secondTag,
      *secondTime);
  require(secondRetraction.isValid(),
          "second timestamped interaction send returned an invalid retraction handle");
  waitFor(
      immediate,
      [&] { return immediate.recorder().timedInteractions().size() >= 2U; },
      options,
      "second non-constrained timestamped interaction delivery");
  auto const secondImmediate = immediate.recorder().timedInteractions();
  require(secondImmediate.size() == 2U,
          "non-constrained recipient received duplicate second timestamped interaction delivery");
  assertInteraction(
      secondImmediate.at(1),
      immediateInteraction,
      immediateParameter,
      secondValueBytes,
      secondTagBytes,
      encodeTime(*secondTime),
      publisher.federateHandle(),
      rti::RECEIVE,
      immediate);
  require(secondImmediate.at(1).retractionPresent,
          "second timestamped interaction callback omitted its retraction handle");
  require(secondImmediate.at(1).retraction == copyBytes(secondRetraction.encode()),
          "second timestamped interaction callback returned the wrong retraction handle");

  constrained.rtiAmbassador().timeAdvanceRequest(*secondConstrainedTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*secondTime);
  waitFor(
      publisher,
      constrained,
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 2U &&
            constrained.recorder().timeAdvanceGrants().size() >= 2U &&
            constrained.recorder().timedInteractions().size() >= 1U;
      },
      options,
      "second timestamped interaction delivery and time advance grants");
  auto const constrainedInteractions = constrained.recorder().timedInteractions();
  require(constrainedInteractions.size() == 1U,
          "time-constrained recipient received the wrong number of timestamped interactions");
  assertInteraction(
      constrainedInteractions.front(),
      constrainedInteraction,
      constrainedParameter,
      secondValueBytes,
      secondTagBytes,
      encodeTime(*secondTime),
      publisher.federateHandle(),
      rti::TIMESTAMP,
      constrained);
  require(constrainedInteractions.front().retractionPresent,
          "time-constrained timestamped interaction callback omitted its retraction handle");
  require(constrainedInteractions.front().retraction == copyBytes(secondRetraction.encode()),
          "time-constrained timestamped interaction callback returned the wrong retraction handle");

  auto const immediateRetractions = immediate.recorder().retractions();
  auto const constrainedRetractions = constrained.recorder().retractions();
  require(immediateRetractions.size() == 1U && constrainedRetractions.empty(),
          "second timestamped interaction changed retraction state unexpectedly");
  requireException(
      [&] { publisher.rtiAmbassador().retract(secondRetraction); },
      L"MessageCanNoLongerBeRetracted",
      "retracting a delivered timestamped interaction at the producer boundary");

  constrained.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  immediate.rtiAmbassador().unsubscribeInteractionClass(immediateInteraction);
  constrained.rtiAmbassador().unsubscribeInteractionClass(constrainedInteraction);
  publisher.rtiAmbassador().unpublishInteractionClass(publisherInteraction);
  constrained.resign(rti::NO_ACTION);
  immediate.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  constrained.disconnect();
  immediate.disconnect();
  publisher.disconnect();
}

void scenarioTimestampedInteractionRegulationReenable(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timestamped interaction regulation re-enable requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session receiver(options, model, "constrained");
  auto const federation = federationName(
      options,
      "timestamped-interaction-regulation-reenable");
  connectAndJoin(publisher, receiver, options, federation, options.fom);

  auto const publisherInteraction = publisher.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const receiverInteraction = receiver.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const publisherParameter = publisher.rtiAmbassador().getParameterHandle(
      publisherInteraction,
      options.parameterName);
  auto const receiverParameter = receiver.rtiAmbassador().getParameterHandle(
      receiverInteraction,
      options.parameterName);
  require(
      publisherInteraction.isValid() && receiverInteraction.isValid() &&
          publisherParameter.isValid() && receiverParameter.isValid(),
      "timestamped interaction regulation re-enable lookup returned an invalid handle");
  publisher.rtiAmbassador().publishInteractionClass(publisherInteraction);
  receiver.rtiAmbassador().subscribeInteractionClass(receiverInteraction, true);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherInteraction,
      rti::TIMESTAMP);

  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  require(
      publisherTime.factory->getName() == receiverTime.factory->getName(),
      "timestamped interaction regulation re-enable members selected different logical-time factories");
  enableTimestampedRoles(
      publisher,
      receiver,
      publisherTime,
      receiverTime,
      options,
      "timestamped interaction regulation re-enable");

  auto const updateTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      5U);
  auto const publisherTarget = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      2U);
  auto const changedLookaheadTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      3U);
  auto changedLookahead = publisherTime.factory->makeZero();
  require(
      changedLookahead != nullptr,
      "timestamped interaction regulation re-enable could not allocate the changed lookahead");
  changedLookahead->setToDifference(
      *changedLookaheadTime,
      *publisherTime.initial);

  std::vector<std::uint8_t> parameterBytes{0xD1U, 0x5AU};
  std::vector<std::uint8_t> tagBytes{0x43U, 0x48U, 0x47U, 0x4CU};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherParameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
  auto const retraction = publisher.rtiAmbassador().sendInteraction(
      publisherInteraction,
      parameters,
      tag,
      *updateTime);
  require(
      retraction.isValid(),
      "timestamped interaction regulation re-enable send returned an invalid retraction handle");
  require(
      receiver.recorder().timedInteractions().empty(),
      "timestamped interaction regulation re-enable delivered before its grant");

  publisher.rtiAmbassador().disableTimeRegulation();
  publisher.rtiAmbassador().enableTimeRegulation(*changedLookahead);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 2U; },
      options,
      "timestamped interaction regulation re-enable callback");
  auto queriedLookahead = publisherTime.factory->makeZero();
  require(
      queriedLookahead != nullptr,
      "timestamped interaction regulation re-enable could not allocate a lookahead query");
  publisher.rtiAmbassador().queryLookahead(*queriedLookahead);
  require(
      *queriedLookahead == *changedLookahead,
      "timestamped interaction regulation re-enable did not expose the changed lookahead");

  receiver.recorder().clearCallbackOrder();
  publisher.recorder().clearCallbackOrder();
  receiver.rtiAmbassador().timeAdvanceRequest(*updateTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*publisherTarget);
  waitFor(
      publisher,
      receiver,
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 1U &&
            receiver.recorder().timeAdvanceGrants().size() >= 1U &&
            receiver.recorder().timedInteractions().size() >= 1U;
      },
      options,
      "timestamped interaction regulation re-enable delivery");
  auto const interactions = receiver.recorder().timedInteractions();
  require(
      interactions.size() == 1U &&
          publisher.recorder().timeRegulationEnabled().size() == 2U,
      "timestamped interaction regulation re-enable returned the wrong callback counts");
  require(
      receiver.recorder().callbackOrder() == std::vector<std::string>{"interaction", "grant"},
      "timestamped interaction regulation re-enable delivered after its grant");
  auto const& interaction = interactions.front();
  require(
      interaction.interaction == receiverInteraction &&
          interaction.parameters.size() == 1U &&
          interaction.parameters.count(receiverParameter) == 1U &&
          copyBytes(interaction.parameters.at(receiverParameter)) == parameterBytes,
      "timestamped interaction regulation re-enable returned the wrong class or parameter");
  require(
      interaction.tag == tagBytes && interaction.time == encodeTime(*updateTime) &&
          !interaction.timeText.empty(),
      "timestamped interaction regulation re-enable did not preserve value metadata");
  require(
      interaction.producer == publisher.federateHandle() &&
          interaction.sentOrder == rti::TIMESTAMP &&
          interaction.receivedOrder == rti::TIMESTAMP,
      "timestamped interaction regulation re-enable returned the wrong producer or order");
  require(
      interaction.transportation.isValid() &&
          !receiver.rtiAmbassador().getTransportationTypeName(interaction.transportation).empty(),
      "timestamped interaction regulation re-enable returned an unresolvable transport");
  require(
      !interaction.regions.has_value(),
      "timestamped interaction regulation re-enable unexpectedly supplied source regions");
  require(
      interaction.retractionPresent && interaction.retraction == copyBytes(retraction.encode()),
      "timestamped interaction regulation re-enable omitted the retraction handle");
  require(
      publisher.recorder().timeAdvanceGrants().front().encoded == encodeTime(*publisherTarget),
      "timestamped interaction regulation re-enable returned the wrong producer grant");
  require(
      receiver.recorder().timeAdvanceGrants().front().encoded == encodeTime(*updateTime),
      "timestamped interaction regulation re-enable returned the wrong receiver grant");
  requireException(
      [&] { publisher.rtiAmbassador().retract(retraction); },
      L"MessageCanNoLongerBeRetracted",
      "timestamped interaction regulation re-enable retraction after delivery");

  receiver.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeInteractionClass(receiverInteraction);
  publisher.rtiAmbassador().unpublishInteractionClass(publisherInteraction);
  receiver.resign(rti::NO_ACTION);
  publisher.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

void scenarioTimestampedInteractionReenable(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timestamped interaction re-enable requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session receiver(options, model, "constrained");
  auto const federation = federationName(
      options,
      "timestamped-interaction-reenable");
  connectAndJoin(publisher, receiver, options, federation, options.fom);

  auto const publisherInteraction = publisher.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const receiverInteraction = receiver.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const publisherParameter = publisher.rtiAmbassador().getParameterHandle(
      publisherInteraction,
      options.parameterName);
  auto const receiverParameter = receiver.rtiAmbassador().getParameterHandle(
      receiverInteraction,
      options.parameterName);
  require(
      publisherInteraction.isValid() && receiverInteraction.isValid() &&
          publisherParameter.isValid() && receiverParameter.isValid(),
      "timestamped interaction re-enable lookup returned an invalid handle");
  publisher.rtiAmbassador().publishInteractionClass(publisherInteraction);
  receiver.rtiAmbassador().subscribeInteractionClass(receiverInteraction, true);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherInteraction,
      rti::TIMESTAMP);

  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  require(
      publisherTime.factory->getName() == receiverTime.factory->getName(),
      "timestamped interaction re-enable members selected different logical-time factories");
  auto const lookaheadTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      1U);
  auto lookahead = publisherTime.factory->makeZero();
  require(
      lookahead != nullptr,
      "timestamped interaction re-enable could not allocate a lookahead interval");
  lookahead->setToDifference(*lookaheadTime, *publisherTime.initial);
  receiver.rtiAmbassador().enableTimeConstrained();
  waitFor(
      receiver,
      [&] { return receiver.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "timestamped interaction re-enable time-constrained callback");
  publisher.rtiAmbassador().enableTimeRegulation(*lookahead);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timestamped interaction re-enable time-regulation callback");

  auto const messageTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      5U);
  auto const publisherTarget = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      4U);
  std::vector<std::uint8_t> parameterBytes{0x52U, 0x45U, 0x45U, 0x4EU};
  std::vector<std::uint8_t> tagBytes{0x52U, 0x45U, 0x45U, 0x4EU, 0x2DU, 0x52U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherParameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
  auto const retraction = publisher.rtiAmbassador().sendInteraction(
      publisherInteraction,
      parameters,
      tag,
      *messageTime);
  require(
      retraction.isValid(),
      "timestamped interaction re-enable returned an invalid retraction handle");
  require(
      receiver.recorder().timedInteractions().empty(),
      "timestamped interaction re-enable delivered before its grant");

  receiver.rtiAmbassador().disableTimeConstrained();
  for (int pass = 0; pass != 8; ++pass) {
    receiver.pump();
  }
  require(
      receiver.recorder().timedInteractions().empty(),
      "timestamped interaction re-enable delivered while time constrained was disabled");
  receiver.rtiAmbassador().enableTimeConstrained();
  waitFor(
      receiver,
      [&] { return receiver.recorder().timeConstrainedEnabled().size() >= 2U; },
      options,
      "timestamped interaction re-enable second time-constrained callback");
  require(
      receiver.recorder().timedInteractions().empty(),
      "timestamped interaction re-enable delivered during re-enable callback");

  receiver.recorder().clearCallbackOrder();
  publisher.recorder().clearCallbackOrder();
  receiver.rtiAmbassador().timeAdvanceRequest(*messageTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*publisherTarget);
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 1U &&
            receiver.recorder().timeAdvanceGrants().size() >= 1U &&
            receiver.recorder().timedInteractions().size() >= 1U;
      },
      options,
      "timestamped interaction re-enable delivery and grants");
  require(
      receiver.recorder().timedInteractions().size() == 1U &&
          receiver.recorder().timeConstrainedEnabled().size() == 2U,
      "timestamped interaction re-enable returned the wrong callback counts");
  require(
      receiver.recorder().callbackOrder() ==
          std::vector<std::string>{"interaction", "grant"},
      "timestamped interaction re-enable delivered after its grant");
  auto const interactions = receiver.recorder().timedInteractions();
  auto const& interaction = interactions.front();
  require(
      interaction.interaction == receiverInteraction &&
          interaction.parameters.size() == 1U &&
          interaction.parameters.count(receiverParameter) == 1U &&
          copyBytes(interaction.parameters.at(receiverParameter)) == parameterBytes,
      "timestamped interaction re-enable returned the wrong class or parameter");
  require(
      interaction.tag == tagBytes && interaction.time == encodeTime(*messageTime) &&
          !interaction.timeText.empty(),
      "timestamped interaction re-enable did not preserve value metadata");
  require(
      interaction.producer == publisher.federateHandle() &&
          interaction.sentOrder == rti::TIMESTAMP &&
          interaction.receivedOrder == rti::TIMESTAMP,
      "timestamped interaction re-enable returned the wrong producer or order");
  require(
      interaction.transportation.isValid() &&
          !receiver.rtiAmbassador().getTransportationTypeName(
              interaction.transportation).empty(),
      "timestamped interaction re-enable returned an unresolvable transport");
  require(
      !interaction.regions.has_value(),
      "timestamped interaction re-enable unexpectedly supplied source regions");
  require(
      interaction.retractionPresent &&
          interaction.retraction == copyBytes(retraction.encode()),
      "timestamped interaction re-enable omitted its retraction handle");
  require(
      publisher.recorder().timeAdvanceGrants().front().encoded ==
              encodeTime(*publisherTarget) &&
          receiver.recorder().timeAdvanceGrants().front().encoded ==
              encodeTime(*messageTime),
      "timestamped interaction re-enable returned the wrong grants");
  requireException(
      [&] { publisher.rtiAmbassador().retract(retraction); },
      L"MessageCanNoLongerBeRetracted",
      "timestamped interaction re-enable retraction after delivery");

  receiver.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeInteractionClass(receiverInteraction);
  publisher.rtiAmbassador().unpublishInteractionClass(publisherInteraction);
  receiver.resign(rti::NO_ACTION);
  publisher.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

void scenarioTimestampedDirectedInteractionReenable(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timestamped directed interaction re-enable requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session receiver(options, model, "constrained");
  auto const federation = federationName(
      options,
      "timestamped-directed-interaction-reenable");
  connectAndJoin(publisher, receiver, options, federation, options.fom);

  auto const publisherClass = publisher.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const receiverClass = receiver.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const publisherAttribute = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass,
      options.attributeName);
  auto const receiverAttribute = receiver.rtiAmbassador().getAttributeHandle(
      receiverClass,
      options.attributeName);
  auto const publisherInteraction = publisher.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const receiverInteraction = receiver.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const publisherParameter = publisher.rtiAmbassador().getParameterHandle(
      publisherInteraction,
      options.parameterName);
  auto const receiverParameter = receiver.rtiAmbassador().getParameterHandle(
      receiverInteraction,
      options.parameterName);
  require(
      publisherClass.isValid() && receiverClass.isValid() &&
          publisherAttribute.isValid() && receiverAttribute.isValid() &&
          publisherInteraction.isValid() && receiverInteraction.isValid() &&
          publisherParameter.isValid() && receiverParameter.isValid(),
      "timestamped directed interaction re-enable lookup returned an invalid handle");

  rti::AttributeHandleSet publisherAttributes;
  publisherAttributes.insert(publisherAttribute);
  rti::AttributeHandleSet receiverAttributes;
  receiverAttributes.insert(receiverAttribute);
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  receiver.rtiAmbassador().publishObjectClassAttributes(
      receiverClass,
      receiverAttributes);
  publisher.rtiAmbassador().subscribeObjectClassAttributes(
      publisherClass,
      publisherAttributes,
      true,
      L"");
  receiver.rtiAmbassador().subscribeObjectClassAttributes(
      receiverClass,
      receiverAttributes,
      true,
      L"");

  rti::InteractionClassHandleSet publisherDirectedInteractions;
  publisherDirectedInteractions.insert(publisherInteraction);
  rti::InteractionClassHandleSet receiverDirectedInteractions;
  receiverDirectedInteractions.insert(receiverInteraction);
  publisher.rtiAmbassador().publishObjectClassDirectedInteractions(
      publisherClass,
      publisherDirectedInteractions);
  receiver.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      receiverClass,
      receiverDirectedInteractions,
      true);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherInteraction,
      rti::TIMESTAMP);

  auto const target = receiver.rtiAmbassador().registerObjectInstance(receiverClass);
  require(
      target.isValid(),
      "timestamped directed interaction re-enable registration returned an invalid handle");
  waitFor(
      publisher,
      receiver,
      [&] { return publisher.recorder().hasDiscovery(target); },
      options,
      "timestamped directed interaction re-enable target discovery");

  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  require(
      publisherTime.factory->getName() == receiverTime.factory->getName(),
      "timestamped directed interaction re-enable members selected different logical-time factories");
  auto const lookaheadTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      1U);
  auto lookahead = publisherTime.factory->makeZero();
  require(
      lookahead != nullptr,
      "timestamped directed interaction re-enable could not allocate a lookahead interval");
  lookahead->setToDifference(*lookaheadTime, *publisherTime.initial);
  receiver.rtiAmbassador().enableTimeConstrained();
  waitFor(
      receiver,
      [&] { return receiver.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "timestamped directed interaction re-enable time-constrained callback");
  publisher.rtiAmbassador().enableTimeRegulation(*lookahead);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timestamped directed interaction re-enable time-regulation callback");

  auto const interactionTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      5U);
  auto const publisherTarget = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      4U);
  std::vector<std::uint8_t> parameterBytes{0xD1U, 0x52U};
  std::vector<std::uint8_t> tagBytes{0x52U, 0x45U, 0x45U, 0x4EU, 0x2DU, 0x44U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherParameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
  auto const retraction = publisher.rtiAmbassador().sendDirectedInteraction(
      publisherInteraction,
      target,
      parameters,
      tag,
      *interactionTime);
  require(
      retraction.isValid(),
      "timestamped directed interaction re-enable send returned an invalid retraction handle");
  require(
      receiver.recorder().timedDirectedInteractions().empty(),
      "timestamped directed interaction re-enable delivered before its grant");

  receiver.rtiAmbassador().disableTimeConstrained();
  for (int pass = 0; pass != 8; ++pass) {
    receiver.pump();
  }
  require(
      receiver.recorder().timedDirectedInteractions().empty(),
      "timestamped directed interaction re-enable delivered while time constrained was disabled");
  receiver.rtiAmbassador().enableTimeConstrained();
  waitFor(
      receiver,
      [&] { return receiver.recorder().timeConstrainedEnabled().size() >= 2U; },
      options,
      "timestamped directed interaction re-enable second time-constrained callback");
  require(
      receiver.recorder().timedDirectedInteractions().empty(),
      "timestamped directed interaction re-enable delivered during re-enable callback");

  receiver.recorder().clearCallbackOrder();
  publisher.recorder().clearCallbackOrder();
  receiver.rtiAmbassador().timeAdvanceRequest(*interactionTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*publisherTarget);
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 1U &&
            receiver.recorder().timeAdvanceGrants().size() >= 1U &&
            receiver.recorder().timedDirectedInteractions().size() >= 1U;
      },
      options,
      "timestamped directed interaction re-enable delivery and grants");

  auto const directedInteractions = receiver.recorder().timedDirectedInteractions();
  require(
      directedInteractions.size() == 1U &&
          receiver.recorder().timeConstrainedEnabled().size() == 2U,
      "timestamped directed interaction re-enable returned the wrong callback counts");
  require(
      receiver.recorder().callbackOrder() ==
          std::vector<std::string>{"directed", "grant"},
      "timestamped directed interaction re-enable delivered after its grant");
  auto const& interaction = directedInteractions.front();
  require(
      interaction.interaction == receiverInteraction &&
          interaction.object == target &&
          interaction.parameters.size() == 1U &&
          interaction.parameters.count(receiverParameter) == 1U &&
          copyBytes(interaction.parameters.at(receiverParameter)) == parameterBytes,
      "timestamped directed interaction re-enable returned the wrong target or parameter");
  require(
      interaction.tag == tagBytes &&
          interaction.time == encodeTime(*interactionTime) &&
          !interaction.timeText.empty(),
      "timestamped directed interaction re-enable did not preserve value metadata");
  require(
      interaction.producer == publisher.federateHandle() &&
          interaction.sentOrder == rti::TIMESTAMP &&
          interaction.receivedOrder == rti::TIMESTAMP,
      "timestamped directed interaction re-enable returned the wrong producer or order");
  require(
      interaction.transportation.isValid() &&
          !receiver.rtiAmbassador().getTransportationTypeName(
              interaction.transportation).empty(),
      "timestamped directed interaction re-enable returned an unresolvable transport");
  require(
      interaction.retractionPresent &&
          interaction.retraction == copyBytes(retraction.encode()),
      "timestamped directed interaction re-enable omitted the retraction handle");
  require(
      publisher.recorder().timeAdvanceGrants().front().encoded ==
              encodeTime(*publisherTarget),
      "timestamped directed interaction re-enable returned the wrong producer grant");
  require(
      receiver.recorder().timeAdvanceGrants().front().encoded ==
              encodeTime(*interactionTime),
      "timestamped directed interaction re-enable returned the wrong receiver grant");
  requireException(
      [&] { publisher.rtiAmbassador().retract(retraction); },
      L"MessageCanNoLongerBeRetracted",
      "timestamped directed interaction re-enable retraction after delivery");

  receiver.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      receiverClass,
      receiverDirectedInteractions);
  publisher.rtiAmbassador().unpublishObjectClassDirectedInteractions(
      publisherClass,
      publisherDirectedInteractions);
  receiver.rtiAmbassador().unsubscribeObjectClassAttributes(
      receiverClass,
      receiverAttributes);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  receiver.resign(rti::DELETE_OBJECTS);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

void scenarioTimestampedDirectedInteractionRegulationReenable(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timestamped directed interaction regulation re-enable requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session receiver(options, model, "constrained");
  auto const federation = federationName(
      options,
      "timestamped-directed-interaction-regulation-reenable");
  connectAndJoin(publisher, receiver, options, federation, options.fom);

  auto const publisherClass = publisher.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const receiverClass = receiver.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const publisherAttribute = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass,
      options.attributeName);
  auto const receiverAttribute = receiver.rtiAmbassador().getAttributeHandle(
      receiverClass,
      options.attributeName);
  auto const publisherInteraction = publisher.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const receiverInteraction = receiver.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const publisherParameter = publisher.rtiAmbassador().getParameterHandle(
      publisherInteraction,
      options.parameterName);
  auto const receiverParameter = receiver.rtiAmbassador().getParameterHandle(
      receiverInteraction,
      options.parameterName);
  require(
      publisherClass.isValid() && receiverClass.isValid() &&
          publisherAttribute.isValid() && receiverAttribute.isValid() &&
          publisherInteraction.isValid() && receiverInteraction.isValid() &&
          publisherParameter.isValid() && receiverParameter.isValid(),
      "timestamped directed interaction regulation re-enable lookup returned an invalid handle");

  rti::AttributeHandleSet publisherAttributes;
  publisherAttributes.insert(publisherAttribute);
  rti::AttributeHandleSet receiverAttributes;
  receiverAttributes.insert(receiverAttribute);
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  receiver.rtiAmbassador().publishObjectClassAttributes(
      receiverClass,
      receiverAttributes);
  publisher.rtiAmbassador().subscribeObjectClassAttributes(
      publisherClass,
      publisherAttributes,
      true,
      L"");
  receiver.rtiAmbassador().subscribeObjectClassAttributes(
      receiverClass,
      receiverAttributes,
      true,
      L"");

  rti::InteractionClassHandleSet publisherDirectedInteractions;
  publisherDirectedInteractions.insert(publisherInteraction);
  rti::InteractionClassHandleSet receiverDirectedInteractions;
  receiverDirectedInteractions.insert(receiverInteraction);
  publisher.rtiAmbassador().publishObjectClassDirectedInteractions(
      publisherClass,
      publisherDirectedInteractions);
  receiver.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      receiverClass,
      receiverDirectedInteractions,
      true);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherInteraction,
      rti::TIMESTAMP);

  auto const target = receiver.rtiAmbassador().registerObjectInstance(receiverClass);
  require(
      target.isValid(),
      "timestamped directed interaction regulation re-enable registration returned an invalid handle");
  waitFor(
      publisher,
      receiver,
      [&] { return publisher.recorder().hasDiscovery(target); },
      options,
      "timestamped directed interaction regulation re-enable target discovery");

  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  enableTimestampedRoles(
      publisher,
      receiver,
      publisherTime,
      receiverTime,
      options,
      "timestamped directed interaction regulation re-enable");

  auto const interactionTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      5U);
  auto const publisherTarget = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      2U);
  auto const changedLookaheadTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      3U);
  auto changedLookahead = publisherTime.factory->makeZero();
  require(
      changedLookahead != nullptr,
      "timestamped directed interaction regulation re-enable could not allocate the changed lookahead");
  changedLookahead->setToDifference(
      *changedLookaheadTime,
      *publisherTime.initial);

  std::vector<std::uint8_t> parameterBytes{0xD1U, 0x52U};
  std::vector<std::uint8_t> tagBytes{0x44U, 0x49U, 0x52U, 0x4CU};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherParameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
  auto const retraction = publisher.rtiAmbassador().sendDirectedInteraction(
      publisherInteraction,
      target,
      parameters,
      tag,
      *interactionTime);
  require(
      retraction.isValid(),
      "timestamped directed interaction regulation re-enable send returned an invalid retraction handle");
  require(
      receiver.recorder().timedDirectedInteractions().empty(),
      "timestamped directed interaction regulation re-enable delivered before its grant");

  publisher.rtiAmbassador().disableTimeRegulation();
  publisher.rtiAmbassador().enableTimeRegulation(*changedLookahead);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 2U; },
      options,
      "timestamped directed interaction regulation re-enable callback");
  auto queriedLookahead = publisherTime.factory->makeZero();
  require(
      queriedLookahead != nullptr,
      "timestamped directed interaction regulation re-enable could not allocate a lookahead query");
  publisher.rtiAmbassador().queryLookahead(*queriedLookahead);
  require(
      *queriedLookahead == *changedLookahead,
      "timestamped directed interaction regulation re-enable did not expose the changed lookahead");

  receiver.recorder().clearCallbackOrder();
  publisher.recorder().clearCallbackOrder();
  receiver.rtiAmbassador().timeAdvanceRequest(*interactionTime);
  require(
      receiver.recorder().timedDirectedInteractions().empty(),
      "timestamped directed interaction regulation re-enable delivered while the producer boundary was pending");
  publisher.rtiAmbassador().timeAdvanceRequest(*publisherTarget);
  waitFor(
      publisher,
      receiver,
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 1U &&
            receiver.recorder().timeAdvanceGrants().size() >= 1U &&
            receiver.recorder().timedDirectedInteractions().size() >= 1U;
      },
      options,
      "timestamped directed interaction regulation re-enable delivery");

  auto const directedInteractions = receiver.recorder().timedDirectedInteractions();
  require(
      directedInteractions.size() == 1U &&
          publisher.recorder().timeRegulationEnabled().size() == 2U,
      "timestamped directed interaction regulation re-enable returned the wrong callback counts");
  require(
      receiver.recorder().callbackOrder() ==
          std::vector<std::string>{"directed", "grant"},
      "timestamped directed interaction regulation re-enable delivered after its grant");
  auto const& interaction = directedInteractions.front();
  require(
      interaction.interaction == receiverInteraction &&
          interaction.object == target &&
          interaction.parameters.size() == 1U &&
          interaction.parameters.count(receiverParameter) == 1U &&
          copyBytes(interaction.parameters.at(receiverParameter)) == parameterBytes,
      "timestamped directed interaction regulation re-enable returned the wrong target or parameter");
  require(
      interaction.tag == tagBytes &&
          interaction.time == encodeTime(*interactionTime) &&
          !interaction.timeText.empty(),
      "timestamped directed interaction regulation re-enable did not preserve value metadata");
  require(
      interaction.producer == publisher.federateHandle() &&
          interaction.sentOrder == rti::TIMESTAMP &&
          interaction.receivedOrder == rti::TIMESTAMP,
      "timestamped directed interaction regulation re-enable returned the wrong producer or order");
  require(
      interaction.transportation.isValid() &&
          !receiver.rtiAmbassador().getTransportationTypeName(
              interaction.transportation).empty(),
      "timestamped directed interaction regulation re-enable returned an unresolvable transport");
  require(
      interaction.retractionPresent &&
          interaction.retraction == copyBytes(retraction.encode()),
      "timestamped directed interaction regulation re-enable omitted the retraction handle");
  require(
      publisher.recorder().timeAdvanceGrants().front().encoded ==
          encodeTime(*publisherTarget),
      "timestamped directed interaction regulation re-enable returned the wrong producer grant");
  require(
      receiver.recorder().timeAdvanceGrants().front().encoded ==
          encodeTime(*interactionTime),
      "timestamped directed interaction regulation re-enable returned the wrong receiver grant");
  requireException(
      [&] { publisher.rtiAmbassador().retract(retraction); },
      L"MessageCanNoLongerBeRetracted",
      "timestamped directed interaction regulation re-enable retraction after delivery");

  receiver.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      receiverClass,
      receiverDirectedInteractions);
  publisher.rtiAmbassador().unpublishObjectClassDirectedInteractions(
      publisherClass,
      publisherDirectedInteractions);
  receiver.rtiAmbassador().unsubscribeObjectClassAttributes(
      receiverClass,
      receiverAttributes);
  publisher.rtiAmbassador().unsubscribeObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  receiver.rtiAmbassador().unpublishObjectClassAttributes(
      receiverClass,
      receiverAttributes);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  receiver.resign(rti::DELETE_OBJECTS);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

void scenarioTimestampedDirectedInteractionSourceResignation(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timestamped directed interaction source resignation requires an adapter-supplied logical-time implementation");

  Session owner(options, model, "owner");
  Session publisher(options, model, "publisher");
  Session receiver(options, model, "receiver");
  Session clock(options, model, "source-resignation-clock");
  auto const federation = federationName(
      options,
      "timestamped-directed-interaction-source-resignation");
  connectAndJoin(owner, publisher, options, federation, options.fom);
  receiver.connect();
  receiver.join(
      options.memberFederateName + L"-timestamped-directed-resignation-receiver",
      options.federateType,
      federation);
  clock.connect();
  clock.join(
      options.memberFederateName + L"-timestamped-directed-resignation-clock",
      options.federateType,
      federation);

  auto const ownerClass = owner.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const publisherClass = publisher.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const receiverClass = receiver.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const ownerAttribute = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.attributeName);
  auto const publisherAttribute = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass,
      options.attributeName);
  auto const receiverAttribute = receiver.rtiAmbassador().getAttributeHandle(
      receiverClass,
      options.attributeName);
  auto const ownerInteraction = owner.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const publisherInteraction =
      publisher.rtiAmbassador().getInteractionClassHandle(
          options.interactionClassName);
  auto const receiverInteraction = receiver.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const publisherParameter = publisher.rtiAmbassador().getParameterHandle(
      publisherInteraction,
      options.parameterName);
  auto const receiverParameter = receiver.rtiAmbassador().getParameterHandle(
      receiverInteraction,
      options.parameterName);
  require(
      ownerClass.isValid() && publisherClass.isValid() && receiverClass.isValid() &&
          ownerAttribute.isValid() && publisherAttribute.isValid() &&
          receiverAttribute.isValid() && ownerInteraction.isValid() &&
          publisherInteraction.isValid() && receiverInteraction.isValid() &&
          publisherParameter.isValid() && receiverParameter.isValid(),
      "timestamped directed interaction source resignation lookup returned an invalid handle");

  rti::AttributeHandleSet ownerAttributes;
  ownerAttributes.insert(ownerAttribute);
  rti::AttributeHandleSet publisherAttributes;
  publisherAttributes.insert(publisherAttribute);
  rti::AttributeHandleSet receiverAttributes;
  receiverAttributes.insert(receiverAttribute);
  rti::InteractionClassHandleSet publisherDirectedInteractions;
  publisherDirectedInteractions.insert(publisherInteraction);
  rti::InteractionClassHandleSet receiverDirectedInteractions;
  receiverDirectedInteractions.insert(receiverInteraction);

  owner.rtiAmbassador().publishObjectClassAttributes(
      ownerClass,
      ownerAttributes);
  publisher.rtiAmbassador().subscribeObjectClassAttributes(
      publisherClass,
      publisherAttributes,
      true,
      L"");
  receiver.rtiAmbassador().subscribeObjectClassAttributes(
      receiverClass,
      receiverAttributes,
      true,
      L"");
  publisher.rtiAmbassador().publishObjectClassDirectedInteractions(
      publisherClass,
      publisherDirectedInteractions);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherInteraction,
      rti::TIMESTAMP);
  receiver.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      receiverClass,
      receiverDirectedInteractions,
      true);

  auto const target = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(
      target.isValid(),
      "timestamped directed interaction source resignation registration returned an invalid handle");
  waitFor(
      publisher,
      receiver,
      [&] {
        return publisher.recorder().hasDiscovery(target) &&
            receiver.recorder().hasDiscovery(target);
      },
      options,
      "timestamped directed interaction source resignation target discovery");

  auto ownerTime = makeTimeContext(owner);
  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  auto clockTime = makeTimeContext(clock);
  require(
      ownerTime.factory->getName() == publisherTime.factory->getName() &&
          ownerTime.factory->getName() == receiverTime.factory->getName() &&
          ownerTime.factory->getName() == clockTime.factory->getName(),
      "timestamped directed interaction source resignation members selected different logical-time factories");

  auto makeLookahead = [](TimeContext const& time) {
    auto target = timeAfter(*time.factory, *time.initial, *time.epsilon, 5U);
    auto result = time.factory->makeZero();
    require(
        result != nullptr,
        "timestamped directed interaction source resignation could not allocate a lookahead interval");
    result->setToDifference(*target, *time.initial);
    return result;
  };
  auto publisherLookahead = makeLookahead(publisherTime);
  auto clockLookahead = makeLookahead(clockTime);

  receiver.rtiAmbassador().enableTimeConstrained();
  waitFor(
      receiver,
      [&] { return receiver.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "timestamped directed interaction source resignation receiver time-constrained callback");
  publisher.rtiAmbassador().enableTimeRegulation(*publisherLookahead);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timestamped directed interaction source resignation publisher time-regulation callback");
  clock.rtiAmbassador().enableTimeRegulation(*clockLookahead);
  waitFor(
      clock,
      [&] { return clock.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timestamped directed interaction source resignation clock time-regulation callback");

  auto const messageTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      6U);
  auto const receiverTarget = timeAfter(
      *receiverTime.factory,
      *receiverTime.initial,
      *receiverTime.epsilon,
      6U);
  auto const clockTarget = timeAfter(
      *clockTime.factory,
      *clockTime.initial,
      *clockTime.epsilon,
      2U);
  std::vector<std::uint8_t> parameterBytes{
      0x44U, 0x49U, 0x52U, 0x2DU, 0x52U};
  std::vector<std::uint8_t> tagBytes{
      0x44U, 0x53U, 0x4FU, 0x2DU, 0x52U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherParameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
  auto const retraction = publisher.rtiAmbassador().sendDirectedInteraction(
      publisherInteraction,
      target,
      parameters,
      tag,
      *messageTime);
  require(
      retraction.isValid(),
      "timestamped directed interaction source resignation send returned an invalid retraction handle");
  require(
      receiver.recorder().timedDirectedInteractions().empty(),
      "timestamped directed interaction source resignation delivered before the receiver frontier");

  receiver.rtiAmbassador().timeAdvanceRequest(*receiverTarget);
  require(
      receiver.recorder().timeAdvanceGrants().empty(),
      "timestamped directed interaction source resignation granted before the producer frontier");
  publisher.resign(rti::NO_ACTION);
  require(
      receiver.recorder().timedDirectedInteractions().empty() &&
          receiver.recorder().timeAdvanceGrants().empty(),
      "timestamped directed interaction source resignation released the queued callback too early");
  requireException(
      [&] { publisher.rtiAmbassador().retract(retraction); },
      L"FederateNotExecutionMember",
      "timestamped directed interaction source resignation post-resignation retraction");

  clock.rtiAmbassador().timeAdvanceRequest(*clockTarget);
  waitFor(
      clock,
      [&] { return clock.recorder().timeAdvanceGrants().size() >= 1U; },
      options,
      "timestamped directed interaction source resignation clock frontier");
  waitFor(
      receiver,
      [&] {
        return receiver.recorder().timedDirectedInteractions().size() >= 1U &&
            receiver.recorder().timeAdvanceGrants().size() >= 1U;
      },
      options,
      "timestamped directed interaction source resignation delivery and grant");

  require(
      receiver.recorder().timedDirectedInteractions().size() == 1U &&
          receiver.recorder().timeAdvanceGrants().size() == 1U,
      "timestamped directed interaction source resignation returned duplicate callbacks");
  require(
      receiver.recorder().callbackOrder() ==
          std::vector<std::string>{"directed", "grant"},
      "timestamped directed interaction source resignation delivered after its grant");
  auto const directedInteractions = receiver.recorder().timedDirectedInteractions();
  auto const& interaction = directedInteractions.front();
  require(
      interaction.interaction == receiverInteraction &&
          interaction.object == target && interaction.parameters.size() == 1U &&
          interaction.parameters.count(receiverParameter) == 1U &&
          copyBytes(interaction.parameters.at(receiverParameter)) == parameterBytes,
      "timestamped directed interaction source resignation returned the wrong target or parameter");
  require(
      interaction.tag == tagBytes && interaction.time == encodeTime(*messageTime) &&
          !interaction.timeText.empty(),
      "timestamped directed interaction source resignation did not preserve payload or time");
  require(
      interaction.producer == publisher.federateHandle() &&
          interaction.sentOrder == rti::TIMESTAMP &&
          interaction.receivedOrder == rti::TIMESTAMP,
      "timestamped directed interaction source resignation returned the wrong producer or order metadata");
  require(
      interaction.transportation.isValid() &&
          !receiver.rtiAmbassador().getTransportationTypeName(
              interaction.transportation).empty(),
      "timestamped directed interaction source resignation returned an unresolvable transport");
  require(
      interaction.retractionPresent &&
          interaction.retraction == copyBytes(retraction.encode()),
      "timestamped directed interaction source resignation omitted its retraction handle");
  require(
      receiver.recorder().timeAdvanceGrants().front().encoded ==
          encodeTime(*receiverTarget),
      "timestamped directed interaction source resignation returned the wrong receiver grant");

  receiver.rtiAmbassador().disableTimeConstrained();
  clock.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      receiverClass,
      receiverDirectedInteractions);
  receiver.rtiAmbassador().unsubscribeObjectClassAttributes(
      receiverClass,
      receiverAttributes);
  owner.rtiAmbassador().unpublishObjectClassAttributes(
      ownerClass,
      ownerAttributes);
  receiver.resign(rti::NO_ACTION);
  clock.resign(rti::NO_ACTION);
  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  publisher.disconnect();
  receiver.disconnect();
  clock.disconnect();
  owner.disconnect();
}

void scenarioTimestampedDirectedInteractionTarNmr(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timestamped directed interaction TAR/NMR requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session tar(options, model, "tar-member");
  Session nmr(options, model, "next-message-member");
  auto const federation = federationName(
      options,
      "timestamped-directed-interaction-tar-nmr");
  connectAndJoin(publisher, tar, options, federation, options.fom);
  nmr.connect();
  nmr.join(
      options.memberFederateName + L"-timestamped-directed-nmr",
      options.federateType,
      federation);

  auto const publisherClass = publisher.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const tarClass = tar.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const nmrClass = nmr.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const publisherAttribute = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass,
      options.attributeName);
  auto const tarAttribute = tar.rtiAmbassador().getAttributeHandle(
      tarClass,
      options.attributeName);
  auto const nmrAttribute = nmr.rtiAmbassador().getAttributeHandle(
      nmrClass,
      options.attributeName);
  auto const publisherInteraction = publisher.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const tarInteraction = tar.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const nmrInteraction = nmr.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const publisherParameter = publisher.rtiAmbassador().getParameterHandle(
      publisherInteraction,
      options.parameterName);
  auto const tarParameter = tar.rtiAmbassador().getParameterHandle(
      tarInteraction,
      options.parameterName);
  auto const nmrParameter = nmr.rtiAmbassador().getParameterHandle(
      nmrInteraction,
      options.parameterName);
  require(
      publisherClass.isValid() && tarClass.isValid() && nmrClass.isValid() &&
          publisherAttribute.isValid() && tarAttribute.isValid() &&
          nmrAttribute.isValid() && publisherInteraction.isValid() &&
          tarInteraction.isValid() && nmrInteraction.isValid() &&
          publisherParameter.isValid() && tarParameter.isValid() &&
          nmrParameter.isValid(),
      "timestamped directed interaction TAR/NMR lookup returned an invalid handle");

  rti::AttributeHandleSet const publisherAttributes{publisherAttribute};
  rti::AttributeHandleSet const tarAttributes{tarAttribute};
  rti::AttributeHandleSet const nmrAttributes{nmrAttribute};
  rti::InteractionClassHandleSet const publisherDirected{publisherInteraction};
  rti::InteractionClassHandleSet const tarDirected{tarInteraction};
  rti::InteractionClassHandleSet const nmrDirected{nmrInteraction};
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  publisher.rtiAmbassador().publishObjectClassDirectedInteractions(
      publisherClass,
      publisherDirected);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherInteraction,
      rti::TIMESTAMP);
  tar.rtiAmbassador().subscribeObjectClassAttributes(
      tarClass,
      tarAttributes,
      true,
      L"");
  nmr.rtiAmbassador().subscribeObjectClassAttributes(
      nmrClass,
      nmrAttributes,
      true,
      L"");
  tar.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      tarClass,
      tarDirected,
      true);
  nmr.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      nmrClass,
      nmrDirected,
      true);

  auto const target = publisher.rtiAmbassador().registerObjectInstance(publisherClass);
  require(
      target.isValid(),
      "timestamped directed interaction TAR/NMR registration returned an invalid handle");
  waitFor(
      tar,
      [&] { return tar.recorder().hasDiscovery(target); },
      options,
      "timestamped directed interaction TAR/NMR TAR target discovery");
  waitFor(
      nmr,
      [&] { return nmr.recorder().hasDiscovery(target); },
      options,
      "timestamped directed interaction TAR/NMR NMR target discovery");

  auto publisherTime = makeTimeContext(publisher);
  auto tarTime = makeTimeContext(tar);
  auto nmrTime = makeTimeContext(nmr);
  require(
      publisherTime.factory->getName() == tarTime.factory->getName() &&
          publisherTime.factory->getName() == nmrTime.factory->getName(),
      "timestamped directed interaction TAR/NMR members selected different logical-time factories");

  auto makeLookahead = [](TimeContext const& time) {
    auto targetTime = timeAfter(*time.factory, *time.initial, *time.epsilon, 5U);
    auto result = time.factory->makeZero();
    require(
        result != nullptr,
        "timestamped directed interaction TAR/NMR could not allocate a lookahead interval");
    result->setToDifference(*targetTime, *time.initial);
    return result;
  };
  auto publisherLookahead = makeLookahead(publisherTime);
  tar.rtiAmbassador().enableTimeConstrained();
  waitFor(
      tar,
      [&] { return tar.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "timestamped directed interaction TAR/NMR TAR time-constrained callback");
  nmr.rtiAmbassador().enableTimeConstrained();
  waitFor(
      nmr,
      [&] { return nmr.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "timestamped directed interaction TAR/NMR NMR time-constrained callback");
  publisher.rtiAmbassador().enableTimeRegulation(*publisherLookahead);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timestamped directed interaction TAR/NMR publisher time-regulation callback");

  auto const messageTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      7U);
  auto const tarTarget = timeAfter(
      *tarTime.factory,
      *tarTime.initial,
      *tarTime.epsilon,
      7U);
  auto const nmrTarget = timeAfter(
      *nmrTime.factory,
      *nmrTime.initial,
      *nmrTime.epsilon,
      10U);
  auto const publisherTarget = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      2U);
  std::vector<std::uint8_t> const parameterBytes{
      0x54U, 0x41U, 0x52U, 0x2DU, 0x4EU};
  std::vector<std::uint8_t> const tagBytes{
      0x54U, 0x41U, 0x52U, 0x2DU, 0x4DU};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherParameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
  auto const retraction = publisher.rtiAmbassador().sendDirectedInteraction(
      publisherInteraction,
      target,
      parameters,
      tag,
      *messageTime);
  require(
      retraction.isValid(),
      "timestamped directed interaction TAR/NMR send returned an invalid retraction handle");
  require(
      tar.recorder().timedDirectedInteractions().empty() &&
          nmr.recorder().timedDirectedInteractions().empty(),
      "timestamped directed interaction TAR/NMR delivered before either request");

  tar.rtiAmbassador().timeAdvanceRequest(*tarTarget);
  nmr.rtiAmbassador().nextMessageRequest(*nmrTarget);
  require(
      tar.recorder().timeAdvanceGrants().empty() &&
          nmr.recorder().timeAdvanceGrants().empty(),
      "timestamped directed interaction TAR/NMR granted before the publisher frontier");
  publisher.rtiAmbassador().timeAdvanceRequest(*publisherTarget);
  waitForSessions(
      {&publisher, &tar, &nmr},
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 1U &&
            tar.recorder().timedDirectedInteractions().size() >= 1U &&
            tar.recorder().timeAdvanceGrants().size() >= 1U &&
            nmr.recorder().timedDirectedInteractions().size() >= 1U &&
            nmr.recorder().timeAdvanceGrants().size() >= 1U;
      },
      options,
      "timestamped directed interaction TAR/NMR deliveries and grants");

  auto assertDirected = [&](Session& receiver,
                            rti::InteractionClassHandle const& expectedInteraction,
                            rti::ParameterHandle const& expectedParameter,
                            TimedDirectedInteractionRecord const& record,
                            std::vector<std::uint8_t> const& expectedGrant,
                            std::wstring const& expectedGrantText) {
    require(
        record.interaction == expectedInteraction && record.object == target &&
            record.parameters.size() == 1U &&
            record.parameters.count(expectedParameter) == 1U &&
            copyBytes(record.parameters.at(expectedParameter)) == parameterBytes,
        "timestamped directed interaction TAR/NMR returned the wrong target or parameter");
    require(
        record.tag == tagBytes && record.time == encodeTime(*messageTime) &&
            !record.timeText.empty(),
        "timestamped directed interaction TAR/NMR did not preserve payload or time");
    require(
        record.producer == publisher.federateHandle() &&
            record.sentOrder == rti::TIMESTAMP &&
            record.receivedOrder == rti::TIMESTAMP,
        "timestamped directed interaction TAR/NMR returned the wrong producer or order metadata");
    require(
        record.transportation.isValid() &&
            !receiver.rtiAmbassador().getTransportationTypeName(
                record.transportation).empty(),
        "timestamped directed interaction TAR/NMR returned an unresolvable transport");
    require(
        record.retractionPresent &&
            record.retraction == copyBytes(retraction.encode()),
        "timestamped directed interaction TAR/NMR omitted its retraction handle");
    require(
        receiver.recorder().timeAdvanceGrants().size() == 1U &&
            receiver.recorder().timeAdvanceGrants().front().encoded == expectedGrant,
        "timestamped directed interaction TAR/NMR returned the wrong grant (actual=" +
            toNarrow(receiver.recorder().timeAdvanceGrants().front().text) +
            ", expected=" + toNarrow(expectedGrantText) + ")");
    require(
        receiver.recorder().callbackOrder() ==
            std::vector<std::string>{"directed", "grant"},
        "timestamped directed interaction TAR/NMR delivered after its grant");
  };
  require(
      tar.recorder().timedDirectedInteractions().size() == 1U &&
          nmr.recorder().timedDirectedInteractions().size() == 1U,
      "timestamped directed interaction TAR/NMR delivered duplicate callbacks");
  assertDirected(
      tar,
      tarInteraction,
      tarParameter,
      tar.recorder().timedDirectedInteractions().front(),
      encodeTime(*tarTarget),
      tarTarget->toString());
  assertDirected(
      nmr,
      nmrInteraction,
      nmrParameter,
      nmr.recorder().timedDirectedInteractions().front(),
      encodeTime(*messageTime),
      messageTime->toString());

  auto tarLogicalTime = tarTime.factory->makeInitial();
  auto nmrLogicalTime = nmrTime.factory->makeInitial();
  require(
      tarLogicalTime != nullptr && nmrLogicalTime != nullptr,
      "timestamped directed interaction TAR/NMR could not allocate query times");
  tar.rtiAmbassador().queryLogicalTime(*tarLogicalTime);
  nmr.rtiAmbassador().queryLogicalTime(*nmrLogicalTime);
  require(
      *tarLogicalTime == *tarTarget && *nmrLogicalTime == *messageTime,
      "timestamped directed interaction TAR/NMR query returned the wrong logical time");
  requireException(
      [&] { publisher.rtiAmbassador().retract(retraction); },
      L"MessageCanNoLongerBeRetracted",
      "timestamped directed interaction TAR/NMR retraction after delivery");

  tar.rtiAmbassador().disableTimeConstrained();
  nmr.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  tar.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      tarClass,
      tarDirected);
  nmr.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      nmrClass,
      nmrDirected);
  tar.rtiAmbassador().unsubscribeObjectClassAttributes(tarClass, tarAttributes);
  nmr.rtiAmbassador().unsubscribeObjectClassAttributes(nmrClass, nmrAttributes);
  publisher.rtiAmbassador().unpublishObjectClassDirectedInteractions(
      publisherClass,
      publisherDirected);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  nmr.resign(rti::NO_ACTION);
  tar.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  nmr.disconnect();
  tar.disconnect();
  publisher.disconnect();
}

void scenarioTimestampedDirectedInteractionSourceResignationFanout(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timestamped directed interaction source resignation fanout requires an adapter-supplied logical-time implementation");

  Session owner(options, model, "target-owner");
  Session publisher(options, model, "publisher");
  Session first(options, model, "first");
  Session second(options, model, "second");
  Session clock(options, model, "source-resignation-fanout-clock");
  auto const federation = federationName(
      options,
      "timestamped-directed-interaction-source-resignation-fanout");
  connectAndJoin(owner, publisher, options, federation, options.fom);
  first.connect();
  first.join(
      options.memberFederateName + L"-timestamped-directed-resignation-first",
      options.federateType,
      federation);
  second.connect();
  second.join(
      options.memberFederateName + L"-timestamped-directed-resignation-second",
      options.federateType,
      federation);
  clock.connect();
  clock.join(
      options.memberFederateName + L"-timestamped-directed-resignation-clock",
      options.federateType,
      federation);

  auto const ownerClass = owner.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const publisherClass = publisher.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const firstClass = first.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const secondClass = second.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const ownerAttribute = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.attributeName);
  auto const publisherAttribute = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass,
      options.attributeName);
  auto const firstAttribute = first.rtiAmbassador().getAttributeHandle(
      firstClass,
      options.attributeName);
  auto const secondAttribute = second.rtiAmbassador().getAttributeHandle(
      secondClass,
      options.attributeName);
  auto const publisherInteraction = publisher.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const firstInteraction = first.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const secondInteraction = second.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const publisherParameter = publisher.rtiAmbassador().getParameterHandle(
      publisherInteraction,
      options.parameterName);
  auto const firstParameter = first.rtiAmbassador().getParameterHandle(
      firstInteraction,
      options.parameterName);
  auto const secondParameter = second.rtiAmbassador().getParameterHandle(
      secondInteraction,
      options.parameterName);
  require(
      ownerClass.isValid() && publisherClass.isValid() && firstClass.isValid() &&
          secondClass.isValid() && ownerAttribute.isValid() &&
          publisherAttribute.isValid() && firstAttribute.isValid() &&
          secondAttribute.isValid() && publisherInteraction.isValid() &&
          firstInteraction.isValid() && secondInteraction.isValid() &&
          publisherParameter.isValid() && firstParameter.isValid() &&
          secondParameter.isValid(),
      "timestamped directed interaction source resignation fanout lookup returned an invalid handle");

  rti::AttributeHandleSet ownerAttributes;
  ownerAttributes.insert(ownerAttribute);
  rti::AttributeHandleSet publisherAttributes;
  publisherAttributes.insert(publisherAttribute);
  rti::AttributeHandleSet firstAttributes;
  firstAttributes.insert(firstAttribute);
  rti::AttributeHandleSet secondAttributes;
  secondAttributes.insert(secondAttribute);
  rti::InteractionClassHandleSet publisherDirectedInteractions;
  publisherDirectedInteractions.insert(publisherInteraction);
  rti::InteractionClassHandleSet firstDirectedInteractions;
  firstDirectedInteractions.insert(firstInteraction);
  rti::InteractionClassHandleSet secondDirectedInteractions;
  secondDirectedInteractions.insert(secondInteraction);

  owner.rtiAmbassador().publishObjectClassAttributes(
      ownerClass,
      ownerAttributes);
  publisher.rtiAmbassador().subscribeObjectClassAttributes(
      publisherClass,
      publisherAttributes,
      true,
      L"");
  first.rtiAmbassador().subscribeObjectClassAttributes(
      firstClass,
      firstAttributes,
      true,
      L"");
  second.rtiAmbassador().subscribeObjectClassAttributes(
      secondClass,
      secondAttributes,
      true,
      L"");
  publisher.rtiAmbassador().publishObjectClassDirectedInteractions(
      publisherClass,
      publisherDirectedInteractions);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherInteraction,
      rti::TIMESTAMP);
  first.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      firstClass,
      firstDirectedInteractions,
      true);
  second.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      secondClass,
      secondDirectedInteractions,
      true);

  auto const target = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(
      target.isValid(),
      "timestamped directed interaction source resignation fanout registration returned an invalid handle");
  waitFor(
      publisher,
      [&] { return publisher.recorder().hasDiscovery(target); },
      options,
      "timestamped directed interaction source resignation fanout publisher target discovery");
  waitFor(
      first,
      [&] { return first.recorder().hasDiscovery(target); },
      options,
      "timestamped directed interaction source resignation fanout first target discovery");
  waitFor(
      second,
      [&] { return second.recorder().hasDiscovery(target); },
      options,
      "timestamped directed interaction source resignation fanout second target discovery");

  auto publisherTime = makeTimeContext(publisher);
  auto firstTime = makeTimeContext(first);
  auto secondTime = makeTimeContext(second);
  auto clockTime = makeTimeContext(clock);
  require(
      publisherTime.factory->getName() == firstTime.factory->getName() &&
          publisherTime.factory->getName() == secondTime.factory->getName() &&
          publisherTime.factory->getName() == clockTime.factory->getName(),
      "timestamped directed interaction source resignation fanout members selected different logical-time factories");

  auto makeLookahead = [](TimeContext const& time) {
    auto target = timeAfter(*time.factory, *time.initial, *time.epsilon, 5U);
    auto result = time.factory->makeZero();
    require(
        result != nullptr,
        "timestamped directed interaction source resignation fanout could not allocate a lookahead interval");
    result->setToDifference(*target, *time.initial);
    return result;
  };
  auto publisherLookahead = makeLookahead(publisherTime);
  auto clockLookahead = makeLookahead(clockTime);

  first.rtiAmbassador().enableTimeConstrained();
  waitFor(
      first,
      [&] { return first.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "timestamped directed interaction source resignation fanout first time-constrained callback");
  second.rtiAmbassador().enableTimeConstrained();
  waitFor(
      second,
      [&] { return second.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "timestamped directed interaction source resignation fanout second time-constrained callback");
  publisher.rtiAmbassador().enableTimeRegulation(*publisherLookahead);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timestamped directed interaction source resignation fanout publisher time-regulation callback");
  clock.rtiAmbassador().enableTimeRegulation(*clockLookahead);
  waitFor(
      clock,
      [&] { return clock.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timestamped directed interaction source resignation fanout clock time-regulation callback");

  auto const messageTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      6U);
  auto const firstTarget = timeAfter(
      *firstTime.factory,
      *firstTime.initial,
      *firstTime.epsilon,
      6U);
  auto const secondTarget = timeAfter(
      *secondTime.factory,
      *secondTime.initial,
      *secondTime.epsilon,
      6U);
  auto const firstClockTarget = timeAfter(
      *clockTime.factory,
      *clockTime.initial,
      *clockTime.epsilon,
      2U);
  auto const secondClockTarget = timeAfter(
      *clockTime.factory,
      *clockTime.initial,
      *clockTime.epsilon,
      6U);
  std::vector<std::uint8_t> parameterBytes{
      0x44U, 0x49U, 0x52U, 0x2DU, 0x4DU, 0x52U};
  std::vector<std::uint8_t> tagBytes{
      0x44U, 0x53U, 0x4FU, 0x2DU, 0x4DU, 0x52U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherParameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
  auto const retraction = publisher.rtiAmbassador().sendDirectedInteraction(
      publisherInteraction,
      target,
      parameters,
      tag,
      *messageTime);
  require(
      retraction.isValid(),
      "timestamped directed interaction source resignation fanout send returned an invalid retraction handle");
  require(
      first.recorder().timedDirectedInteractions().empty() &&
          second.recorder().timedDirectedInteractions().empty(),
      "timestamped directed interaction source resignation fanout delivered before either recipient frontier");

  first.rtiAmbassador().timeAdvanceRequest(*firstTarget);
  require(
      first.recorder().timeAdvanceGrants().empty() &&
          second.recorder().timeAdvanceGrants().empty(),
      "timestamped directed interaction source resignation fanout granted before the producer frontier");
  publisher.resign(rti::NO_ACTION);
  requireException(
      [&] { publisher.rtiAmbassador().retract(retraction); },
      L"FederateNotExecutionMember",
      "timestamped directed interaction source resignation fanout post-resignation retraction");
  require(
      first.recorder().timedDirectedInteractions().empty() &&
          second.recorder().timedDirectedInteractions().empty() &&
          first.recorder().timeAdvanceGrants().empty() &&
          second.recorder().timeAdvanceGrants().empty(),
      "timestamped directed interaction source resignation fanout released queued callbacks too early");

  clock.rtiAmbassador().timeAdvanceRequest(*firstClockTarget);
  waitFor(
      clock,
      [&] { return clock.recorder().timeAdvanceGrants().size() >= 1U; },
      options,
      "timestamped directed interaction source resignation fanout first clock frontier");
  waitFor(
      first,
      [&] {
        return first.recorder().timedDirectedInteractions().size() >= 1U &&
            first.recorder().timeAdvanceGrants().size() >= 1U;
      },
      options,
      "timestamped directed interaction source resignation fanout first delivery and grant");
  require(
      second.recorder().timedDirectedInteractions().empty() &&
          second.recorder().timeAdvanceGrants().empty(),
      "timestamped directed interaction source resignation fanout drained the second recipient early");

  second.rtiAmbassador().timeAdvanceRequest(*secondTarget);
  clock.rtiAmbassador().timeAdvanceRequest(*secondClockTarget);
  waitFor(
      clock,
      [&] { return clock.recorder().timeAdvanceGrants().size() >= 2U; },
      options,
      "timestamped directed interaction source resignation fanout second clock frontier");
  waitFor(
      second,
      [&] {
        return second.recorder().timedDirectedInteractions().size() >= 1U &&
            second.recorder().timeAdvanceGrants().size() >= 1U;
      },
      options,
      "timestamped directed interaction source resignation fanout second delivery and grant");

  auto assertDirected = [&](Session& receiver,
                            rti::InteractionClassHandle const& expectedInteraction,
                            rti::ParameterHandle const& expectedParameter,
                            auto const& record,
                            std::vector<std::uint8_t> const& expectedGrant,
                            std::wstring const& expectedGrantText) {
    require(
        record.interaction == expectedInteraction && record.object == target &&
            record.parameters.size() == 1U &&
            record.parameters.count(expectedParameter) == 1U &&
            copyBytes(record.parameters.at(expectedParameter)) == parameterBytes,
        "timestamped directed interaction source resignation fanout returned the wrong target or parameter");
    require(
        record.tag == tagBytes && record.time == encodeTime(*messageTime) &&
            !record.timeText.empty(),
        "timestamped directed interaction source resignation fanout did not preserve payload or time");
    require(
        record.producer == publisher.federateHandle() &&
            record.sentOrder == rti::TIMESTAMP &&
            record.receivedOrder == rti::TIMESTAMP,
        "timestamped directed interaction source resignation fanout returned the wrong producer or order metadata");
    require(
        record.transportation.isValid() &&
            !receiver.rtiAmbassador().getTransportationTypeName(
                record.transportation).empty(),
        "timestamped directed interaction source resignation fanout returned an unresolvable transport");
    require(
        record.retractionPresent &&
            record.retraction == copyBytes(retraction.encode()),
        "timestamped directed interaction source resignation fanout omitted its retraction handle");
    require(
        receiver.recorder().timeAdvanceGrants().size() == 1U &&
            receiver.recorder().timeAdvanceGrants().front().encoded == expectedGrant,
        "timestamped directed interaction source resignation fanout returned the wrong recipient grant (actual=" +
            toNarrow(receiver.recorder().timeAdvanceGrants().front().text) +
            ", expected=" + toNarrow(expectedGrantText) + ")");
    require(
        receiver.recorder().callbackOrder() ==
            std::vector<std::string>{"directed", "grant"},
        "timestamped directed interaction source resignation fanout delivered after a grant");
  };
  require(
      first.recorder().timedDirectedInteractions().size() == 1U &&
          second.recorder().timedDirectedInteractions().size() == 1U,
      "timestamped directed interaction source resignation fanout returned duplicate deliveries");
  assertDirected(
      first,
      firstInteraction,
      firstParameter,
      first.recorder().timedDirectedInteractions().front(),
      encodeTime(*firstTarget),
      firstTarget->toString());
  assertDirected(
      second,
      secondInteraction,
      secondParameter,
      second.recorder().timedDirectedInteractions().front(),
      encodeTime(*secondTarget),
      secondTarget->toString());

  first.rtiAmbassador().disableTimeConstrained();
  second.rtiAmbassador().disableTimeConstrained();
  clock.rtiAmbassador().disableTimeRegulation();
  first.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      firstClass,
      firstDirectedInteractions);
  second.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      secondClass,
      secondDirectedInteractions);
  first.rtiAmbassador().unsubscribeObjectClassAttributes(
      firstClass,
      firstAttributes);
  second.rtiAmbassador().unsubscribeObjectClassAttributes(
      secondClass,
      secondAttributes);
  owner.rtiAmbassador().unpublishObjectClassAttributes(
      ownerClass,
      ownerAttributes);
  first.resign(rti::NO_ACTION);
  second.resign(rti::NO_ACTION);
  clock.resign(rti::NO_ACTION);
  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  publisher.disconnect();
  first.disconnect();
  second.disconnect();
  clock.disconnect();
  owner.disconnect();
}

void scenarioDirectedInteractions(Options const& options, rti::CallbackModel model) {
  Session directedLifecycle(options, model, "directed-lifecycle");
  rti::ObjectClassHandle const lifecycleInvalidObjectClass;
  rti::InteractionClassHandle const invalidDirectedInteractionClass;
  rti::ObjectInstanceHandle const invalidDirectedObject;
  rti::InteractionClassHandleSet const emptyDirectedInteractions;
  rti::ParameterHandleValueMap const emptyDirectedParameters;
  rti::VariableLengthData const emptyDirectedTag;
  auto requireDirectedLifecycle = [&](std::wstring const& expected,
                                      std::string const& phase) {
    requireException(
        [&] {
          directedLifecycle.rtiAmbassador().publishObjectClassDirectedInteractions(
              lifecycleInvalidObjectClass,
              emptyDirectedInteractions);
        },
        expected,
        "publishing directed interactions " + phase);
    requireException(
        [&] {
          directedLifecycle.rtiAmbassador().unpublishObjectClassDirectedInteractions(
              lifecycleInvalidObjectClass);
        },
        expected,
        "unpublishing all directed interactions " + phase);
    requireException(
        [&] {
          directedLifecycle.rtiAmbassador().unpublishObjectClassDirectedInteractions(
              lifecycleInvalidObjectClass,
              emptyDirectedInteractions);
        },
        expected,
        "unpublishing selected directed interactions " + phase);
    requireException(
        [&] {
          directedLifecycle.rtiAmbassador().subscribeObjectClassDirectedInteractions(
              lifecycleInvalidObjectClass,
              emptyDirectedInteractions,
              false);
        },
        expected,
        "subscribing directed interactions " + phase);
    requireException(
        [&] {
          directedLifecycle.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
              lifecycleInvalidObjectClass);
        },
        expected,
        "unsubscribing all directed interactions " + phase);
    requireException(
        [&] {
          directedLifecycle.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
              lifecycleInvalidObjectClass,
              emptyDirectedInteractions);
        },
        expected,
        "unsubscribing selected directed interactions " + phase);
    requireException(
        [&] {
          directedLifecycle.rtiAmbassador().sendDirectedInteraction(
              invalidDirectedInteractionClass,
              invalidDirectedObject,
              emptyDirectedParameters,
              emptyDirectedTag);
        },
        expected,
        "sending a directed interaction " + phase);
  };
  requireDirectedLifecycle(L"NotConnected", "before connect");
  directedLifecycle.connect();
  requireDirectedLifecycle(L"FederateNotExecutionMember", "after connect before join");
  directedLifecycle.disconnect();

  Session publisher(options, model, "owner");
  Session targeted(options, model, "member");
  Session universal(options, rti::HLA_IMMEDIATE, "member");
  Session unsubscribed(options, model, "member");
  auto const federation = federationName(options, "directed-interactions");

  publisher.connect();
  targeted.connect();
  universal.connect();
  unsubscribed.connect();
  publisher.rtiAmbassador().createFederationExecution(
      federation,
      options.fom.wstring(),
      options.logicalTimeImplementationName);
  publisher.join(
      options.ownerFederateName + L"-directed-publisher",
      options.federateType,
      federation);
  targeted.join(
      options.memberFederateName + L"-directed-targeted",
      options.federateType,
      federation);
  universal.join(
      options.memberFederateName + L"-directed-universal",
      options.federateType,
      federation);
  unsubscribed.join(
      options.memberFederateName + L"-directed-none",
      options.federateType,
      federation);

  auto const publisherClass = publisher.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const targetedClass = targeted.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const universalClass = universal.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const unsubscribedClass = unsubscribed.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  require(publisherClass.isValid() && targetedClass.isValid() && universalClass.isValid() &&
              unsubscribedClass.isValid(),
          "Directed interaction object-class lookup returned an invalid handle");

  auto const publisherAttribute = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass, options.attributeName);
  auto const targetedAttribute = targeted.rtiAmbassador().getAttributeHandle(
      targetedClass, options.attributeName);
  auto const universalAttribute = universal.rtiAmbassador().getAttributeHandle(
      universalClass, options.attributeName);
  auto const unsubscribedAttribute = unsubscribed.rtiAmbassador().getAttributeHandle(
      unsubscribedClass, options.attributeName);
  require(publisherAttribute.isValid() && targetedAttribute.isValid() &&
              universalAttribute.isValid() && unsubscribedAttribute.isValid(),
          "Directed interaction attribute lookup returned an invalid handle");
  rti::AttributeHandleSet publisherAttributes;
  publisherAttributes.insert(publisherAttribute);
  rti::AttributeHandleSet targetedAttributes;
  targetedAttributes.insert(targetedAttribute);
  rti::AttributeHandleSet universalAttributes;
  universalAttributes.insert(universalAttribute);
  rti::AttributeHandleSet unsubscribedAttributes;
  unsubscribedAttributes.insert(unsubscribedAttribute);

  auto const publisherInteraction = publisher.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const targetedInteraction = targeted.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const universalInteraction = universal.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  require(publisherInteraction.isValid() && targetedInteraction.isValid() &&
              universalInteraction.isValid(),
          "Directed interaction class lookup returned an invalid handle");
  rti::InteractionClassHandleSet publisherDirected;
  publisherDirected.insert(publisherInteraction);
  rti::InteractionClassHandleSet targetedDirected;
  targetedDirected.insert(targetedInteraction);
  rti::InteractionClassHandleSet universalDirected;
  universalDirected.insert(universalInteraction);

  rti::ObjectClassHandle const invalidObjectClass;
  rti::InteractionClassHandleSet const invalidDirected{
      rti::InteractionClassHandle{}};
  requireException(
      [&] {
        publisher.rtiAmbassador().publishObjectClassDirectedInteractions(
            invalidObjectClass,
            rti::InteractionClassHandleSet{});
      },
      L"ObjectClassNotDefined",
      "publishing directed interactions for an invalid object class");
  requireException(
      [&] {
        publisher.rtiAmbassador().publishObjectClassDirectedInteractions(
            publisherClass,
            invalidDirected);
      },
      L"InteractionClassNotDefined",
      "publishing an invalid directed interaction class");
  requireException(
      [&] {
        publisher.rtiAmbassador().unpublishObjectClassDirectedInteractions(
            invalidObjectClass,
            rti::InteractionClassHandleSet{});
      },
      L"ObjectClassNotDefined",
      "unpublishing directed interactions for an invalid object class");
  requireException(
      [&] {
        publisher.rtiAmbassador().unpublishObjectClassDirectedInteractions(
            publisherClass,
            invalidDirected);
      },
      L"InteractionClassNotDefined",
      "unpublishing an invalid directed interaction class");
  requireException(
      [&] {
        targeted.rtiAmbassador().subscribeObjectClassDirectedInteractions(
            invalidObjectClass,
            rti::InteractionClassHandleSet{},
            false);
      },
      L"ObjectClassNotDefined",
      "subscribing directed interactions for an invalid object class");
  requireException(
      [&] {
        targeted.rtiAmbassador().subscribeObjectClassDirectedInteractions(
            targetedClass,
            invalidDirected,
            false);
      },
      L"InteractionClassNotDefined",
      "subscribing an invalid directed interaction class");
  requireException(
      [&] {
        targeted.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
            invalidObjectClass,
            rti::InteractionClassHandleSet{});
      },
      L"ObjectClassNotDefined",
      "unsubscribing directed interactions for an invalid object class");
  requireException(
      [&] {
        targeted.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
            targetedClass,
            invalidDirected);
      },
      L"InteractionClassNotDefined",
      "unsubscribing an invalid directed interaction class");

  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherClass, publisherAttributes);
  targeted.rtiAmbassador().publishObjectClassAttributes(
      targetedClass, targetedAttributes);
  publisher.rtiAmbassador().subscribeObjectClassAttributes(
      publisherClass, publisherAttributes, true, L"");
  targeted.rtiAmbassador().subscribeObjectClassAttributes(
      targetedClass, targetedAttributes, true, L"");
  universal.rtiAmbassador().subscribeObjectClassAttributes(
      universalClass, universalAttributes, true, L"");
  unsubscribed.rtiAmbassador().subscribeObjectClassAttributes(
      unsubscribedClass, unsubscribedAttributes, true, L"");

  publisher.rtiAmbassador().publishObjectClassDirectedInteractions(
      publisherClass, publisherDirected);
  publisher.rtiAmbassador().publishObjectClassDirectedInteractions(
      publisherClass, publisherDirected);
  requireException(
      [&] {
        publisher.rtiAmbassador().sendDirectedInteraction(
            publisherInteraction,
            rti::ObjectInstanceHandle{},
            rti::ParameterHandleValueMap{},
            rti::VariableLengthData{});
      },
      L"ObjectInstanceNotKnown",
      "directed send with an unknown target object");
  targeted.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      targetedClass, targetedDirected, false);
  universal.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      universalClass, universalDirected, true);

  auto const publisherTarget = publisher.rtiAmbassador().registerObjectInstance(publisherClass);
  auto const targetedTarget = targeted.rtiAmbassador().registerObjectInstance(targetedClass);
  require(publisherTarget.isValid() && targetedTarget.isValid(),
          "Directed interaction registration returned an invalid handle");
  waitFor(publisher, [&] { return publisher.recorder().hasDiscovery(targetedTarget); }, options,
          "publisher discovery of the targeted object");
  waitFor(targeted, [&] { return targeted.recorder().hasDiscovery(publisherTarget); }, options,
          "targeted discovery of the publisher object");
  waitFor(universal, [&] { return universal.recorder().hasDiscovery(publisherTarget); }, options,
          "universal discovery of the publisher object");
  require(
      publisher.rtiAmbassador().getKnownObjectClassHandle(targetedTarget) == publisherClass,
      "publisher did not learn the targeted object's class");

  auto assertDirected = [&](DirectedInteractionRecord const& received,
                           rti::InteractionClassHandle const& expectedInteraction,
                           rti::ObjectInstanceHandle const& expectedTarget,
                           std::vector<std::uint8_t> const& expectedTag,
                           rti::RTIambassador& inspector) {
    require(received.interaction == expectedInteraction,
            "Directed callback carried the wrong interaction class");
    require(received.object == expectedTarget,
            "Directed callback carried the wrong target object");
    require(received.parameters.empty(),
            "Directed callback unexpectedly carried parameters");
    require(received.tag == expectedTag,
            "Directed callback did not preserve the user tag");
    require(received.transportation.isValid(),
            "Directed callback returned an invalid transportation handle");
    require(inspector.getTransportationTypeName(received.transportation) ==
                L"HLAreliable",
            "Directed callback did not preserve the reliable transportation type");
    require(received.producer == publisher.federateHandle(),
            "Directed callback carried the wrong producing federate");
  };

  publisher.recorder().clearDirectedInteractions();
  targeted.recorder().clearDirectedInteractions();
  universal.recorder().clearDirectedInteractions();
  unsubscribed.recorder().clearDirectedInteractions();
  std::vector<std::uint8_t> targetedTagBytes{0x11U, 0x22U, 0x33U};
  rti::VariableLengthData targetedTag(
      targetedTagBytes.data(), targetedTagBytes.size());
  publisher.rtiAmbassador().sendDirectedInteraction(
      publisherInteraction,
      targetedTarget,
      rti::ParameterHandleValueMap{},
      targetedTag);
  require(universal.recorder().directedInteractions().size() == 1U,
          "universal directed subscriber did not receive the targeted send");
  if (model == rti::HLA_EVOKED) {
    require(targeted.recorder().directedInteractions().empty(),
            "evoked targeted subscriber received directed data before callback drain");
  }
  waitFor(targeted,
          [&] { return targeted.recorder().directedInteractions().size() == 1U; },
          options,
          "targeted directed interaction delivery");
  auto const targetedReceived = targeted.recorder().directedInteractions();
  auto const universalReceived = universal.recorder().directedInteractions();
  assertDirected(
      targetedReceived.at(0),
      targetedInteraction,
      targetedTarget,
      targetedTagBytes,
      targeted.rtiAmbassador());
  assertDirected(
      universalReceived.at(0),
      universalInteraction,
      targetedTarget,
      targetedTagBytes,
      universal.rtiAmbassador());
  require(unsubscribed.recorder().directedInteractions().empty(),
          "unsubscribed member received a directed interaction");

  std::vector<std::uint8_t> publisherTagBytes{0x44U};
  rti::VariableLengthData publisherTag(
      publisherTagBytes.data(), publisherTagBytes.size());
  publisher.rtiAmbassador().sendDirectedInteraction(
      publisherInteraction,
      publisherTarget,
      rti::ParameterHandleValueMap{},
      publisherTag);
  require(universal.recorder().directedInteractions().size() == 2U,
          "universal directed subscriber did not receive a second target");
  for (int pass = 0; pass != 8; ++pass) {
    targeted.pump();
  }
  require(targeted.recorder().directedInteractions().size() == 1U,
          "by-ownership directed subscriber received another owner's target");
  assertDirected(
      universal.recorder().directedInteractions().at(1),
      universalInteraction,
      publisherTarget,
      publisherTagBytes,
      universal.rtiAmbassador());

  targeted.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      targetedClass, targetedDirected);
  targeted.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      targetedClass, targetedDirected);
  universal.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(universalClass);
  std::vector<std::uint8_t> suppressedTagBytes{0x55U};
  rti::VariableLengthData suppressedTag(
      suppressedTagBytes.data(), suppressedTagBytes.size());
  publisher.rtiAmbassador().sendDirectedInteraction(
      publisherInteraction,
      targetedTarget,
      rti::ParameterHandleValueMap{},
      suppressedTag);
  for (int pass = 0; pass != 8; ++pass) {
    targeted.pump();
    universal.pump();
  }
  require(targeted.recorder().directedInteractions().size() == 1U,
          "unsubscribed targeted member received a later directed interaction");
  require(universal.recorder().directedInteractions().size() == 2U,
          "unsubscribed universal member received a later directed interaction");

  publisher.rtiAmbassador().unpublishObjectClassDirectedInteractions(
      publisherClass, publisherDirected);
  publisher.rtiAmbassador().unpublishObjectClassDirectedInteractions(
      publisherClass, publisherDirected);
  requireException(
      [&] {
        publisher.rtiAmbassador().sendDirectedInteraction(
            publisherInteraction,
            targetedTarget,
            rti::ParameterHandleValueMap{},
            rti::VariableLengthData{});
      },
      L"InteractionClassNotPublished",
      "directed send after unpublication");
  requireException(
      [&] {
        static_cast<void>(publisher.rtiAmbassador().getObjectInstanceHandle(
            federation + L"-no-such-directed-object"));
      },
      L"ObjectInstanceNotKnown",
      "unknown directed target lookup");

  targeted.rtiAmbassador().unsubscribeObjectClass(targetedClass);
  universal.rtiAmbassador().unsubscribeObjectClass(universalClass);
  unsubscribed.rtiAmbassador().unsubscribeObjectClass(unsubscribedClass);
  publisher.rtiAmbassador().unsubscribeObjectClass(publisherClass);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherClass, publisherAttributes);
  targeted.rtiAmbassador().unpublishObjectClassAttributes(
      targetedClass, targetedAttributes);

  publisher.resign(rti::DELETE_OBJECTS);
  targeted.resign(rti::DELETE_OBJECTS);
  universal.resign(rti::NO_ACTION);
  unsubscribed.resign(rti::NO_ACTION);
}

void scenarioDirectedInteractionContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioDirectedInteractions(options, model);
}

void scenarioDirectedInteractionMultiRecipientFifo(
    Options const& options,
    rti::CallbackModel model) {
  Session publisher(options, model, "directed-interaction-fanout-publisher");
  Session first(options, model, "directed-interaction-fanout-first");
  Session second(options, model, "directed-interaction-fanout-second");
  auto const federation = federationName(
      options,
      "directed-interaction-multi-recipient-fifo");
  connectAndJoin(publisher, first, options, federation, options.fom);
  second.connect();
  second.join(
      options.memberFederateName + L"-second",
      options.federateType,
      federation);

  auto const publisherClass = publisher.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const firstClass = first.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const secondClass = second.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const publisherAttribute = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass,
      options.attributeName);
  auto const firstAttribute = first.rtiAmbassador().getAttributeHandle(
      firstClass,
      options.attributeName);
  auto const secondAttribute = second.rtiAmbassador().getAttributeHandle(
      secondClass,
      options.attributeName);
  auto const publisherInteraction =
      publisher.rtiAmbassador().getInteractionClassHandle(
          options.interactionClassName);
  auto const firstInteraction = first.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const secondInteraction = second.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const publisherParameter = publisher.rtiAmbassador().getParameterHandle(
      publisherInteraction,
      options.parameterName);
  auto const firstParameter = first.rtiAmbassador().getParameterHandle(
      firstInteraction,
      options.parameterName);
  auto const secondParameter = second.rtiAmbassador().getParameterHandle(
      secondInteraction,
      options.parameterName);
  require(
      publisherClass.isValid() && firstClass.isValid() && secondClass.isValid() &&
          publisherAttribute.isValid() && firstAttribute.isValid() &&
          secondAttribute.isValid() && publisherInteraction.isValid() &&
          firstInteraction.isValid() && secondInteraction.isValid() &&
          publisherParameter.isValid() && firstParameter.isValid() &&
          secondParameter.isValid(),
      "directed interaction multi-recipient FIFO lookup returned an invalid handle");

  rti::AttributeHandleSet const publisherAttributes{publisherAttribute};
  rti::AttributeHandleSet const firstAttributes{firstAttribute};
  rti::AttributeHandleSet const secondAttributes{secondAttribute};
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  first.rtiAmbassador().subscribeObjectClassAttributes(
      firstClass,
      firstAttributes,
      true,
      L"");
  second.rtiAmbassador().subscribeObjectClassAttributes(
      secondClass,
      secondAttributes,
      true,
      L"");

  rti::InteractionClassHandleSet const publisherDirected{publisherInteraction};
  rti::InteractionClassHandleSet const firstDirected{firstInteraction};
  rti::InteractionClassHandleSet const secondDirected{secondInteraction};
  publisher.rtiAmbassador().publishObjectClassDirectedInteractions(
      publisherClass,
      publisherDirected);
  first.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      firstClass,
      firstDirected,
      true);
  second.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      secondClass,
      secondDirected,
      true);

  auto const target = publisher.rtiAmbassador().registerObjectInstance(publisherClass);
  require(
      target.isValid(),
      "directed interaction multi-recipient FIFO registration returned an invalid target");
  waitForSessions(
      {&first, &second},
      [&] {
        return first.recorder().hasDiscovery(target) &&
            second.recorder().hasDiscovery(target);
      },
      options,
      "directed interaction multi-recipient FIFO target discovery");

  publisher.recorder().clearDirectedInteractions();
  first.recorder().clearDirectedInteractions();
  second.recorder().clearDirectedInteractions();
  auto send = [&](std::vector<std::uint8_t> const& value,
                  std::vector<std::uint8_t> const& tagBytes) {
    rti::ParameterHandleValueMap parameters;
    parameters.emplace(
        publisherParameter,
        rti::VariableLengthData(value.data(), value.size()));
    rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
    publisher.rtiAmbassador().sendDirectedInteraction(
        publisherInteraction,
        target,
        parameters,
        tag);
  };

  std::vector<std::uint8_t> const firstValue{
      0x46U, 0x49U, 0x52U, 0x53U, 0x54U};
  std::vector<std::uint8_t> const firstTag{0x31U};
  std::vector<std::uint8_t> const secondValue{
      0x53U, 0x45U, 0x43U, 0x4FU, 0x4EU, 0x44U};
  std::vector<std::uint8_t> const secondTag{0x32U};
  send(firstValue, firstTag);
  send(secondValue, secondTag);

  waitForSessions(
      {&first, &second},
      [&] {
        return first.recorder().directedInteractions().size() >= 2U &&
            second.recorder().directedInteractions().size() >= 2U;
      },
      options,
      "directed interaction multi-recipient FIFO delivery");
  require(
      publisher.recorder().directedInteractions().empty(),
      "directed interaction multi-recipient FIFO delivered an interaction back to its sender");

  auto assertDelivery = [&](Session& receiver,
                            rti::InteractionClassHandle const& interaction,
                            rti::ParameterHandle const& parameter,
                            std::string const& description) {
    auto const received = receiver.recorder().directedInteractions();
    require(
        received.size() == 2U,
        description + " returned an unexpected callback count");
    auto assertRecord = [&](DirectedInteractionRecord const& record,
                            std::vector<std::uint8_t> const& expectedValue,
                            std::vector<std::uint8_t> const& expectedTag,
                            std::string const& orderDescription) {
      require(
          record.interaction == interaction && record.object == target &&
              record.parameters.size() == 1U &&
              record.parameters.count(parameter) == 1U &&
              copyBytes(record.parameters.at(parameter)) == expectedValue,
          orderDescription + " returned the wrong target or parameter value");
      require(
          record.tag == expectedTag,
          orderDescription + " returned the wrong user tag");
      require(
          record.producer == publisher.federateHandle(),
          orderDescription + " returned the wrong producing federate");
      require(
          record.transportation.isValid() &&
              !receiver.rtiAmbassador()
                   .getTransportationTypeName(record.transportation)
                   .empty(),
          orderDescription + " returned an unknown transportation type");
    };
    assertRecord(
        received.front(),
        firstValue,
        firstTag,
        description + " first receive-order callback");
    assertRecord(
        received.back(),
        secondValue,
        secondTag,
        description + " second receive-order callback");
  };
  assertDelivery(
      first,
      firstInteraction,
      firstParameter,
      "first directed interaction recipient");
  assertDelivery(
      second,
      secondInteraction,
      secondParameter,
      "second directed interaction recipient");

  first.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      firstClass,
      firstDirected);
  second.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      secondClass,
      secondDirected);
  publisher.rtiAmbassador().unpublishObjectClassDirectedInteractions(
      publisherClass,
      publisherDirected);
  first.rtiAmbassador().unsubscribeObjectClassAttributes(
      firstClass,
      firstAttributes);
  second.rtiAmbassador().unsubscribeObjectClassAttributes(
      secondClass,
      secondAttributes);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  second.resign(rti::NO_ACTION);
  first.resign(rti::NO_ACTION);
  publisher.resign(rti::DELETE_OBJECTS);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  second.disconnect();
  first.disconnect();
  publisher.disconnect();
}

void scenarioDirectedInteractionMultiRecipientFifoContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioDirectedInteractionMultiRecipientFifo(options, model);
}

void scenarioDirectedInteractionMixedSubscriptionFanout(
    Options const& options,
    rti::CallbackModel model) {
  Session publisher(options, model, "directed-interaction-mixed-publisher");
  Session owner(options, model, "directed-interaction-mixed-owner");
  Session universalFirst(options, model, "directed-interaction-mixed-universal-first");
  Session universalSecond(options, model, "directed-interaction-mixed-universal-second");
  Session silent(options, model, "directed-interaction-mixed-silent");
  auto const federation = federationName(
      options,
      "directed-interaction-mixed-subscription-fanout");
  connectAndJoin(publisher, owner, options, federation, options.fom);
  universalFirst.connect();
  universalFirst.join(
      options.memberFederateName + L"-universal-first",
      options.federateType,
      federation);
  universalSecond.connect();
  universalSecond.join(
      options.memberFederateName + L"-universal-second",
      options.federateType,
      federation);
  silent.connect();
  silent.join(
      options.memberFederateName + L"-silent",
      options.federateType,
      federation);

  auto const publisherClass = publisher.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const ownerClass = owner.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const universalFirstClass = universalFirst.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const universalSecondClass = universalSecond.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const silentClass = silent.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const publisherAttribute = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass,
      options.attributeName);
  auto const ownerAttribute = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.attributeName);
  auto const universalFirstAttribute = universalFirst.rtiAmbassador().getAttributeHandle(
      universalFirstClass,
      options.attributeName);
  auto const universalSecondAttribute = universalSecond.rtiAmbassador().getAttributeHandle(
      universalSecondClass,
      options.attributeName);
  auto const silentAttribute = silent.rtiAmbassador().getAttributeHandle(
      silentClass,
      options.attributeName);
  auto const publisherInteraction =
      publisher.rtiAmbassador().getInteractionClassHandle(
          options.interactionClassName);
  auto const ownerInteraction = owner.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const universalFirstInteraction =
      universalFirst.rtiAmbassador().getInteractionClassHandle(
          options.interactionClassName);
  auto const universalSecondInteraction =
      universalSecond.rtiAmbassador().getInteractionClassHandle(
          options.interactionClassName);
  auto const ownerParameter = owner.rtiAmbassador().getParameterHandle(
      ownerInteraction,
      options.parameterName);
  auto const publisherParameter = publisher.rtiAmbassador().getParameterHandle(
      publisherInteraction,
      options.parameterName);
  auto const universalFirstParameter = universalFirst.rtiAmbassador().getParameterHandle(
      universalFirstInteraction,
      options.parameterName);
  auto const universalSecondParameter = universalSecond.rtiAmbassador().getParameterHandle(
      universalSecondInteraction,
      options.parameterName);
  require(
      publisherClass.isValid() && ownerClass.isValid() &&
          universalFirstClass.isValid() && universalSecondClass.isValid() &&
          silentClass.isValid() && publisherAttribute.isValid() &&
          ownerAttribute.isValid() && universalFirstAttribute.isValid() &&
          universalSecondAttribute.isValid() && silentAttribute.isValid() &&
          publisherInteraction.isValid() && ownerInteraction.isValid() &&
          universalFirstInteraction.isValid() && universalSecondInteraction.isValid() &&
          publisherParameter.isValid() && ownerParameter.isValid() &&
          universalFirstParameter.isValid() && universalSecondParameter.isValid(),
      "directed interaction mixed subscription fan-out lookup returned an invalid handle");

  rti::AttributeHandleSet const publisherAttributes{publisherAttribute};
  rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
  rti::AttributeHandleSet const universalFirstAttributes{universalFirstAttribute};
  rti::AttributeHandleSet const universalSecondAttributes{universalSecondAttribute};
  rti::AttributeHandleSet const silentAttributes{silentAttribute};
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  publisher.rtiAmbassador().subscribeObjectClassAttributes(
      publisherClass,
      publisherAttributes,
      true,
      L"");
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  universalFirst.rtiAmbassador().subscribeObjectClassAttributes(
      universalFirstClass,
      universalFirstAttributes,
      true,
      L"");
  universalSecond.rtiAmbassador().subscribeObjectClassAttributes(
      universalSecondClass,
      universalSecondAttributes,
      true,
      L"");
  silent.rtiAmbassador().subscribeObjectClassAttributes(
      silentClass,
      silentAttributes,
      true,
      L"");

  rti::InteractionClassHandleSet const publisherDirected{publisherInteraction};
  rti::InteractionClassHandleSet const ownerDirected{ownerInteraction};
  rti::InteractionClassHandleSet const universalFirstDirected{universalFirstInteraction};
  rti::InteractionClassHandleSet const universalSecondDirected{universalSecondInteraction};
  publisher.rtiAmbassador().publishObjectClassDirectedInteractions(
      publisherClass,
      publisherDirected);
  owner.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      ownerClass,
      ownerDirected,
      false);
  universalFirst.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      universalFirstClass,
      universalFirstDirected,
      true);
  universalSecond.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      universalSecondClass,
      universalSecondDirected,
      true);

  auto const ownerTarget = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  auto const publisherTarget = publisher.rtiAmbassador().registerObjectInstance(publisherClass);
  require(
      ownerTarget.isValid() && publisherTarget.isValid(),
      "directed interaction mixed subscription fan-out registration returned an invalid target");
  waitForSessions(
      {&publisher, &universalFirst, &universalSecond, &silent},
      [&] {
        return publisher.recorder().hasDiscovery(ownerTarget) &&
            universalFirst.recorder().hasDiscovery(ownerTarget) &&
            universalFirst.recorder().hasDiscovery(publisherTarget) &&
            universalSecond.recorder().hasDiscovery(ownerTarget) &&
            universalSecond.recorder().hasDiscovery(publisherTarget) &&
            silent.recorder().hasDiscovery(ownerTarget) &&
            silent.recorder().hasDiscovery(publisherTarget);
      },
      options,
      "directed interaction mixed subscription fan-out target discovery");

  publisher.recorder().clearDirectedInteractions();
  owner.recorder().clearDirectedInteractions();
  universalFirst.recorder().clearDirectedInteractions();
  universalSecond.recorder().clearDirectedInteractions();
  silent.recorder().clearDirectedInteractions();
  auto send = [&](rti::ObjectInstanceHandle const& target,
                  std::vector<std::uint8_t> const& value,
                  std::vector<std::uint8_t> const& tagBytes) {
    rti::ParameterHandleValueMap parameters;
    parameters.emplace(
        publisherParameter,
        rti::VariableLengthData(value.data(), value.size()));
    rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
    publisher.rtiAmbassador().sendDirectedInteraction(
        publisherInteraction,
        target,
        parameters,
        tag);
  };

  std::vector<std::uint8_t> const ownerFirstValue{0x4fU, 0x31U};
  std::vector<std::uint8_t> const ownerFirstTag{0x61U};
  std::vector<std::uint8_t> const ownerSecondValue{0x4fU, 0x32U};
  std::vector<std::uint8_t> const ownerSecondTag{0x62U};
  send(ownerTarget, ownerFirstValue, ownerFirstTag);
  send(ownerTarget, ownerSecondValue, ownerSecondTag);
  waitForSessions(
      {&owner, &universalFirst, &universalSecond},
      [&] {
        return owner.recorder().directedInteractions().size() >= 2U &&
            universalFirst.recorder().directedInteractions().size() >= 2U &&
            universalSecond.recorder().directedInteractions().size() >= 2U;
      },
      options,
      "directed interaction mixed subscription fan-out owner-target delivery");

  auto assertDelivery = [&](Session& receiver,
                            DirectedInteractionRecord const& record,
                            rti::InteractionClassHandle const& expectedInteraction,
                            rti::ParameterHandle const& expectedParameter,
                            rti::ObjectInstanceHandle const& expectedTarget,
                            std::vector<std::uint8_t> const& expectedValue,
                            std::vector<std::uint8_t> const& expectedTag,
                            std::string const& description) {
    require(
        record.interaction == expectedInteraction && record.object == expectedTarget &&
            record.parameters.size() == 1U &&
            record.parameters.count(expectedParameter) == 1U &&
            copyBytes(record.parameters.at(expectedParameter)) == expectedValue,
        description + " returned the wrong target or parameter value");
    require(
        record.tag == expectedTag,
        description + " did not preserve the user tag");
    require(
        record.producer == publisher.federateHandle(),
        description + " returned the wrong producing federate");
    require(
        record.transportation.isValid() &&
            !receiver.rtiAmbassador()
                 .getTransportationTypeName(record.transportation)
                 .empty(),
        description + " returned an unknown transportation type");
  };
  auto assertOwnerTargetDeliveries = [&](Session& receiver,
                                         rti::InteractionClassHandle const& interaction,
                                         rti::ParameterHandle const& parameter,
                                         std::string const& description) {
    auto const received = receiver.recorder().directedInteractions();
    require(
        received.size() == 2U,
        description + " returned an unexpected owner-target callback count");
    assertDelivery(
        receiver,
        received.at(0),
        interaction,
        parameter,
        ownerTarget,
        ownerFirstValue,
        ownerFirstTag,
        description + " first callback");
    assertDelivery(
        receiver,
        received.at(1),
        interaction,
        parameter,
        ownerTarget,
        ownerSecondValue,
        ownerSecondTag,
        description + " second callback");
  };
  assertOwnerTargetDeliveries(
      owner,
      ownerInteraction,
      ownerParameter,
      "by-ownership directed subscriber");
  assertOwnerTargetDeliveries(
      universalFirst,
      universalFirstInteraction,
      universalFirstParameter,
      "first universal directed subscriber");
  assertOwnerTargetDeliveries(
      universalSecond,
      universalSecondInteraction,
      universalSecondParameter,
      "second universal directed subscriber");
  require(
      publisher.recorder().directedInteractions().empty() &&
          silent.recorder().directedInteractions().empty(),
      "directed interaction mixed subscription fan-out delivered to an unrelated subscriber");

  std::vector<std::uint8_t> const publisherValue{0x50U, 0x31U};
  std::vector<std::uint8_t> const publisherTag{0x71U};
  send(publisherTarget, publisherValue, publisherTag);
  waitForSessions(
      {&universalFirst, &universalSecond},
      [&] {
        return universalFirst.recorder().directedInteractions().size() >= 3U &&
            universalSecond.recorder().directedInteractions().size() >= 3U;
      },
      options,
      "directed interaction mixed subscription fan-out second-target delivery");
  for (int pass = 0; pass != 8; ++pass) {
    owner.pump();
    silent.pump();
  }
  require(
      owner.recorder().directedInteractions().size() == 2U &&
          silent.recorder().directedInteractions().empty(),
      "directed interaction mixed subscription fan-out ignored subscription kind");
  assertDelivery(
      universalFirst,
      universalFirst.recorder().directedInteractions().at(2),
      universalFirstInteraction,
      universalFirstParameter,
      publisherTarget,
      publisherValue,
      publisherTag,
      "first universal second-target callback");
  assertDelivery(
      universalSecond,
      universalSecond.recorder().directedInteractions().at(2),
      universalSecondInteraction,
      universalSecondParameter,
      publisherTarget,
      publisherValue,
      publisherTag,
      "second universal second-target callback");
  require(
      publisher.recorder().directedInteractions().empty(),
      "directed interaction mixed subscription fan-out delivered back to publisher");

  owner.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      ownerClass,
      ownerDirected);
  universalFirst.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      universalFirstClass,
      universalFirstDirected);
  universalSecond.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      universalSecondClass,
      universalSecondDirected);
  publisher.rtiAmbassador().unpublishObjectClassDirectedInteractions(
      publisherClass,
      publisherDirected);
  publisher.rtiAmbassador().unsubscribeObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  universalFirst.rtiAmbassador().unsubscribeObjectClassAttributes(
      universalFirstClass,
      universalFirstAttributes);
  universalSecond.rtiAmbassador().unsubscribeObjectClassAttributes(
      universalSecondClass,
      universalSecondAttributes);
  silent.rtiAmbassador().unsubscribeObjectClassAttributes(
      silentClass,
      silentAttributes);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  owner.rtiAmbassador().unpublishObjectClassAttributes(ownerClass, ownerAttributes);
  silent.resign(rti::NO_ACTION);
  universalSecond.resign(rti::NO_ACTION);
  universalFirst.resign(rti::NO_ACTION);
  owner.resign(rti::DELETE_OBJECTS);
  publisher.resign(rti::DELETE_OBJECTS);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  silent.disconnect();
  universalSecond.disconnect();
  universalFirst.disconnect();
  owner.disconnect();
  publisher.disconnect();
}

void scenarioDirectedInteractionMixedSubscriptionFanoutContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioDirectedInteractionMixedSubscriptionFanout(options, model);
}

void scenarioDirectedInteractionPublicationSendFence(
    Options const& options,
    rti::CallbackModel model) {
  Session publisher(options, model, "directed-publication-publisher");
  Session receiver(options, model, "directed-publication-receiver");
  auto const federation = federationName(
      options,
      "directed-interaction-publication-send-fence");

  publisher.connect();
  receiver.connect();
  publisher.rtiAmbassador().createFederationExecution(
      federation,
      options.fom.wstring(),
      options.logicalTimeImplementationName);
  publisher.join(
      options.ownerFederateName + L"-directed-publication-publisher",
      options.federateType,
      federation);
  receiver.join(
      options.memberFederateName + L"-directed-publication-receiver",
      options.federateType,
      federation);

  auto const publisherClass = publisher.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const receiverClass = receiver.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const publisherAttribute = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass,
      options.attributeName);
  auto const receiverAttribute = receiver.rtiAmbassador().getAttributeHandle(
      receiverClass,
      options.attributeName);
  auto const publisherInteraction =
      publisher.rtiAmbassador().getInteractionClassHandle(
          options.interactionClassName);
  auto const receiverInteraction =
      receiver.rtiAmbassador().getInteractionClassHandle(
          options.interactionClassName);
  auto const publisherParameter = publisher.rtiAmbassador().getParameterHandle(
      publisherInteraction,
      options.parameterName);
  auto const receiverParameter = receiver.rtiAmbassador().getParameterHandle(
      receiverInteraction,
      options.parameterName);
  require(
      publisherClass.isValid() && receiverClass.isValid() &&
          publisherAttribute.isValid() && receiverAttribute.isValid() &&
          publisherInteraction.isValid() && receiverInteraction.isValid() &&
          publisherParameter.isValid() && receiverParameter.isValid(),
      "directed interaction publication send fence lookup returned an invalid handle");

  rti::AttributeHandleSet publisherAttributes;
  publisherAttributes.insert(publisherAttribute);
  rti::AttributeHandleSet receiverAttributes;
  receiverAttributes.insert(receiverAttribute);
  rti::InteractionClassHandleSet directedInteractions;
  directedInteractions.insert(publisherInteraction);
  rti::InteractionClassHandleSet receiverDirectedInteractions;
  receiverDirectedInteractions.insert(receiverInteraction);

  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  receiver.rtiAmbassador().publishObjectClassAttributes(
      receiverClass,
      receiverAttributes);
  publisher.rtiAmbassador().subscribeObjectClassAttributes(
      publisherClass,
      publisherAttributes,
      true,
      L"");
  receiver.rtiAmbassador().subscribeObjectClassAttributes(
      receiverClass,
      receiverAttributes,
      true,
      L"");
  publisher.rtiAmbassador().publishObjectClassDirectedInteractions(
      publisherClass,
      directedInteractions);
  receiver.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      receiverClass,
      receiverDirectedInteractions,
      false);

  auto const target = receiver.rtiAmbassador().registerObjectInstance(receiverClass);
  require(
      target.isValid(),
      "directed interaction publication fence registration returned an invalid handle");
  waitFor(
      publisher,
      [&] { return publisher.recorder().hasDiscovery(target); },
      options,
      "directed interaction publication fence target discovery");
  require(
      publisher.rtiAmbassador().getKnownObjectClassHandle(target) == publisherClass,
      "directed interaction publication fence learned the wrong target class");

  auto send = [&](std::vector<std::uint8_t> const& value,
                  std::vector<std::uint8_t> const& tagBytes) {
    rti::ParameterHandleValueMap parameters;
    parameters.emplace(
        publisherParameter,
        rti::VariableLengthData(value.data(), value.size()));
    rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
    publisher.rtiAmbassador().sendDirectedInteraction(
        publisherInteraction,
        target,
        parameters,
        tag);
  };

  publisher.recorder().clearDirectedInteractions();
  receiver.recorder().clearDirectedInteractions();
  std::vector<std::uint8_t> const initialValue{0x44U, 0x49U, 0x52U};
  std::vector<std::uint8_t> const initialTag{0x49U, 0x4EU, 0x49U};
  send(initialValue, initialTag);
  waitFor(
      receiver,
      [&] { return receiver.recorder().directedInteractions().size() == 1U; },
      options,
      "directed interaction publication fence initial delivery");

  auto assertReceived = [&](DirectedInteractionRecord const& received,
                            std::vector<std::uint8_t> const& expectedValue,
                            std::vector<std::uint8_t> const& expectedTag) {
    require(
        received.interaction == receiverInteraction && received.object == target,
        "directed interaction publication fence returned the wrong class or target");
    require(
        received.parameters.size() == 1U &&
            received.parameters.count(receiverParameter) == 1U &&
            copyBytes(received.parameters.at(receiverParameter)) == expectedValue,
        "directed interaction publication fence returned the wrong parameter value");
    require(
        received.tag == expectedTag &&
            received.producer == publisher.federateHandle(),
        "directed interaction publication fence returned the wrong tag or producer");
    require(
        received.transportation.isValid() &&
            receiver.rtiAmbassador().getTransportationTypeName(received.transportation) ==
                L"HLAreliable",
        "directed interaction publication fence returned the wrong transportation");
  };
  assertReceived(
      receiver.recorder().directedInteractions().front(),
      initialValue,
      initialTag);

  publisher.rtiAmbassador().unpublishObjectClassDirectedInteractions(publisherClass);
  std::vector<std::uint8_t> const fencedValue{
      0x46U, 0x45U, 0x4EU, 0x43U, 0x45U};
  std::vector<std::uint8_t> const fencedTag{0x46U, 0x45U, 0x4EU};
  requireException(
      [&] { send(fencedValue, fencedTag); },
      L"InteractionClassNotPublished",
      "directed interaction send after whole-class unpublication");
  for (int pass = 0; pass != 8; ++pass) {
    receiver.pump();
  }
  require(
      receiver.recorder().directedInteractions().size() == 1U,
      "unpublished directed interaction unexpectedly delivered a callback");

  publisher.rtiAmbassador().publishObjectClassDirectedInteractions(
      publisherClass,
      directedInteractions);
  std::vector<std::uint8_t> const restoredValue{
      0x52U, 0x45U, 0x53U, 0x54U, 0x4FU, 0x52U, 0x45U};
  std::vector<std::uint8_t> const restoredTag{0x52U, 0x45U, 0x50U};
  send(restoredValue, restoredTag);
  waitFor(
      receiver,
      [&] { return receiver.recorder().directedInteractions().size() == 2U; },
      options,
      "directed interaction publication fence delivery after republication");
  assertReceived(
      receiver.recorder().directedInteractions().back(),
      restoredValue,
      restoredTag);

  receiver.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      receiverClass,
      receiverDirectedInteractions);
  publisher.rtiAmbassador().unpublishObjectClassDirectedInteractions(
      publisherClass,
      directedInteractions);
  receiver.rtiAmbassador().unsubscribeObjectClassAttributes(
      receiverClass,
      receiverAttributes);
  publisher.rtiAmbassador().unsubscribeObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  receiver.rtiAmbassador().unpublishObjectClassAttributes(
      receiverClass,
      receiverAttributes);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  publisher.resign(rti::NO_ACTION);
  receiver.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

void scenarioDirectedInteractionTargetLifecycle(
    Options const& options,
    rti::CallbackModel model) {
  Session publisher(options, model, "directed-target-publisher");
  Session receiver(options, model, "directed-target-receiver");
  Session immediate(options, rti::HLA_IMMEDIATE, "directed-target-immediate");
  auto const federation = federationName(options, "directed-interaction-target-lifecycle");

  publisher.connect();
  receiver.connect();
  immediate.connect();
  publisher.rtiAmbassador().createFederationExecution(
      federation,
      options.fom.wstring(),
      options.logicalTimeImplementationName);
  publisher.join(
      options.ownerFederateName + L"-directed-target-publisher",
      options.federateType,
      federation);
  receiver.join(
      options.memberFederateName + L"-directed-target-receiver",
      options.federateType,
      federation);
  immediate.join(
      options.memberFederateName + L"-directed-target-immediate",
      options.federateType,
      federation);

  auto const publisherClass = publisher.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const receiverClass = receiver.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const immediateClass = immediate.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  require(
      publisherClass.isValid() && receiverClass.isValid() && immediateClass.isValid(),
      "directed target lifecycle object-class lookup returned an invalid handle");
  auto const publisherAttribute = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass,
      options.attributeName);
  auto const receiverAttribute = receiver.rtiAmbassador().getAttributeHandle(
      receiverClass,
      options.attributeName);
  auto const immediateAttribute = immediate.rtiAmbassador().getAttributeHandle(
      immediateClass,
      options.attributeName);
  auto const publisherInteraction = publisher.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const receiverInteraction = receiver.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const immediateInteraction = immediate.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  require(
      publisherAttribute.isValid() && receiverAttribute.isValid() &&
          immediateAttribute.isValid() && publisherInteraction.isValid() &&
          receiverInteraction.isValid() && immediateInteraction.isValid(),
      "directed target lifecycle lookup returned an invalid handle");

  rti::AttributeHandleSet const publisherAttributes{publisherAttribute};
  rti::AttributeHandleSet const receiverAttributes{receiverAttribute};
  rti::AttributeHandleSet const immediateAttributes{immediateAttribute};
  rti::InteractionClassHandleSet const publisherDirected{publisherInteraction};
  rti::InteractionClassHandleSet const receiverDirected{receiverInteraction};
  rti::InteractionClassHandleSet const immediateDirected{immediateInteraction};
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  receiver.rtiAmbassador().subscribeObjectClassAttributes(
      receiverClass,
      receiverAttributes,
      true,
      L"");
  immediate.rtiAmbassador().subscribeObjectClassAttributes(
      immediateClass,
      immediateAttributes,
      true,
      L"");
  publisher.rtiAmbassador().publishObjectClassDirectedInteractions(
      publisherClass,
      publisherDirected);
  receiver.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      receiverClass,
      receiverDirected,
      true);
  immediate.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      immediateClass,
      immediateDirected,
      true);

  auto const target = publisher.rtiAmbassador().registerObjectInstance(publisherClass);
  require(target.isValid(), "directed target lifecycle registration returned an invalid handle");
  waitFor(
      receiver,
      [&] { return receiver.recorder().hasDiscovery(target); },
      options,
      "directed target lifecycle receiver discovery");
  waitFor(
      immediate,
      [&] { return immediate.recorder().hasDiscovery(target); },
      options,
      "directed target lifecycle immediate discovery");

  auto const assertDirected = [&](DirectedInteractionRecord const& received,
                                 rti::InteractionClassHandle const& expectedInteraction,
                                 std::vector<std::uint8_t> const& expectedTag,
                                 rti::RTIambassador& inspector) {
    require(
        received.interaction == expectedInteraction && received.object == target,
        "directed target lifecycle returned the wrong interaction or target");
    require(
        received.parameters.empty() && received.tag == expectedTag,
        "directed target lifecycle did not preserve directed payload metadata");
    require(
        received.transportation.isValid() &&
            inspector.getTransportationTypeName(received.transportation) == L"HLAreliable",
        "directed target lifecycle did not preserve reliable transportation");
    require(
        received.producer == publisher.federateHandle(),
        "directed target lifecycle returned the wrong producing federate");
  };
  auto send = [&](std::vector<std::uint8_t> const& tagBytes) {
    rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
    publisher.rtiAmbassador().sendDirectedInteraction(
        publisherInteraction,
        target,
        rti::ParameterHandleValueMap{},
        tag);
  };

  receiver.recorder().clearDirectedInteractions();
  immediate.recorder().clearDirectedInteractions();
  std::vector<std::uint8_t> const firstTag{0x41U, 0x11U};
  send(firstTag);
  waitFor(
      receiver,
      [&] { return receiver.recorder().directedInteractions().size() == 1U; },
      options,
      "directed target lifecycle ordinary delivery");
  require(
      immediate.recorder().directedInteractions().size() == 1U,
      "directed target lifecycle immediate delivery");
  assertDirected(
      receiver.recorder().directedInteractions().front(),
      receiverInteraction,
      firstTag,
      receiver.rtiAmbassador());
  assertDirected(
      immediate.recorder().directedInteractions().front(),
      immediateInteraction,
      firstTag,
      immediate.rtiAmbassador());

  auto expectedReceiverDeliveries = std::size_t{1U};
  if (model == rti::HLA_EVOKED) {
    std::vector<std::uint8_t> const unsubscribedTag{0x42U, 0x22U};
    send(unsubscribedTag);
    receiver.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
        receiverClass,
        receiverDirected);
    for (int pass = 0; pass != 8; ++pass) {
      receiver.pump();
    }
    require(
        receiver.recorder().directedInteractions().size() == expectedReceiverDeliveries,
        "directed target lifecycle delivered after subscription removal");
    receiver.rtiAmbassador().subscribeObjectClassDirectedInteractions(
        receiverClass,
        receiverDirected,
        true);

    std::vector<std::uint8_t> const resubscribedTag{0x43U, 0x33U};
    send(resubscribedTag);
    ++expectedReceiverDeliveries;
    waitFor(
        receiver,
        [&] {
          return receiver.recorder().directedInteractions().size() ==
              expectedReceiverDeliveries;
        },
        options,
        "directed target lifecycle delivery after resubscription");

    std::vector<std::uint8_t> const unpublishedTag{0x44U, 0x44U};
    send(unpublishedTag);
    publisher.rtiAmbassador().unpublishObjectClassDirectedInteractions(
        publisherClass,
        publisherDirected);
    for (int pass = 0; pass != 8; ++pass) {
      receiver.pump();
    }
    require(
        receiver.recorder().directedInteractions().size() == expectedReceiverDeliveries,
        "directed target lifecycle delivered after source unpublication");
    publisher.rtiAmbassador().publishObjectClassDirectedInteractions(
        publisherClass,
        publisherDirected);

    std::vector<std::uint8_t> const republishedTag{0x45U, 0x55U};
    send(republishedTag);
    ++expectedReceiverDeliveries;
    waitFor(
        receiver,
        [&] {
          return receiver.recorder().directedInteractions().size() ==
              expectedReceiverDeliveries;
        },
        options,
        "directed target lifecycle delivery after republication");
  }

  receiver.recorder().clearRemovals();
  std::vector<std::uint8_t> const deletionTagBytes{0x46U, 0x66U};
  auto const deliveriesBeforeDeletion = receiver.recorder().directedInteractions().size();
  send(deletionTagBytes);
  rti::VariableLengthData deletionTag(
      deletionTagBytes.data(),
      deletionTagBytes.size());
  publisher.rtiAmbassador().deleteObjectInstance(target, deletionTag);
  waitFor(
      receiver,
      [&] {
        return receiver.recorder().hasRemoval(
            target,
            deletionTagBytes,
            publisher.federateHandle());
      },
      options,
      "directed target lifecycle removal");
  auto const receiverDeliveriesAfterDeletion =
      receiver.recorder().directedInteractions().size();
  require(
      receiverDeliveriesAfterDeletion ==
          deliveriesBeforeDeletion + (model == rti::HLA_EVOKED ? 0U : 1U),
      "directed target lifecycle delivered stale work around target deletion");
  auto const removals = receiver.recorder().removals();
  require(
      removals.size() == 1U && removals.front().object == target &&
          removals.front().tag == deletionTagBytes &&
          removals.front().producer == publisher.federateHandle(),
      "directed target lifecycle returned the wrong removal metadata");
  requireException(
      [&] {
        publisher.rtiAmbassador().sendDirectedInteraction(
            publisherInteraction,
            target,
            rti::ParameterHandleValueMap{},
            rti::VariableLengthData{});
      },
      L"ObjectInstanceNotKnown",
      "directed target lifecycle send after deletion");

  receiver.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(receiverClass);
  immediate.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(immediateClass);
  publisher.rtiAmbassador().unpublishObjectClassDirectedInteractions(publisherClass);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  publisher.resign(rti::NO_ACTION);
  receiver.resign(rti::NO_ACTION);
  immediate.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  publisher.disconnect();
  receiver.disconnect();
  immediate.disconnect();
}

void scenarioDirectedInteractionSubscriptionKind(
    Options const& options,
    rti::CallbackModel model) {
  Session owner(options, model, "owner");
  Session sender(options, model, "sender");
  Session ownershipSubscriber(options, model, "ownership-subscriber");
  Session universalSubscriber(options, model, "universal-subscriber");
  auto const federation = federationName(
      options,
      "directed-interaction-subscription-kind");

  owner.connect();
  sender.connect();
  ownershipSubscriber.connect();
  universalSubscriber.connect();
  owner.rtiAmbassador().createFederationExecution(
      federation,
      options.fom.wstring(),
      options.logicalTimeImplementationName);
  owner.join(
      options.ownerFederateName + L"-directed-subscription-owner",
      options.federateType,
      federation);
  sender.join(
      options.memberFederateName + L"-directed-subscription-sender",
      options.federateType,
      federation);
  ownershipSubscriber.join(
      options.memberFederateName + L"-directed-subscription-by-owner",
      options.federateType,
      federation);
  universalSubscriber.join(
      options.memberFederateName + L"-directed-subscription-universal",
      options.federateType,
      federation);

  auto const ownerClass = owner.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const senderClass = sender.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const ownershipClass = ownershipSubscriber.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const universalClass = universalSubscriber.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const ownerAttribute = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.attributeName);
  auto const senderAttribute = sender.rtiAmbassador().getAttributeHandle(
      senderClass,
      options.attributeName);
  auto const ownershipAttribute = ownershipSubscriber.rtiAmbassador().getAttributeHandle(
      ownershipClass,
      options.attributeName);
  auto const universalAttribute = universalSubscriber.rtiAmbassador().getAttributeHandle(
      universalClass,
      options.attributeName);
  auto const senderInteraction = sender.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const ownerInteraction = owner.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const ownershipInteraction = ownershipSubscriber.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const universalInteraction = universalSubscriber.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const senderParameter = sender.rtiAmbassador().getParameterHandle(
      senderInteraction,
      options.parameterName);
  auto const ownerParameter = owner.rtiAmbassador().getParameterHandle(
      ownerInteraction,
      options.parameterName);
  auto const ownershipParameter = ownershipSubscriber.rtiAmbassador().getParameterHandle(
      ownershipInteraction,
      options.parameterName);
  auto const universalParameter = universalSubscriber.rtiAmbassador().getParameterHandle(
      universalInteraction,
      options.parameterName);
  require(
      ownerClass.isValid() && senderClass.isValid() && ownershipClass.isValid() &&
          universalClass.isValid() && ownerAttribute.isValid() &&
          senderAttribute.isValid() && ownershipAttribute.isValid() &&
          universalAttribute.isValid() && senderInteraction.isValid() &&
          ownerInteraction.isValid() && ownershipInteraction.isValid() &&
          universalInteraction.isValid() && senderParameter.isValid() &&
          ownerParameter.isValid() && ownershipParameter.isValid() &&
          universalParameter.isValid(),
      "directed interaction subscription-kind lookup returned an invalid handle");

  rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
  rti::AttributeHandleSet const senderAttributes{senderAttribute};
  rti::AttributeHandleSet const ownershipAttributes{ownershipAttribute};
  rti::AttributeHandleSet const universalAttributes{universalAttribute};
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  ownershipSubscriber.rtiAmbassador().publishObjectClassAttributes(
      ownershipClass,
      ownershipAttributes);
  sender.rtiAmbassador().subscribeObjectClassAttributes(
      senderClass,
      senderAttributes,
      true,
      L"");
  ownershipSubscriber.rtiAmbassador().subscribeObjectClassAttributes(
      ownershipClass,
      ownershipAttributes,
      true,
      L"");
  universalSubscriber.rtiAmbassador().subscribeObjectClassAttributes(
      universalClass,
      universalAttributes,
      true,
      L"");

  rti::InteractionClassHandleSet const senderDirected{senderInteraction};
  rti::InteractionClassHandleSet const ownerDirected{ownerInteraction};
  rti::InteractionClassHandleSet const ownershipDirected{ownershipInteraction};
  rti::InteractionClassHandleSet const universalDirected{universalInteraction};
  sender.rtiAmbassador().publishObjectClassDirectedInteractions(
      senderClass,
      senderDirected);
  owner.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      ownerClass,
      ownerDirected,
      false);
  ownershipSubscriber.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      ownershipClass,
      ownershipDirected,
      false);
  universalSubscriber.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      universalClass,
      universalDirected,
      true);

  auto const ownerTarget = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(
      ownerTarget.isValid(),
      "directed interaction subscription-kind owner registration returned an invalid handle");
  waitFor(
      sender,
      [&] { return sender.recorder().hasDiscovery(ownerTarget); },
      options,
      "directed interaction subscription-kind sender discovery of owner target");
  waitFor(
      ownershipSubscriber,
      [&] { return ownershipSubscriber.recorder().hasDiscovery(ownerTarget); },
      options,
      "directed interaction subscription-kind ownership subscriber discovery of owner target");
  waitFor(
      universalSubscriber,
      [&] { return universalSubscriber.recorder().hasDiscovery(ownerTarget); },
      options,
      "directed interaction subscription-kind universal discovery of owner target");

  std::vector<std::uint8_t> const parameterBytes{0x53U, 0x55U, 0x42U, 0x2DU, 0x4BU};
  std::vector<std::uint8_t> const ownerTagBytes{0x4FU, 0x57, 0x4EU};
  std::vector<std::uint8_t> const ownershipTagBytes{0x4FU, 0x57, 0x52};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      senderParameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));

  auto assertDirected = [&](Session& receiver,
                            DirectedInteractionRecord const& record,
                            rti::InteractionClassHandle const& expectedInteraction,
                            rti::ParameterHandle const& expectedParameter,
                            rti::ObjectInstanceHandle const& expectedTarget,
                            std::vector<std::uint8_t> const& expectedTag) {
    require(
        record.interaction == expectedInteraction && record.object == expectedTarget &&
            record.parameters.size() == 1U &&
            record.parameters.count(expectedParameter) == 1U &&
            copyBytes(record.parameters.at(expectedParameter)) == parameterBytes,
        "directed interaction subscription-kind returned the wrong target or parameter");
    require(
        record.tag == expectedTag,
        "directed interaction subscription-kind did not preserve the user tag");
    require(
        record.transportation.isValid() &&
            receiver.rtiAmbassador().getTransportationTypeName(record.transportation) ==
                L"HLAreliable",
        "directed interaction subscription-kind returned the wrong transportation");
    require(
        record.producer == sender.federateHandle(),
        "directed interaction subscription-kind returned the wrong producing federate");
  };

  owner.recorder().clearDirectedInteractions();
  ownershipSubscriber.recorder().clearDirectedInteractions();
  universalSubscriber.recorder().clearDirectedInteractions();
  rti::VariableLengthData ownerTag(ownerTagBytes.data(), ownerTagBytes.size());
  sender.rtiAmbassador().sendDirectedInteraction(
      senderInteraction,
      ownerTarget,
      parameters,
      ownerTag);
  waitFor(
      owner,
      [&] { return owner.recorder().directedInteractions().size() >= 1U; },
      options,
      "directed interaction subscription-kind ownership delivery");
  waitFor(
      universalSubscriber,
      [&] { return universalSubscriber.recorder().directedInteractions().size() >= 1U; },
      options,
      "directed interaction subscription-kind universal delivery");
  for (int pass = 0; pass != 8; ++pass) {
    ownershipSubscriber.pump();
  }
  require(
      ownershipSubscriber.recorder().directedInteractions().empty(),
      "directed interaction subscription-kind non-owner received an ownership delivery");
  auto const ownerDeliveries = owner.recorder().directedInteractions();
  auto const universalDeliveries = universalSubscriber.recorder().directedInteractions();
  require(ownerDeliveries.size() == 1U && universalDeliveries.size() == 1U,
          "directed interaction subscription-kind returned duplicate first deliveries");
  assertDirected(
      owner,
      ownerDeliveries.front(),
      ownerInteraction,
      ownerParameter,
      ownerTarget,
      ownerTagBytes);
  assertDirected(
      universalSubscriber,
      universalDeliveries.front(),
      universalInteraction,
      universalParameter,
      ownerTarget,
      ownerTagBytes);

  universalSubscriber.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      universalClass,
      rti::InteractionClassHandleSet{},
      false);
  sender.rtiAmbassador().sendDirectedInteraction(
      senderInteraction,
      ownerTarget,
      parameters,
      ownerTag);
  waitFor(
      owner,
      [&] { return owner.recorder().directedInteractions().size() >= 2U; },
      options,
      "directed interaction subscription-kind repeated ownership delivery");
  waitFor(
      universalSubscriber,
      [&] { return universalSubscriber.recorder().directedInteractions().size() >= 2U; },
      options,
      "directed interaction subscription-kind empty-set universal delivery");
  require(
      ownershipSubscriber.recorder().directedInteractions().empty(),
      "directed interaction subscription-kind non-owner received a repeated ownership delivery");

  auto const ownershipTarget = ownershipSubscriber.rtiAmbassador().registerObjectInstance(
      ownershipClass);
  require(
      ownershipTarget.isValid(),
      "directed interaction subscription-kind second registration returned an invalid handle");
  waitFor(
      sender,
      [&] { return sender.recorder().hasDiscovery(ownershipTarget); },
      options,
      "directed interaction subscription-kind sender discovery of ownership target");
  waitFor(
      universalSubscriber,
      [&] { return universalSubscriber.recorder().hasDiscovery(ownershipTarget); },
      options,
      "directed interaction subscription-kind universal discovery of ownership target");

  rti::VariableLengthData ownershipTag(
      ownershipTagBytes.data(),
      ownershipTagBytes.size());
  sender.rtiAmbassador().sendDirectedInteraction(
      senderInteraction,
      ownershipTarget,
      parameters,
      ownershipTag);
  waitFor(
      ownershipSubscriber,
      [&] { return ownershipSubscriber.recorder().directedInteractions().size() >= 1U; },
      options,
      "directed interaction subscription-kind second ownership delivery");
  waitFor(
      universalSubscriber,
      [&] { return universalSubscriber.recorder().directedInteractions().size() >= 3U; },
      options,
      "directed interaction subscription-kind second universal delivery");
  require(
      owner.recorder().directedInteractions().size() == 2U,
      "directed interaction subscription-kind non-owner received the second target");
  auto const ownershipDeliveries = ownershipSubscriber.recorder().directedInteractions();
  auto const universalAfterOwnership = universalSubscriber.recorder().directedInteractions();
  assertDirected(
      ownershipSubscriber,
      ownershipDeliveries.front(),
      ownershipInteraction,
      ownershipParameter,
      ownershipTarget,
      ownershipTagBytes);
  assertDirected(
      universalSubscriber,
      universalAfterOwnership.at(2),
      universalInteraction,
      universalParameter,
      ownershipTarget,
      ownershipTagBytes);

  universalSubscriber.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      universalClass,
      universalDirected,
      false);
  sender.rtiAmbassador().sendDirectedInteraction(
      senderInteraction,
      ownerTarget,
      parameters,
      ownerTag);
  waitFor(
      owner,
      [&] { return owner.recorder().directedInteractions().size() >= 3U; },
      options,
      "directed interaction subscription-kind switched owner delivery");
  for (int pass = 0; pass != 8; ++pass) {
    universalSubscriber.pump();
  }
  require(
      universalSubscriber.recorder().directedInteractions().size() == 3U,
      "directed interaction subscription-kind universal subscriber ignored ownership mode");
  require(
      ownershipSubscriber.recorder().directedInteractions().size() == 1U,
      "directed interaction subscription-kind ownership subscriber changed unexpectedly");

  ownershipSubscriber.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      ownershipClass,
      ownershipDirected,
      true);
  sender.rtiAmbassador().sendDirectedInteraction(
      senderInteraction,
      ownerTarget,
      parameters,
      ownerTag);
  waitFor(
      owner,
      [&] { return owner.recorder().directedInteractions().size() >= 4U; },
      options,
      "directed interaction subscription-kind switched universal delivery");
  waitFor(
      ownershipSubscriber,
      [&] { return ownershipSubscriber.recorder().directedInteractions().size() >= 2U; },
      options,
      "directed interaction subscription-kind ownership subscriber universal delivery");
  for (int pass = 0; pass != 8; ++pass) {
    universalSubscriber.pump();
  }
  require(
      universalSubscriber.recorder().directedInteractions().size() == 3U,
      "directed interaction subscription-kind switched universal subscriber received an extra delivery");
  auto const switchedOwnershipDeliveries = ownershipSubscriber.recorder().directedInteractions();
  assertDirected(
      ownershipSubscriber,
      switchedOwnershipDeliveries.at(1),
      ownershipInteraction,
      ownershipParameter,
      ownerTarget,
      ownerTagBytes);

  universalSubscriber.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(universalClass);
  ownershipSubscriber.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      ownershipClass);
  owner.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(ownerClass);
  sender.rtiAmbassador().unpublishObjectClassDirectedInteractions(senderClass);
  sender.rtiAmbassador().unsubscribeObjectClassAttributes(senderClass, senderAttributes);
  ownershipSubscriber.rtiAmbassador().unsubscribeObjectClassAttributes(
      ownershipClass,
      ownershipAttributes);
  universalSubscriber.rtiAmbassador().unsubscribeObjectClassAttributes(
      universalClass,
      universalAttributes);
  owner.rtiAmbassador().unpublishObjectClassAttributes(ownerClass, ownerAttributes);
  ownershipSubscriber.rtiAmbassador().unpublishObjectClassAttributes(
      ownershipClass,
      ownershipAttributes);
  universalSubscriber.resign(rti::NO_ACTION);
  ownershipSubscriber.resign(rti::DELETE_OBJECTS);
  sender.resign(rti::NO_ACTION);
  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  universalSubscriber.disconnect();
  ownershipSubscriber.disconnect();
  sender.disconnect();
  owner.disconnect();
}

void scenarioTimestampedDirectedInteractionImmediateSourceResignation(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.logicalTimeImplementationName.empty(),
      "Immediate timestamped directed-interaction source resignation requires an adapter-supplied logical-time implementation");

  Session owner(options, model, "owner");
  Session sender(options, model, "sender");
  Session receiver(options, model, "receiver");
  auto const federation = federationName(
      options,
      "timestamped-directed-interaction-immediate-source-resignation");
  connectAndJoin(owner, sender, options, federation, options.fom);
  receiver.connect();
  receiver.join(
      options.memberFederateName + L"-timestamped-directed-immediate-receiver",
      options.federateType,
      federation);

  auto const ownerClass = owner.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const senderClass = sender.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const receiverClass = receiver.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const ownerAttribute = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.attributeName);
  auto const senderAttribute = sender.rtiAmbassador().getAttributeHandle(
      senderClass,
      options.attributeName);
  auto const receiverAttribute = receiver.rtiAmbassador().getAttributeHandle(
      receiverClass,
      options.attributeName);
  auto const senderInteraction = sender.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const receiverInteraction = receiver.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const senderParameter = sender.rtiAmbassador().getParameterHandle(
      senderInteraction,
      options.parameterName);
  auto const receiverParameter = receiver.rtiAmbassador().getParameterHandle(
      receiverInteraction,
      options.parameterName);
  require(
      ownerClass.isValid() && senderClass.isValid() && receiverClass.isValid() &&
          ownerAttribute.isValid() && senderAttribute.isValid() &&
          receiverAttribute.isValid() && senderInteraction.isValid() &&
          receiverInteraction.isValid() && senderParameter.isValid() &&
          receiverParameter.isValid(),
      "Immediate timestamped directed-interaction source resignation lookup returned an invalid handle");

  rti::AttributeHandleSet ownerAttributes;
  ownerAttributes.insert(ownerAttribute);
  rti::AttributeHandleSet senderAttributes;
  senderAttributes.insert(senderAttribute);
  rti::AttributeHandleSet receiverAttributes;
  receiverAttributes.insert(receiverAttribute);
  rti::InteractionClassHandleSet senderDirectedInteractions;
  senderDirectedInteractions.insert(senderInteraction);
  rti::InteractionClassHandleSet receiverDirectedInteractions;
  receiverDirectedInteractions.insert(receiverInteraction);

  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  sender.rtiAmbassador().subscribeObjectClassAttributes(
      senderClass,
      senderAttributes,
      true,
      L"");
  receiver.rtiAmbassador().subscribeObjectClassAttributes(
      receiverClass,
      receiverAttributes,
      true,
      L"");
  sender.rtiAmbassador().publishObjectClassDirectedInteractions(
      senderClass,
      senderDirectedInteractions);
  sender.rtiAmbassador().changeInteractionOrderType(
      senderInteraction,
      rti::TIMESTAMP);
  receiver.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      receiverClass,
      receiverDirectedInteractions,
      true);

  auto const target = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(
      target.isValid(),
      "Immediate timestamped directed-interaction source resignation registration returned an invalid handle");
  waitFor(
      sender,
      receiver,
      [&] {
        return sender.recorder().hasDiscovery(target) &&
            receiver.recorder().hasDiscovery(target);
      },
      options,
      "Immediate timestamped directed-interaction source resignation target discovery");

  auto senderTime = makeTimeContext(sender);
  auto const senderFederate = sender.federateHandle();
  require(
      senderTime.factory != nullptr && senderTime.initial != nullptr &&
          senderTime.epsilon != nullptr,
      "Immediate timestamped directed-interaction source resignation could not initialize logical time");
  sender.rtiAmbassador().enableTimeRegulation(*senderTime.epsilon);
  waitFor(
      sender,
      [&] { return sender.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "Immediate timestamped directed-interaction source resignation time-regulation callback");

  auto const messageTime = timeAfter(
      *senderTime.factory,
      *senderTime.initial,
      *senderTime.epsilon,
      6U);
  std::vector<std::uint8_t> parameterBytes{
      0x49U, 0x4DU, 0x4DU, 0x2DU, 0x52U};
  std::vector<std::uint8_t> tagBytes{
      0x49U, 0x4DU, 0x4DU, 0x2DU, 0x52U, 0x45U, 0x53U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      senderParameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
  auto const retraction = sender.rtiAmbassador().sendDirectedInteraction(
      senderInteraction,
      target,
      parameters,
      tag,
      *messageTime);
  require(
      retraction.isValid(),
      "Immediate timestamped directed-interaction source resignation send returned an invalid retraction handle");
  auto const retractionBytes = copyBytes(retraction.encode());

  sender.resign(rti::NO_ACTION);
  waitFor(
      receiver,
      [&] { return receiver.recorder().timedDirectedInteractions().size() >= 1U; },
      options,
      "Immediate timestamped directed-interaction source resignation delivery");

  auto const directedInteractions = receiver.recorder().timedDirectedInteractions();
  require(
      directedInteractions.size() == 1U,
      "Immediate timestamped directed-interaction source resignation returned duplicate callbacks");
  auto const callbackOrder = receiver.recorder().callbackOrder();
  require(
      std::count(callbackOrder.begin(), callbackOrder.end(), "directed") == 1,
      "Immediate timestamped directed-interaction source resignation did not deliver exactly one directed callback");
  auto const& interaction = directedInteractions.front();
  require(
      interaction.interaction == receiverInteraction && interaction.object == target &&
          interaction.parameters.size() == 1U &&
          interaction.parameters.count(receiverParameter) == 1U &&
          copyBytes(interaction.parameters.at(receiverParameter)) == parameterBytes,
      "Immediate timestamped directed-interaction source resignation returned the wrong interaction or parameter");
  require(
      interaction.tag == tagBytes,
      "Immediate timestamped directed-interaction source resignation returned the wrong user tag");
  require(
      interaction.producer == senderFederate,
      "Immediate timestamped directed-interaction source resignation returned the wrong producing federate");
  require(
      interaction.transportation.isValid() &&
          !receiver.rtiAmbassador().getTransportationTypeName(
              interaction.transportation).empty(),
      "Immediate timestamped directed-interaction source resignation returned an unresolvable transport");
  require(
      interaction.time == encodeTime(*messageTime) && !interaction.timeText.empty(),
      "Immediate timestamped directed-interaction source resignation returned the wrong logical time");
  require(
      interaction.sentOrder == rti::TIMESTAMP &&
          interaction.receivedOrder == rti::RECEIVE,
      "Immediate timestamped directed-interaction source resignation returned the wrong order metadata");
  require(
      interaction.retractionPresent && interaction.retraction == retractionBytes,
      "Immediate timestamped directed-interaction source resignation omitted its retraction handle");
  require(
      receiver.recorder().retractions().empty(),
      "Immediate timestamped directed-interaction source resignation produced an unexpected retraction callback");

  receiver.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      receiverClass,
      receiverDirectedInteractions);
  receiver.rtiAmbassador().unsubscribeObjectClassAttributes(
      receiverClass,
      receiverAttributes);
  owner.rtiAmbassador().unpublishObjectClassAttributes(
      ownerClass,
      ownerAttributes);
  receiver.resign(rti::NO_ACTION);
  owner.resign(rti::DELETE_OBJECTS);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  sender.disconnect();
  owner.disconnect();
}

void scenarioQueryLitsAfterSourceResignationContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioQueryLitsAfterSourceResignation(options, model);
}

void scenarioTimestampedDirectedInteractions(Options const& options, rti::CallbackModel model) {
  Session publisher(options, model, "owner");
  Session targeted(options, model, "member");
  Session universal(options, model, "member");
  Session nonOwner(options, model, "member");
  auto const federation = federationName(options, "timestamped-directed-interactions");
  publisher.connect();
  targeted.connect();
  universal.connect();
  nonOwner.connect();
  publisher.rtiAmbassador().createFederationExecution(
      federation,
      options.fom.wstring(),
      options.logicalTimeImplementationName);
  publisher.join(
      options.ownerFederateName + L"-timestamped-directed-publisher",
      options.federateType,
      federation);
  targeted.join(
      options.memberFederateName + L"-timestamped-directed-target",
      options.federateType,
      federation);
  universal.join(
      options.memberFederateName + L"-timestamped-directed-universal",
      options.federateType,
      federation);
  nonOwner.join(
      options.memberFederateName + L"-timestamped-directed-non-owner",
      options.federateType,
      federation);

  auto const publisherClass = publisher.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const targetedClass = targeted.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const universalClass = universal.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const nonOwnerClass = nonOwner.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  require(
      publisherClass.isValid() && targetedClass.isValid() && universalClass.isValid() &&
          nonOwnerClass.isValid(),
      "timestamped directed object-class lookup returned an invalid handle");
  auto const publisherAttribute = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass, options.attributeName);
  auto const targetedAttribute = targeted.rtiAmbassador().getAttributeHandle(
      targetedClass, options.attributeName);
  auto const universalAttribute = universal.rtiAmbassador().getAttributeHandle(
      universalClass, options.attributeName);
  auto const nonOwnerAttribute = nonOwner.rtiAmbassador().getAttributeHandle(
      nonOwnerClass, options.attributeName);
  require(
      publisherAttribute.isValid() && targetedAttribute.isValid() &&
          universalAttribute.isValid() && nonOwnerAttribute.isValid(),
      "timestamped directed attribute lookup returned an invalid handle");
  rti::AttributeHandleSet publisherAttributes;
  publisherAttributes.insert(publisherAttribute);
  rti::AttributeHandleSet targetedAttributes;
  targetedAttributes.insert(targetedAttribute);
  rti::AttributeHandleSet universalAttributes;
  universalAttributes.insert(universalAttribute);
  rti::AttributeHandleSet nonOwnerAttributes;
  nonOwnerAttributes.insert(nonOwnerAttribute);

  auto const publisherInteraction = publisher.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const targetedInteraction = targeted.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const universalInteraction = universal.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const nonOwnerInteraction = nonOwner.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  require(
      publisherInteraction.isValid() && targetedInteraction.isValid() &&
          universalInteraction.isValid() && nonOwnerInteraction.isValid(),
      "timestamped directed interaction lookup returned an invalid class handle");
  auto const publisherParameter = publisher.rtiAmbassador().getParameterHandle(
      publisherInteraction, options.parameterName);
  auto const targetedParameter = targeted.rtiAmbassador().getParameterHandle(
      targetedInteraction, options.parameterName);
  auto const universalParameter = universal.rtiAmbassador().getParameterHandle(
      universalInteraction, options.parameterName);
  require(
      publisherParameter.isValid() && targetedParameter.isValid() &&
          universalParameter.isValid(),
      "timestamped directed parameter lookup returned an invalid handle");
  rti::InteractionClassHandleSet directedInteractions;
  directedInteractions.insert(publisherInteraction);

  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherClass, publisherAttributes);
  targeted.rtiAmbassador().publishObjectClassAttributes(
      targetedClass, targetedAttributes);
  publisher.rtiAmbassador().subscribeObjectClassAttributes(
      publisherClass, publisherAttributes, true, L"");
  targeted.rtiAmbassador().subscribeObjectClassAttributes(
      targetedClass, targetedAttributes, true, L"");
  universal.rtiAmbassador().subscribeObjectClassAttributes(
      universalClass, universalAttributes, true, L"");
  // This federate knows the target through an ordinary object subscription,
  // but registers no object and is not a universal directed subscriber.
  nonOwner.rtiAmbassador().subscribeObjectClassAttributes(
      nonOwnerClass, nonOwnerAttributes, true, L"");
  publisher.rtiAmbassador().publishObjectClassDirectedInteractions(
      publisherClass, directedInteractions);
  rti::InteractionClassHandleSet targetedDirectedInteractions;
  targetedDirectedInteractions.insert(targetedInteraction);
  targeted.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      targetedClass, targetedDirectedInteractions, false);
  rti::InteractionClassHandleSet universalDirectedInteractions;
  universalDirectedInteractions.insert(universalInteraction);
  universal.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      universalClass, universalDirectedInteractions, true);
  rti::InteractionClassHandleSet nonOwnerDirectedInteractions;
  nonOwnerDirectedInteractions.insert(nonOwnerInteraction);
  nonOwner.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      nonOwnerClass, nonOwnerDirectedInteractions, false);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherInteraction, rti::TIMESTAMP);

  auto const target = targeted.rtiAmbassador().registerObjectInstance(targetedClass);
  require(target.isValid(), "timestamped directed registration returned an invalid handle");
  waitFor(
      publisher,
      [&] { return publisher.recorder().hasDiscovery(target); },
      options,
      "publisher discovery of the timestamped directed target");
  waitFor(
      universal,
      [&] { return universal.recorder().hasDiscovery(target); },
      options,
      "universal discovery of the timestamped directed target");
  waitFor(
      nonOwner,
      [&] { return nonOwner.recorder().hasDiscovery(target); },
      options,
      "non-owner discovery of the timestamped directed target");

  auto publisherTime = makeTimeContext(publisher);
  auto targetedTime = makeTimeContext(targeted);
  auto universalTime = makeTimeContext(universal);
  require(
      publisherTime.factory->getName() == targetedTime.factory->getName() &&
          publisherTime.factory->getName() == universalTime.factory->getName(),
      "timestamped directed members selected different logical-time factories");
  universal.rtiAmbassador().enableTimeConstrained();
  publisher.rtiAmbassador().enableTimeRegulation(*publisherTime.epsilon);

  auto waitForAll = [&](auto predicate, std::string const& description) {
    auto const deadline = Clock::now() +
        std::chrono::milliseconds(options.timeoutMilliseconds);
    while (Clock::now() < deadline) {
      publisher.pump();
      targeted.pump();
      universal.pump();
      nonOwner.pump();
      if (predicate()) {
        return;
      }
      std::this_thread::sleep_for(std::chrono::milliseconds(1));
    }
    throw std::runtime_error("Timed out waiting for " + description);
  };
  waitForAll(
      [&] {
        return publisher.recorder().timeRegulationEnabled().size() >= 1U &&
            universal.recorder().timeConstrainedEnabled().size() >= 1U;
      },
      "timestamped directed time-role callbacks");
  require(
      publisher.recorder().timeRegulationEnabled().size() == 1U &&
          universal.recorder().timeConstrainedEnabled().size() == 1U,
      "timestamped directed time-role callback was delivered more than once");
  rti::MessageRetractionHandle const invalidRetraction;
  requireException(
      [&] { publisher.rtiAmbassador().retract(invalidRetraction); },
      L"InvalidMessageRetractionHandle",
      "timestamped directed retract with an invalid handle");
  rti::InteractionClassHandle const invalidDirectedInteraction;
  auto const invalidDirectedTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      3U);
  requireException(
      [&] {
        publisher.rtiAmbassador().sendDirectedInteraction(
            invalidDirectedInteraction,
            target,
            rti::ParameterHandleValueMap{},
            rti::VariableLengthData{},
            *invalidDirectedTime);
      },
      L"InteractionClassNotDefined",
      "timestamped directed send with an invalid interaction class");
  requireException(
      [&] {
        publisher.rtiAmbassador().sendDirectedInteraction(
            publisherInteraction,
            rti::ObjectInstanceHandle{},
            rti::ParameterHandleValueMap{},
            rti::VariableLengthData{},
            *invalidDirectedTime);
      },
      L"ObjectInstanceNotKnown",
      "timestamped directed send with an unknown target object");

  auto assertDirected = [&](TimedDirectedInteractionRecord const& record,
                            rti::InteractionClassHandle const& expectedInteraction,
                            rti::ParameterHandle const& expectedParameter,
                            std::vector<std::uint8_t> const& expectedValue,
                            rti::ObjectInstanceHandle const& expectedTarget,
                            std::vector<std::uint8_t> const& expectedTag,
                            std::vector<std::uint8_t> const& expectedTime,
                            rti::FederateHandle const& expectedProducer,
                            rti::OrderType expectedReceivedOrder,
                            Session& inspector) {
    require(record.interaction == expectedInteraction,
            "timestamped directed callback carried the wrong interaction class");
    require(record.object == expectedTarget,
            "timestamped directed callback carried the wrong target object");
    require(record.parameters.size() == 1U &&
                record.parameters.count(expectedParameter) == 1U,
            "timestamped directed callback returned the wrong parameter set");
    require(copyBytes(record.parameters.at(expectedParameter)) == expectedValue,
            "timestamped directed callback returned the wrong parameter value");
    require(record.tag == expectedTag,
            "timestamped directed callback did not preserve the user tag");
    require(record.producer == expectedProducer,
            "timestamped directed callback returned the wrong producing federate");
    require(record.transportation.isValid() && !inspector.rtiAmbassador()
                .getTransportationTypeName(record.transportation).empty(),
            "timestamped directed callback returned an unresolvable transportation type");
    require(record.time == expectedTime,
            "timestamped directed callback returned the wrong logical time");
    require(!record.timeText.empty(),
            "timestamped directed callback returned no logical-time representation");
    require(record.sentOrder == rti::TIMESTAMP,
            "timestamped directed callback returned a non-timestamp sent order");
    require(record.receivedOrder == expectedReceivedOrder,
            "timestamped directed callback returned the wrong received order");
  };

  auto firstTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      3U);
  auto firstTargetedTime = timeAfter(
      *targetedTime.factory,
      *targetedTime.initial,
      *targetedTime.epsilon,
      3U);
  auto firstUniversalTime = timeAfter(
      *universalTime.factory,
      *universalTime.initial,
      *universalTime.epsilon,
      3U);
  std::vector<std::uint8_t> firstValueBytes{0x41U, 0x42U, 0x43U};
  std::vector<std::uint8_t> firstTagBytes{0x51U, 0x52U};
  rti::ParameterHandleValueMap firstParameters;
  firstParameters.emplace(
      publisherParameter,
      rti::VariableLengthData(firstValueBytes.data(), firstValueBytes.size()));
  rti::VariableLengthData firstTag(firstTagBytes.data(), firstTagBytes.size());
  auto firstRetraction = publisher.rtiAmbassador().sendDirectedInteraction(
      publisherInteraction,
      target,
      firstParameters,
      firstTag,
      *firstTime);
  require(firstRetraction.isValid(),
          "timestamped directed send returned an invalid retraction handle");
  waitForAll(
      [&] { return targeted.recorder().timedDirectedInteractions().size() >= 1U; },
      "non-constrained timestamped directed delivery");
  auto const firstTargetedReceived = targeted.recorder().timedDirectedInteractions();
  require(firstTargetedReceived.size() == 1U,
          "non-constrained directed recipient received duplicate timestamped delivery");
  assertDirected(
      firstTargetedReceived.front(),
      targetedInteraction,
      targetedParameter,
      firstValueBytes,
      target,
      firstTagBytes,
      encodeTime(*firstTime),
      publisher.federateHandle(),
      rti::RECEIVE,
      targeted);
  require(firstTargetedReceived.front().retractionPresent &&
              firstTargetedReceived.front().retraction ==
                  copyBytes(firstRetraction.encode()),
          "non-constrained directed callback returned the wrong retraction handle");
  require(nonOwner.recorder().timedDirectedInteractions().empty(),
          "timestamped directed interaction reached a non-owner without a universal subscription");
  require(universal.recorder().timedDirectedInteractions().empty(),
          "time-constrained directed recipient received a timestamped interaction before its grant");
  publisher.rtiAmbassador().retract(firstRetraction);
  waitForAll(
      [&] { return targeted.recorder().retractions().size() >= 1U; },
      "non-constrained timestamped directed retraction callback");
  auto const firstTargetedRetractions = targeted.recorder().retractions();
  require(firstTargetedRetractions.size() == 1U && firstTargetedRetractions.front().valid &&
              firstTargetedRetractions.front().encoded == copyBytes(firstRetraction.encode()),
          "non-constrained directed retraction callback returned the wrong message handle");
  require(universal.recorder().retractions().empty(),
          "pending timestamped directed interaction produced a retraction callback");

  targeted.rtiAmbassador().enableTimeConstrained();
  waitForAll(
      [&] { return targeted.recorder().timeConstrainedEnabled().size() >= 1U; },
      "timestamped directed target time-constrained callback");
  require(targeted.recorder().timeConstrainedEnabled().size() == 1U,
          "timestamped directed target time-constrained callback was delivered more than once");

  targeted.rtiAmbassador().timeAdvanceRequest(*firstTargetedTime);
  universal.rtiAmbassador().timeAdvanceRequest(*firstUniversalTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*firstTime);
  waitForAll(
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 1U &&
            targeted.recorder().timeAdvanceGrants().size() >= 1U &&
            universal.recorder().timeAdvanceGrants().size() >= 1U;
      },
      "first timestamped directed time advance grants");
  require(targeted.recorder().timedDirectedInteractions().size() == 1U &&
              universal.recorder().timedDirectedInteractions().empty(),
          "retracted timestamped directed interaction was delivered at its grant");
  require(targeted.recorder().retractions().size() == 1U &&
              universal.recorder().retractions().empty(),
          "retracted pending timestamped directed interaction produced a stale callback");

  auto secondTime = timeAfter(
      *publisherTime.factory,
      *firstTime,
      *publisherTime.epsilon,
      3U);
  auto secondTargetedTime = timeAfter(
      *targetedTime.factory,
      *firstTargetedTime,
      *targetedTime.epsilon,
      3U);
  auto secondUniversalTime = timeAfter(
      *universalTime.factory,
      *firstUniversalTime,
      *universalTime.epsilon,
      3U);
  std::vector<std::uint8_t> secondValueBytes{0x61U, 0x62U, 0x63U};
  std::vector<std::uint8_t> secondTagBytes{0x71U, 0x72U};
  rti::ParameterHandleValueMap secondParameters;
  secondParameters.emplace(
      publisherParameter,
      rti::VariableLengthData(secondValueBytes.data(), secondValueBytes.size()));
  rti::VariableLengthData secondTag(secondTagBytes.data(), secondTagBytes.size());
  auto secondRetraction = publisher.rtiAmbassador().sendDirectedInteraction(
      publisherInteraction,
      target,
      secondParameters,
      secondTag,
      *secondTime);
  require(secondRetraction.isValid(),
          "second timestamped directed send returned an invalid retraction handle");
  targeted.rtiAmbassador().timeAdvanceRequest(*secondTargetedTime);
  universal.rtiAmbassador().timeAdvanceRequest(*secondUniversalTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*secondTime);
  waitForAll(
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 2U &&
            targeted.recorder().timeAdvanceGrants().size() >= 2U &&
            universal.recorder().timeAdvanceGrants().size() >= 2U &&
            targeted.recorder().timedDirectedInteractions().size() >= 1U &&
            universal.recorder().timedDirectedInteractions().size() >= 1U;
      },
      "second timestamped directed delivery and time advance grants");
  auto const targetedReceived = targeted.recorder().timedDirectedInteractions();
  auto const universalReceived = universal.recorder().timedDirectedInteractions();
  require(targetedReceived.size() == 2U && universalReceived.size() == 1U,
          "timestamped directed subscribers received the wrong delivery count");
  require(nonOwner.recorder().timedDirectedInteractions().empty(),
          "timestamped directed interaction reached a non-owner without a universal subscription");
  assertDirected(
      targetedReceived.at(1),
      targetedInteraction,
      targetedParameter,
      secondValueBytes,
      target,
      secondTagBytes,
      encodeTime(*secondTime),
      publisher.federateHandle(),
      rti::TIMESTAMP,
      targeted);
  assertDirected(
      universalReceived.front(),
      universalInteraction,
      universalParameter,
      secondValueBytes,
      target,
      secondTagBytes,
      encodeTime(*secondTime),
      publisher.federateHandle(),
      rti::TIMESTAMP,
      universal);
  require(targetedReceived.at(1).retractionPresent &&
              universalReceived.front().retractionPresent,
          "timestamped directed callback omitted a retraction handle");
  require(targetedReceived.at(1).retraction == copyBytes(secondRetraction.encode()) &&
              universalReceived.front().retraction == copyBytes(secondRetraction.encode()),
          "timestamped directed callback returned the wrong retraction handle");

  auto const targetedRetractions = targeted.recorder().retractions();
  auto const universalRetractions = universal.recorder().retractions();
  require(targetedRetractions.size() == 1U,
          "second timestamped directed interaction changed target retraction state unexpectedly");
  require(universalRetractions.empty(),
          "second timestamped directed interaction changed universal retraction state unexpectedly");
  requireException(
      [&] { publisher.rtiAmbassador().retract(secondRetraction); },
      L"MessageCanNoLongerBeRetracted",
      "retracting a delivered timestamped directed interaction at the producer boundary");

  targeted.rtiAmbassador().disableTimeConstrained();
  universal.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  targeted.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      targetedClass, targetedDirectedInteractions);
  universal.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      universalClass, universalDirectedInteractions);
  nonOwner.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      nonOwnerClass, nonOwnerDirectedInteractions);
  publisher.rtiAmbassador().unpublishObjectClassDirectedInteractions(
      publisherClass, directedInteractions);
  publisher.rtiAmbassador().unsubscribeObjectClass(publisherClass);
  targeted.rtiAmbassador().unsubscribeObjectClass(targetedClass);
  universal.rtiAmbassador().unsubscribeObjectClass(universalClass);
  nonOwner.rtiAmbassador().unsubscribeObjectClass(nonOwnerClass);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherClass, publisherAttributes);
  targeted.rtiAmbassador().unpublishObjectClassAttributes(
      targetedClass, targetedAttributes);
  universal.resign(rti::NO_ACTION);
  nonOwner.resign(rti::NO_ACTION);
  targeted.resign(rti::DELETE_OBJECTS);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  universal.disconnect();
  nonOwner.disconnect();
  targeted.disconnect();
  publisher.disconnect();
}

