void scenarioTransportOrder(Options const& options, rti::CallbackModel model) {
  Session owner(options, model, "owner");
  Session observer(options, model, "member");
  auto const federation = federationName(options, "transport-order");
  connectAndJoin(owner, observer, options, federation, options.fom);

  rti::ObjectClassHandle ownerClass;
  rti::AttributeHandle ownerAttribute;
  rti::InteractionClassHandle ownerInteraction;
  rti::ParameterHandle ownerParameter;
  handles(owner, options, ownerClass, ownerAttribute, ownerInteraction, ownerParameter);
  auto const observerClass = observer.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const observerAttribute = observer.rtiAmbassador().getAttributeHandle(
      observerClass, options.attributeName);
  auto const observerInteraction = observer.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  require(observerClass.isValid() && observerAttribute.isValid() &&
              observerInteraction.isValid(),
          "Transport/order observer lookup returned an invalid handle");
  auto const reliable = owner.rtiAmbassador().getTransportationTypeHandle(L"HLAreliable");
  auto const bestEffort = owner.rtiAmbassador().getTransportationTypeHandle(L"HLAbestEffort");
  require(reliable.isValid() && bestEffort.isValid(),
          "Transport/order lookup did not return the standard transportation handles");

  rti::AttributeHandleSet ownerAttributes;
  ownerAttributes.insert(ownerAttribute);
  rti::AttributeHandleSet observerAttributes;
  observerAttributes.insert(observerAttribute);
  rti::ObjectClassHandle const invalidObjectClass;
  rti::ObjectInstanceHandle const invalidObject;
  rti::InteractionClassHandle const invalidInteraction;
  rti::AttributeHandleSet const invalidAttributes{rti::AttributeHandle{}};
  rti::TransportationTypeHandle const invalidTransportation;
  requireException(
      [&] {
        owner.rtiAmbassador().changeDefaultAttributeOrderType(
            invalidObjectClass,
            ownerAttributes,
            rti::RECEIVE);
      },
      L"ObjectClassNotDefined",
      "default attribute order change with an invalid object class");
  requireException(
      [&] {
        owner.rtiAmbassador().changeDefaultAttributeOrderType(
            ownerClass,
            invalidAttributes,
            rti::RECEIVE);
      },
      L"AttributeNotDefined",
      "default attribute order change with an invalid attribute");
  requireException(
      [&] {
        owner.rtiAmbassador().changeDefaultAttributeTransportationType(
            invalidObjectClass,
            ownerAttributes,
            bestEffort);
      },
      L"ObjectClassNotDefined",
      "default attribute transportation change with an invalid object class");
  requireException(
      [&] {
        owner.rtiAmbassador().changeDefaultAttributeTransportationType(
            ownerClass,
            invalidAttributes,
            bestEffort);
      },
      L"AttributeNotDefined",
      "default attribute transportation change with an invalid attribute");
  requireException(
      [&] {
        owner.rtiAmbassador().changeDefaultAttributeTransportationType(
            ownerClass,
            ownerAttributes,
            invalidTransportation);
      },
      L"InvalidTransportationTypeHandle",
      "default attribute transportation change with an invalid transportation handle");
  requireException(
      [&] {
        owner.rtiAmbassador().requestAttributeTransportationTypeChange(
            invalidObject,
            ownerAttributes,
            bestEffort);
      },
      L"ObjectInstanceNotKnown",
      "attribute transportation change for an unknown object");
  requireException(
      [&] {
        owner.rtiAmbassador().queryAttributeTransportationType(
            invalidObject,
            ownerAttribute);
      },
      L"ObjectInstanceNotKnown",
      "attribute transportation query for an unknown object");
  requireException(
      [&] { owner.rtiAmbassador().changeInteractionOrderType(invalidInteraction, rti::RECEIVE); },
      L"InteractionClassNotDefined",
      "interaction order change with an invalid interaction class");
  requireException(
      [&] {
        owner.rtiAmbassador().requestInteractionTransportationTypeChange(
            invalidInteraction,
            bestEffort);
      },
      L"InteractionClassNotDefined",
      "interaction transportation change with an invalid interaction class");
  requireException(
      [&] {
        owner.rtiAmbassador().queryInteractionTransportationType(
            owner.federateHandle(),
            invalidInteraction);
      },
      L"InteractionClassNotDefined",
      "interaction transportation query with an invalid interaction class");
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  observer.rtiAmbassador().subscribeObjectClassAttributes(
      observerClass, observerAttributes, true, L"");
  requireException(
      [&] {
        owner.rtiAmbassador().changeInteractionOrderType(
            ownerInteraction, rti::RECEIVE);
      },
      L"InteractionClassNotPublished",
      "unpublished interaction order change");
  owner.rtiAmbassador().publishInteractionClass(ownerInteraction);
  observer.rtiAmbassador().subscribeInteractionClass(observerInteraction, true);
  requireException(
      [&] {
        owner.rtiAmbassador().requestInteractionTransportationTypeChange(
            ownerInteraction,
            invalidTransportation);
      },
      L"InvalidTransportationTypeHandle",
      "published interaction transportation change with an invalid transportation handle");

  owner.rtiAmbassador().changeDefaultAttributeOrderType(
      ownerClass, ownerAttributes, rti::RECEIVE);
  auto const first = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(first.isValid(), "Transport/order first registration returned an invalid handle");
  requireException(
      [&] {
        owner.rtiAmbassador().changeAttributeOrderType(
            invalidObject,
            ownerAttributes,
            rti::RECEIVE);
      },
      L"ObjectInstanceNotKnown",
      "per-instance attribute order change with an unknown object");
  requireException(
      [&] {
        owner.rtiAmbassador().changeAttributeOrderType(
            first,
            invalidAttributes,
            rti::TIMESTAMP);
      },
      L"AttributeNotDefined",
      "per-instance attribute order change with an invalid attribute");
  requireException(
      [&] {
        owner.rtiAmbassador().requestAttributeTransportationTypeChange(
            first,
            invalidAttributes,
            bestEffort);
      },
      L"AttributeNotDefined",
      "attribute transportation change with an invalid attribute");
  requireException(
      [&] {
        owner.rtiAmbassador().requestAttributeTransportationTypeChange(
            first,
            ownerAttributes,
            invalidTransportation);
      },
      L"InvalidTransportationTypeHandle",
      "attribute transportation change with an invalid transportation handle");
  requireException(
      [&] {
        owner.rtiAmbassador().queryAttributeTransportationType(
            first,
            rti::AttributeHandle{});
      },
      L"AttributeNotDefined",
      "attribute transportation query with an invalid attribute");
  owner.rtiAmbassador().changeAttributeOrderType(
      first, ownerAttributes, rti::TIMESTAMP);
  owner.rtiAmbassador().changeAttributeOrderType(
      first, ownerAttributes, rti::RECEIVE);
  owner.rtiAmbassador().changeInteractionOrderType(ownerInteraction, rti::TIMESTAMP);
  owner.rtiAmbassador().changeInteractionOrderType(ownerInteraction, rti::RECEIVE);

  owner.rtiAmbassador().changeDefaultAttributeTransportationType(
      ownerClass, ownerAttributes, bestEffort);
  auto const second = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(second.isValid(), "Transport/order second registration returned an invalid handle");
  waitFor(observer,
          [&] {
            return observer.recorder().hasDiscovery(first) &&
                observer.recorder().hasDiscovery(second);
          },
          options,
          "transport/order object discovery");

  auto sameTransport = [](rti::RTIambassador& inspector,
                          rti::TransportationTypeHandle const& actual,
                          std::wstring const& expectedName) {
    return actual.isValid() &&
        inspector.getTransportationTypeName(actual) == expectedName;
  };

  owner.recorder().clearTransportationRecords();
  owner.rtiAmbassador().queryAttributeTransportationType(first, ownerAttribute);
  owner.rtiAmbassador().queryAttributeTransportationType(second, ownerAttribute);
  waitFor(owner,
          [&] { return owner.recorder().attributeTransportationReports().size() >= 2U; },
          options,
          "attribute transportation query reports");
  auto const attributeReports = owner.recorder().attributeTransportationReports();
  auto const firstReport = std::find_if(
      attributeReports.begin(), attributeReports.end(), [&](auto const& report) {
        return report.object == first && report.attribute == ownerAttribute;
      });
  auto const secondReport = std::find_if(
      attributeReports.begin(), attributeReports.end(), [&](auto const& report) {
        return report.object == second && report.attribute == ownerAttribute;
      });
  require(firstReport != attributeReports.end() && secondReport != attributeReports.end(),
          "Attribute transportation query reports omitted a registered object");
  require(sameTransport(owner.rtiAmbassador(), firstReport->transportation, L"HLAreliable"),
          "first object did not retain the reliable transportation default");
  require(sameTransport(owner.rtiAmbassador(), secondReport->transportation, L"HLAbestEffort"),
          "second object did not capture the best-effort class default");

  owner.recorder().clearTransportationRecords();
  observer.recorder().clearReflection();
  owner.rtiAmbassador().requestAttributeTransportationTypeChange(
      first, ownerAttributes, bestEffort);
  if (model == rti::HLA_EVOKED) {
    requireException(
        [&] {
          owner.rtiAmbassador().requestAttributeTransportationTypeChange(
              first, ownerAttributes, reliable);
        },
        L"AttributeAlreadyBeingChanged",
        "duplicate attribute transportation request");
  } else {
    waitFor(owner,
            [&] {
              return owner.recorder().attributeTransportationConfirmations().size() >= 1U;
            },
            options,
            "immediate attribute transportation confirmation");
  }
  std::vector<std::uint8_t> beforeValueBytes{0x01U};
  std::vector<std::uint8_t> beforeTagBytes{0x01U};
  rti::AttributeHandleValueMap beforeValues;
  beforeValues.emplace(
      ownerAttribute,
      rti::VariableLengthData(beforeValueBytes.data(), beforeValueBytes.size()));
  rti::VariableLengthData beforeTag(beforeTagBytes.data(), beforeTagBytes.size());
  owner.rtiAmbassador().updateAttributeValues(first, beforeValues, beforeTag);
  waitFor(observer,
          [&] { return observer.recorder().reflection().present; },
          options,
          "pre-confirmation attribute update");
  auto const beforeReflection = observer.recorder().reflection();
  require(beforeReflection.object == first &&
              sameTransport(observer.rtiAmbassador(), beforeReflection.transportation,
                            model == rti::HLA_EVOKED ? L"HLAreliable" : L"HLAbestEffort"),
          model == rti::HLA_EVOKED
              ? "pre-confirmation attribute update did not use reliable transport"
              : "immediate attribute transport change did not use best-effort transport");
  waitFor(owner,
          [&] {
            return owner.recorder().attributeTransportationConfirmations().size() >= 1U;
          },
          options,
          "attribute transportation confirmation");
  auto const attributeConfirmations = owner.recorder().attributeTransportationConfirmations();
  auto const& attributeConfirmation = attributeConfirmations.back();
  require(attributeConfirmation.object == first &&
              attributeConfirmation.attributes.count(ownerAttribute) == 1U &&
              sameTransport(owner.rtiAmbassador(), attributeConfirmation.transportation,
                            L"HLAbestEffort"),
          "attribute transportation confirmation did not commit best effort");

  observer.recorder().clearReflection();
  std::vector<std::uint8_t> afterValueBytes{0x02U};
  std::vector<std::uint8_t> afterTagBytes{0x02U};
  rti::AttributeHandleValueMap afterValues;
  afterValues.emplace(
      ownerAttribute,
      rti::VariableLengthData(afterValueBytes.data(), afterValueBytes.size()));
  rti::VariableLengthData afterTag(afterTagBytes.data(), afterTagBytes.size());
  owner.rtiAmbassador().updateAttributeValues(first, afterValues, afterTag);
  waitFor(observer,
          [&] { return observer.recorder().reflection().present; },
          options,
          "post-confirmation attribute update");
  auto const afterReflection = observer.recorder().reflection();
  require(afterReflection.object == first &&
              sameTransport(observer.rtiAmbassador(), afterReflection.transportation,
                            L"HLAbestEffort"),
          "post-confirmation attribute update did not use best-effort transport");
  owner.recorder().clearTransportationRecords();
  owner.rtiAmbassador().queryAttributeTransportationType(first, ownerAttribute);
  waitFor(owner,
          [&] { return owner.recorder().attributeTransportationReports().size() >= 1U; },
          options,
          "final attribute transportation query");
  require(sameTransport(
              owner.rtiAmbassador(),
              owner.recorder().attributeTransportationReports().back().transportation,
              L"HLAbestEffort"),
          "attribute transportation query did not observe the committed change");

  owner.recorder().clearTransportationRecords();
  observer.recorder().clearInteraction();
  owner.rtiAmbassador().requestInteractionTransportationTypeChange(
      ownerInteraction, bestEffort);
  if (model == rti::HLA_EVOKED) {
    requireException(
        [&] {
          owner.rtiAmbassador().requestInteractionTransportationTypeChange(
              ownerInteraction, reliable);
        },
        L"InteractionClassAlreadyBeingChanged",
        "duplicate interaction transportation request");
  } else {
    waitFor(owner,
            [&] {
              return owner.recorder().interactionTransportationConfirmations().size() >= 1U;
            },
            options,
            "immediate interaction transportation confirmation");
  }
  std::vector<std::uint8_t> interactionBeforeTagBytes{0x03U};
  rti::VariableLengthData interactionBeforeTag(
      interactionBeforeTagBytes.data(), interactionBeforeTagBytes.size());
  owner.rtiAmbassador().sendInteraction(
      ownerInteraction, rti::ParameterHandleValueMap{}, interactionBeforeTag);
  waitFor(observer,
          [&] { return observer.recorder().interaction().present; },
          options,
          "pre-confirmation interaction delivery");
  auto const interactionBefore = observer.recorder().interaction();
  require(sameTransport(observer.rtiAmbassador(), interactionBefore.transportation,
                        model == rti::HLA_EVOKED ? L"HLAreliable" : L"HLAbestEffort"),
          model == rti::HLA_EVOKED
              ? "pre-confirmation interaction did not use reliable transport"
              : "immediate interaction transport change did not use best-effort transport");
  waitFor(owner,
          [&] {
            return owner.recorder().interactionTransportationConfirmations().size() >= 1U;
          },
          options,
          "interaction transportation confirmation");
  auto const interactionConfirmations =
      owner.recorder().interactionTransportationConfirmations();
  auto const& interactionConfirmation = interactionConfirmations.back();
  require(interactionConfirmation.interaction == ownerInteraction &&
              sameTransport(owner.rtiAmbassador(), interactionConfirmation.transportation,
                            L"HLAbestEffort"),
          "interaction transportation confirmation did not commit best effort");

  observer.recorder().clearInteraction();
  std::vector<std::uint8_t> interactionAfterTagBytes{0x04U};
  rti::VariableLengthData interactionAfterTag(
      interactionAfterTagBytes.data(), interactionAfterTagBytes.size());
  owner.rtiAmbassador().sendInteraction(
      ownerInteraction, rti::ParameterHandleValueMap{}, interactionAfterTag);
  waitFor(observer,
          [&] { return observer.recorder().interaction().present; },
          options,
          "post-confirmation interaction delivery");
  auto const interactionAfter = observer.recorder().interaction();
  require(sameTransport(observer.rtiAmbassador(), interactionAfter.transportation,
                        L"HLAbestEffort"),
          "post-confirmation interaction did not use best-effort transport");
  owner.recorder().clearTransportationRecords();
  owner.rtiAmbassador().queryInteractionTransportationType(
      owner.federateHandle(), ownerInteraction);
  waitFor(owner,
          [&] { return owner.recorder().interactionTransportationReports().size() >= 1U; },
          options,
          "interaction transportation query");
  auto const interactionReports = owner.recorder().interactionTransportationReports();
  auto const& interactionReport = interactionReports.back();
  require(interactionReport.federate == owner.federateHandle() &&
              interactionReport.interaction == ownerInteraction &&
              sameTransport(owner.rtiAmbassador(), interactionReport.transportation,
                            L"HLAbestEffort"),
          "interaction transportation query did not observe the committed change");

  observer.rtiAmbassador().unsubscribeInteractionClass(observerInteraction);
  observer.rtiAmbassador().unsubscribeObjectClassAttributes(
      observerClass, observerAttributes);
  owner.rtiAmbassador().unpublishInteractionClass(ownerInteraction);
  owner.rtiAmbassador().unpublishObjectClassAttributes(ownerClass, ownerAttributes);
  owner.rtiAmbassador().unpublishObjectClass(ownerClass);
  owner.resign(rti::DELETE_OBJECTS);
  observer.resign(rti::NO_ACTION);
}

void scenarioFederationTeardownIsolation(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.modelFom.empty(),
      "Federation teardown isolation requires an adapter-supplied rich FOM model");

  Session publisherA(options, model, "owner");
  Session receiverA(options, model, "member");
  Session publisherB(options, model, "owner");
  Session receiverB(options, model, "member");
  auto const federationA = federationName(options, "federation-teardown-isolation");
  auto const federationB = federationA + L"-child";

  publisherA.connect();
  receiverA.connect();
  publisherB.connect();
  receiverB.connect();
  publisherA.rtiAmbassador().createFederationExecution(
      federationA,
      options.modelFom.wstring(),
      options.logicalTimeImplementationName);
  publisherB.rtiAmbassador().createFederationExecution(
      federationB,
      options.modelFom.wstring(),
      options.logicalTimeImplementationName);
  publisherA.join(
      options.ownerFederateName + L"-teardown-a-publisher",
      options.federateType,
      federationA);
  receiverA.join(
      options.memberFederateName + L"-teardown-a-receiver",
      options.federateType,
      federationA);
  publisherB.join(
      options.ownerFederateName + L"-teardown-b-publisher",
      options.federateType,
      federationB);
  receiverB.join(
      options.memberFederateName + L"-teardown-b-receiver",
      options.federateType,
      federationB);

  struct RateFixture {
    rti::ObjectClassHandle publisherClass;
    rti::ObjectClassHandle receiverClass;
    rti::AttributeHandle publisherAttribute;
    rti::AttributeHandle receiverAttribute;
    rti::ObjectInstanceHandle object;
  };

  auto configure = [&](Session& publisher,
                       Session& receiver,
                       std::string const& description) {
    RateFixture fixture;
    fixture.publisherClass = publisher.rtiAmbassador().getObjectClassHandle(
        options.rateObjectClassName);
    fixture.receiverClass = receiver.rtiAmbassador().getObjectClassHandle(
        options.rateObjectClassName);
    fixture.publisherAttribute = publisher.rtiAmbassador().getAttributeHandle(
        fixture.publisherClass,
        options.rateBestEffortAttributeName);
    fixture.receiverAttribute = receiver.rtiAmbassador().getAttributeHandle(
        fixture.receiverClass,
        options.rateBestEffortAttributeName);
    require(
        fixture.publisherClass.isValid() && fixture.receiverClass.isValid() &&
            fixture.publisherAttribute.isValid() && fixture.receiverAttribute.isValid(),
        description + " update-rate isolation lookup returned an invalid handle");

    publisher.rtiAmbassador().publishObjectClassAttributes(
        fixture.publisherClass,
        rti::AttributeHandleSet{fixture.publisherAttribute});
    receiver.rtiAmbassador().subscribeObjectClassAttributes(
        fixture.receiverClass,
        rti::AttributeHandleSet{fixture.receiverAttribute},
        true,
        options.rateDesignatorName);
    require(
        receiver.rtiAmbassador().getUpdateRateValue(options.rateDesignatorName) > 0.0,
        description + " update-rate isolation designator did not resolve");

    fixture.object = publisher.rtiAmbassador().registerObjectInstance(
        fixture.publisherClass);
    require(
        fixture.object.isValid(),
        description + " update-rate isolation registration returned an invalid handle");
    waitFor(
        receiver,
        [&] { return receiver.recorder().hasDiscovery(fixture.object); },
        options,
        description + " update-rate isolation discovery");
    return fixture;
  };

  auto const fixtureA = configure(publisherA, receiverA, "Federation A");
  auto const fixtureB = configure(publisherB, receiverB, "Federation B");

  auto send = [&](Session& publisher, RateFixture const& fixture, std::uint8_t value) {
    std::vector<std::uint8_t> bytes{value};
    rti::AttributeHandleValueMap values;
    values.emplace(
        fixture.publisherAttribute,
        rti::VariableLengthData(bytes.data(), bytes.size()));
    publisher.rtiAmbassador().updateAttributeValues(
        fixture.object,
        values,
        rti::VariableLengthData{});
  };

  auto expectReflection = [&](Session& receiver,
                              RateFixture const& fixture,
                              std::uint8_t expected,
                              std::string const& description) {
    waitFor(
        receiver,
        [&] { return receiver.recorder().reflections().size() >= 1U; },
        options,
        description + " reflection");
    auto const reflections = receiver.recorder().reflections();
    require(
        reflections.size() == 1U,
        description + " delivered an unexpected reflection count");
    auto const& reflection = reflections.front();
    require(
        reflection.object == fixture.object && reflection.values.size() == 1U &&
            reflection.values.count(fixture.receiverAttribute) == 1U &&
            copyBytes(reflection.values.at(fixture.receiverAttribute)) ==
                std::vector<std::uint8_t>{expected},
        description + " delivered the wrong object or value");
  };

  auto observeSuppression = [&](Session& receiver, std::string const& description) {
    auto const deadline = Clock::now() + std::chrono::milliseconds(250);
    while (Clock::now() < deadline) {
      receiver.pump();
      std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    require(
        receiver.recorder().reflections().empty(),
        description + " delivered an update inside the active named-rate interval");
  };

  receiverA.recorder().clearReflection();
  send(publisherA, fixtureA, 0x11U);
  expectReflection(receiverA, fixtureA, 0x11U, "Federation A first update");
  receiverA.recorder().clearReflection();
  send(publisherA, fixtureA, 0x12U);
  observeSuppression(receiverA, "Federation A second update");

  receiverB.recorder().clearReflection();
  send(publisherB, fixtureB, 0x21U);
  expectReflection(receiverB, fixtureB, 0x21U, "Federation B first update");
  receiverB.recorder().clearReflection();
  send(publisherB, fixtureB, 0x22U);
  observeSuppression(receiverB, "Federation B second update");

  receiverA.resign(rti::NO_ACTION);
  publisherA.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  publisherA.rtiAmbassador().destroyFederationExecution(federationA);

  receiverB.recorder().clearReflection();
  send(publisherB, fixtureB, 0x23U);
  observeSuppression(
      receiverB,
      "Federation B update after Federation A teardown");

  receiverB.resign(rti::NO_ACTION);
  publisherB.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  publisherB.rtiAmbassador().destroyFederationExecution(federationB);
  receiverA.disconnect();
  publisherA.disconnect();
  receiverB.disconnect();
  publisherB.disconnect();
}

void scenarioHandleWireFormats(Options const& options, rti::CallbackModel model) {
  Session publisher(options, model, "owner");
  Session receiver(options, model, "member");
  auto const federation = federationName(options, "handle-wire-formats");
  connectAndJoin(publisher, receiver, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const receiverHandles = ddmHandles(receiver, options);
  require(
      publisherHandles.objectClass == receiverHandles.objectClass &&
          publisherHandles.attribute == receiverHandles.attribute &&
          publisherHandles.interactionClass == receiverHandles.interactionClass &&
          publisherHandles.parameter == receiverHandles.parameter &&
          publisherHandles.firstDimension == receiverHandles.firstDimension &&
          publisherHandles.secondDimension == receiverHandles.secondDimension,
      "handle wire-format setup returned different ordinary or dimension handles");
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "handle wire-format");

  auto const region = createDdmRegion(
      publisher,
      publisherHandles,
      1UL,
      5UL,
      2UL,
      7UL);
  verifyDdmRegion(
      publisher,
      publisherHandles,
      region,
      1UL,
      5UL,
      2UL,
      7UL,
      "handle wire-format region");

  auto requireHandleRoundTrip = [&](auto const& handle, auto decoder,
                                    std::string const& description) {
    auto const encoded = handle.encode();
    require(encoded.size() == handle.encodedLength(),
            description + " reported an inconsistent encoded length");
    require(encoded.size() > 0U, description + " produced an empty encoding");
    require(decoder(encoded) == handle, description + " did not round-trip");
  };
  requireHandleRoundTrip(
      publisherHandles.firstDimension,
      [&](rti::VariableLengthData const& encoded) {
        return publisher.rtiAmbassador().decodeDimensionHandle(encoded);
      },
      "Dimension handle");
  requireHandleRoundTrip(
      region,
      [&](rti::VariableLengthData const& encoded) {
        return publisher.rtiAmbassador().decodeRegionHandle(encoded);
      },
      "Region handle");

  rti::AttributeHandleSet publisherAttributes;
  publisherAttributes.insert(publisherHandles.attribute);
  rti::AttributeHandleSet receiverAttributes;
  receiverAttributes.insert(receiverHandles.attribute);
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherHandles.objectClass,
      publisherAttributes);
  publisher.rtiAmbassador().changeDefaultAttributeOrderType(
      publisherHandles.objectClass,
      publisherAttributes,
      rti::TIMESTAMP);
  receiver.rtiAmbassador().subscribeObjectClassAttributes(
      receiverHandles.objectClass,
      receiverAttributes,
      true,
      L"");
  auto const object = publisher.rtiAmbassador().registerObjectInstance(
      publisherHandles.objectClass);
  require(object.isValid(), "handle wire-format registration returned an invalid object");
  waitFor(
      receiver,
      [&] { return receiver.recorder().hasDiscovery(object); },
      options,
      "handle wire-format object discovery");

  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  enableTimestampedRoles(
      publisher,
      receiver,
      publisherTime,
      receiverTime,
      options,
      "handle wire-format");
  auto const messageTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      3U);
  std::vector<std::uint8_t> valueBytes{0x71U, 0x72U, 0x73U};
  std::vector<std::uint8_t> tagBytes{0x48U, 0x57U, 0x46U};
  rti::AttributeHandleValueMap values;
  values.emplace(
      publisherHandles.attribute,
      rti::VariableLengthData(valueBytes.data(), valueBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
  auto const retraction = publisher.rtiAmbassador().updateAttributeValues(
      object,
      values,
      tag,
      *messageTime);
  require(
      retraction.isValid(),
      "handle wire-format timestamped update returned an invalid retraction handle");
  requireHandleRoundTrip(
      retraction,
      [&](rti::VariableLengthData const& encoded) {
        return publisher.rtiAmbassador().decodeMessageRetractionHandle(encoded);
      },
      "Message retraction handle");
  requirePortableHandleEncoding(
      publisherHandles.firstDimension,
      "Dimension handle");
  requirePortableHandleEncoding(region, "Region handle");
  requirePortableHandleEncoding(retraction, "Message retraction handle");

  auto requireEmptyDecodeRejected = [&](auto decoder, std::string const& description) {
    requireException(
        [&] { static_cast<void>(decoder(rti::VariableLengthData{})); },
        L"CouldNotDecode",
        description + " accepted an empty encoding");
  };
  requireEmptyDecodeRejected(
      [&](rti::VariableLengthData const& encoded) {
        return publisher.rtiAmbassador().decodeDimensionHandle(encoded);
      },
      "Dimension handle decoder");
  requireEmptyDecodeRejected(
      [&](rti::VariableLengthData const& encoded) {
        return publisher.rtiAmbassador().decodeRegionHandle(encoded);
      },
      "Region handle decoder");
  requireEmptyDecodeRejected(
      [&](rti::VariableLengthData const& encoded) {
        return publisher.rtiAmbassador().decodeMessageRetractionHandle(encoded);
      },
      "Message retraction handle decoder");

  publisher.rtiAmbassador().retract(retraction);
  receiver.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeObjectClassAttributes(
      receiverHandles.objectClass,
      receiverAttributes);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherHandles.objectClass,
      publisherAttributes);
  publisher.rtiAmbassador().deleteRegion(region);
  receiver.resign(rti::NO_ACTION);
  publisher.resign(rti::DELETE_OBJECTS);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
}

void scenarioOrdinaryEdges(Options const& options, rti::CallbackModel model) {
  Session owner(options, model, "owner");
  Session member(options, model, "member");
  Session passive(options, model, "passive");
  auto const federation = federationName(options, "ordinary-edges");
  connectAndJoin(owner, member, options, federation, options.fom);
  passive.connect();
  passive.join(
      options.memberFederateName + L"-passive",
      options.federateType,
      federation);

  rti::ObjectClassHandle ownerClass;
  rti::AttributeHandle ownerAttribute;
  rti::InteractionClassHandle ownerInteraction;
  rti::ParameterHandle ownerParameter;
  handles(owner, options, ownerClass, ownerAttribute, ownerInteraction, ownerParameter);
  auto const memberClass = member.rtiAmbassador().getObjectClassHandle(options.objectClassName);
  auto const memberAttribute =
      member.rtiAmbassador().getAttributeHandle(memberClass, options.attributeName);
  auto const memberInteraction =
      member.rtiAmbassador().getInteractionClassHandle(options.interactionClassName);
  auto const passiveClass =
      passive.rtiAmbassador().getObjectClassHandle(options.objectClassName);
  auto const passiveAttribute =
      passive.rtiAmbassador().getAttributeHandle(passiveClass, options.attributeName);
  auto const passiveInteraction =
      passive.rtiAmbassador().getInteractionClassHandle(options.interactionClassName);
  require(memberClass.isValid() && memberAttribute.isValid(),
          "Ordinary-edge member handle lookup returned an invalid handle");
  require(memberInteraction.isValid(),
          "Ordinary-edge member interaction lookup returned an invalid handle");
  require(passiveClass.isValid() && passiveAttribute.isValid(),
          "Ordinary-edge passive handle lookup returned an invalid handle");
  require(passiveInteraction.isValid(),
          "Ordinary-edge passive interaction lookup returned an invalid handle");

  rti::AttributeHandleSet ownerAttributes;
  ownerAttributes.insert(ownerAttribute);
  rti::AttributeHandleSet memberAttributes;
  memberAttributes.insert(memberAttribute);
  rti::AttributeHandleSet passiveAttributes;
  passiveAttributes.insert(passiveAttribute);
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  member.rtiAmbassador().subscribeObjectClassAttributes(
      memberClass, memberAttributes, true, L"");
  member.rtiAmbassador().subscribeObjectClassAttributes(
      memberClass, memberAttributes, true, L"");
  passive.rtiAmbassador().subscribeObjectClassAttributes(
      passiveClass, passiveAttributes, false, L"");
  owner.rtiAmbassador().publishInteractionClass(ownerInteraction);
  owner.rtiAmbassador().publishInteractionClass(ownerInteraction);
  member.rtiAmbassador().subscribeInteractionClass(memberInteraction, true);
  member.rtiAmbassador().subscribeInteractionClass(memberInteraction, true);
  passive.rtiAmbassador().subscribeInteractionClass(passiveInteraction, false);

  std::vector<std::uint8_t> interactionValue{0x71U, 0x72U};
  std::vector<std::uint8_t> interactionTagBytes{0x81U, 0x82U};
  rti::VariableLengthData interactionTag(
      interactionTagBytes.data(), interactionTagBytes.size());
  rti::ParameterHandleValueMap interactionParameters;
  interactionParameters.emplace(
      ownerParameter,
      rti::VariableLengthData(interactionValue.data(), interactionValue.size()));
  owner.rtiAmbassador().sendInteraction(
      ownerInteraction, interactionParameters, interactionTag);
  waitFor(member, [&] { return member.recorder().interaction().present; }, options,
          "ordinary-edge interaction delivery");
  auto const receivedInteraction = member.recorder().interaction();
  require(receivedInteraction.interaction == memberInteraction,
          "Ordinary-edge interaction delivery returned the wrong class");
  require(receivedInteraction.parameters.size() == 1U &&
              receivedInteraction.parameters.count(ownerParameter) == 1U &&
              copyBytes(receivedInteraction.parameters.at(ownerParameter)) == interactionValue,
          "Ordinary-edge interaction delivery returned the wrong parameter value");
  require(receivedInteraction.tag == interactionTagBytes,
          "Ordinary-edge interaction delivery returned the wrong tag");
  require(receivedInteraction.producer == owner.federateHandle(),
          "Ordinary-edge interaction delivery returned the wrong producer");
  for (int pass = 0; pass != 8; ++pass) {
    passive.pump();
  }
  require(passive.recorder().interaction().present,
          "Passive interaction declaration did not receive active-relevance delivery");

  requireException(
      [&] {
        passive.rtiAmbassador().sendInteraction(
            passiveInteraction, interactionParameters, interactionTag);
      },
      L"InteractionClassNotPublished",
      "ordinary-edge interaction send without publication");
  rti::ParameterHandleValueMap invalidInteractionParameters;
  invalidInteractionParameters.emplace(rti::ParameterHandle{}, rti::VariableLengthData{});
  requireException(
      [&] {
        owner.rtiAmbassador().sendInteraction(
            ownerInteraction, invalidInteractionParameters, interactionTag);
      },
      L"InteractionParameterNotDefined",
      "ordinary-edge interaction send with an undefined parameter");
  member.recorder().clearInteraction();
  member.rtiAmbassador().unsubscribeInteractionClass(memberInteraction);
  owner.rtiAmbassador().sendInteraction(
      ownerInteraction, interactionParameters, interactionTag);
  for (int pass = 0; pass != 8; ++pass) {
    member.pump();
  }
  require(!member.recorder().interaction().present,
          "Unsubscribed member unexpectedly received a later interaction");
  owner.rtiAmbassador().unpublishInteractionClass(ownerInteraction);
  requireException(
      [&] {
        owner.rtiAmbassador().sendInteraction(
            ownerInteraction, interactionParameters, interactionTag);
      },
      L"InteractionClassNotPublished",
      "ordinary-edge interaction send after unpublication");

  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(object.isValid(), "Ordinary-edge registration returned an invalid handle");
  waitFor(member, [&] { return member.recorder().discovery().present; }, options,
          "ordinary-edge discovery");
  auto const knownObject = member.recorder().discovery().object;
  require(knownObject == object, "Ordinary-edge discovery returned the wrong object");
  for (int pass = 0; pass != 8; ++pass) {
    passive.pump();
  }
  require(passive.recorder().discovery().present,
          "Passive declaration did not receive active-relevance discovery");
  require(passive.recorder().discovery().object == object,
          "Passive declaration discovery returned the wrong object");

  rti::AttributeHandleValueMap ownerValues;
  std::vector<std::uint8_t> valueBytes{0x11U, 0x22U};
  ownerValues.emplace(
      ownerAttribute,
      rti::VariableLengthData(valueBytes.data(), valueBytes.size()));
  requireException(
      [&] {
        owner.rtiAmbassador().updateAttributeValues(
            rti::ObjectInstanceHandle{},
            ownerValues,
            rti::VariableLengthData{});
      },
      L"ObjectInstanceNotKnown",
      "ordinary update for an unknown object instance");
  owner.rtiAmbassador().updateAttributeValues(object, ownerValues, rti::VariableLengthData{});
  waitFor(member, [&] { return member.recorder().reflection().present; }, options,
          "ordinary-edge reflection");
  require(copyBytes(member.recorder().reflection().values.at(memberAttribute)) == valueBytes,
          "Ordinary-edge reflection returned the wrong value");
  for (int pass = 0; pass != 8; ++pass) {
    passive.pump();
  }
  require(passive.recorder().reflection().present,
          "Passive declaration did not receive active-relevance reflection");
  require(passive.recorder().reflection().object == object &&
              passive.recorder().reflection().values.count(passiveAttribute) == 1U &&
              copyBytes(passive.recorder().reflection().values.at(passiveAttribute)) ==
                  valueBytes,
          "Passive declaration reflection returned the wrong attribute value");

  rti::AttributeHandleValueMap memberValues;
  memberValues.emplace(
      memberAttribute,
      rti::VariableLengthData(valueBytes.data(), valueBytes.size()));
  requireException(
      [&] {
        member.rtiAmbassador().updateAttributeValues(
            knownObject, memberValues, rti::VariableLengthData{});
      },
      L"AttributeNotOwned",
      "non-owner ordinary attribute update");
  requireException(
      [&] {
        member.rtiAmbassador().requestAttributeValueUpdate(
            rti::ObjectInstanceHandle{}, memberAttributes, rti::VariableLengthData{});
      },
      L"ObjectInstanceNotKnown",
      "unknown object attribute-value request");
  requireException(
      [&] {
        static_cast<void>(member.rtiAmbassador().getKnownObjectClassHandle(
            rti::ObjectInstanceHandle{}));
      },
      L"ObjectInstanceNotKnown",
      "unknown object class lookup");
  rti::AttributeHandleValueMap invalidValues;
  invalidValues.emplace(rti::AttributeHandle{}, rti::VariableLengthData{});
  requireException(
      [&] {
        owner.rtiAmbassador().updateAttributeValues(
            object, invalidValues, rti::VariableLengthData{});
      },
      L"AttributeNotDefined",
      "ordinary update with an undefined attribute");

  member.recorder().clearReflection();
  member.rtiAmbassador().unsubscribeObjectClassAttributes(memberClass, memberAttributes);
  owner.rtiAmbassador().updateAttributeValues(object, ownerValues, rti::VariableLengthData{});
  for (int pass = 0; pass != 8; ++pass) {
    member.pump();
  }
  require(!member.recorder().reflection().present,
          "Unsubscribed member unexpectedly received an attribute reflection");
  passive.rtiAmbassador().unsubscribeObjectClassAttributes(passiveClass, passiveAttributes);
  passive.rtiAmbassador().unsubscribeInteractionClass(passiveInteraction);
  owner.rtiAmbassador().unpublishObjectClassAttributes(ownerClass, ownerAttributes);

  owner.resign(rti::DELETE_OBJECTS);
  member.resign(rti::NO_ACTION);
  passive.resign(rti::NO_ACTION);
}

void scenarioOrdinaryEdgesContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioOrdinaryEdges(options, model);
}


void scenarioLocalDeleteObjectInstance(
    Options const& options,
    rti::CallbackModel model) {
  Session unjoined(options, model, "local-delete-unjoined");
  Session owner(options, model, "owner");
  Session requester(options, model, "requester");
  auto const federation = federationName(options, "local-delete-object-instance");

  requireException(
      [&] { owner.rtiAmbassador().localDeleteObjectInstance(rti::ObjectInstanceHandle{}); },
      L"NotConnected",
      "local deletion before connect");
  unjoined.connect();
  requireException(
      [&] {
        unjoined.rtiAmbassador().localDeleteObjectInstance(rti::ObjectInstanceHandle{});
      },
      L"FederateNotExecutionMember",
      "local deletion after connect before join");

  connectAndJoin(owner, requester, options, federation, options.fom);

  auto const ownerClass = owner.rtiAmbassador().getObjectClassHandle(options.objectClassName);
  auto const ownerAttribute = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.attributeName);
  auto const requesterClass = requester.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const requesterAttribute = requester.rtiAmbassador().getAttributeHandle(
      requesterClass,
      options.attributeName);
  require(
      ownerClass.isValid() && ownerAttribute.isValid() && requesterClass.isValid() &&
          requesterAttribute.isValid(),
      "Local deletion handle lookup returned an invalid handle");
  rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
  rti::AttributeHandleSet const requesterAttributes{requesterAttribute};

  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  requester.rtiAmbassador().subscribeObjectClassAttributes(
      requesterClass,
      requesterAttributes,
      true,
      L"");

  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(object.isValid(), "Local deletion registration returned an invalid object handle");
  waitFor(
      requester,
      [&] { return requester.recorder().hasDiscovery(object); },
      options,
      "local deletion object discovery");
  auto const discovery = requester.recorder().discovery();
  require(
      discovery.object == object && discovery.objectClass == requesterClass &&
          requester.rtiAmbassador().getKnownObjectClassHandle(object) == requesterClass,
      "Local deletion discovery did not establish object identity");

  requireException(
      [&] { owner.rtiAmbassador().localDeleteObjectInstance(object); },
      L"FederateOwnsAttributes",
      "local deletion while owning object attributes");

  std::vector<std::uint8_t> acquisitionTagBytes{0x51U, 0x18U};
  rti::VariableLengthData const acquisitionTag(
      acquisitionTagBytes.data(),
      acquisitionTagBytes.size());
  requester.rtiAmbassador().publishObjectClassAttributes(
      requesterClass,
      requesterAttributes);
  requester.rtiAmbassador().attributeOwnershipAcquisition(
      object,
      requesterAttributes,
      acquisitionTag);
  requireException(
      [&] { requester.rtiAmbassador().localDeleteObjectInstance(object); },
      L"OwnershipAcquisitionPending",
      "local deletion while ownership acquisition is pending");
  requester.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);

  // Rejoin a fresh requester so the successful local-delete transition is
  // independent of the canceled ownership-acquisition request.
  Session freshRequester(options, model, "local-delete-requester-fresh");
  freshRequester.connect();
  freshRequester.join(
      options.memberFederateName + L"-fresh",
      options.federateType,
      federation);
  auto const freshClass = freshRequester.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const freshAttribute = freshRequester.rtiAmbassador().getAttributeHandle(
      freshClass,
      options.attributeName);
  require(
      freshClass.isValid() && freshAttribute.isValid(),
      "Fresh local deletion handle lookup returned an invalid handle");
  rti::AttributeHandleSet const freshAttributes{freshAttribute};
  freshRequester.rtiAmbassador().subscribeObjectClassAttributes(
      freshClass,
      freshAttributes,
      true,
      L"");
  waitFor(
      freshRequester,
      [&] { return freshRequester.recorder().hasDiscovery(object); },
      options,
      "fresh requester object discovery");

  freshRequester.rtiAmbassador().localDeleteObjectInstance(object);
  requireException(
      [&] { static_cast<void>(freshRequester.rtiAmbassador().getKnownObjectClassHandle(object)); },
      L"ObjectInstanceNotKnown",
      "object identity after local deletion");

  freshRequester.recorder().clearDiscovery();
  freshRequester.rtiAmbassador().subscribeObjectClassAttributes(
      freshClass,
      freshAttributes,
      true,
      L"");
  waitFor(
      freshRequester,
      [&] { return freshRequester.recorder().hasDiscovery(object); },
      options,
      "rediscovery after local deletion");
  require(
      freshRequester.rtiAmbassador().getKnownObjectClassHandle(object) == freshClass,
      "Rediscovery after local deletion did not restore object identity");

  freshRequester.recorder().clearReflection();
  std::vector<std::uint8_t> valueBytes{0x04U, 0x20U};
  rti::AttributeHandleValueMap values;
  values.emplace(
      ownerAttribute,
      rti::VariableLengthData(valueBytes.data(), valueBytes.size()));
  std::vector<std::uint8_t> updateTagBytes{0x7AU};
  rti::VariableLengthData const updateTag(updateTagBytes.data(), updateTagBytes.size());
  owner.rtiAmbassador().updateAttributeValues(object, values, updateTag);
  waitFor(
      freshRequester,
      [&] { return freshRequester.recorder().reflectionCount() == 1U; },
      options,
      "post-local-delete attribute reflection");
  auto const reflection = freshRequester.recorder().reflection();
  require(
      reflection.present && reflection.object == object && reflection.tag == updateTagBytes &&
          reflection.producer == owner.federateHandle() &&
          reflection.values.find(freshAttribute) != reflection.values.end() &&
          copyBytes(reflection.values.at(freshAttribute)) == valueBytes,
      "Post-local-delete reflection returned the wrong metadata or value");

  freshRequester.resign(rti::NO_ACTION);
  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  unjoined.disconnect();
  requester.disconnect();
  freshRequester.disconnect();
  owner.disconnect();
}

void scenarioObjectNameReservationLifecycle(
    Options const& options,
    rti::CallbackModel model) {
  Session unjoined(options, model, "unjoined");
  Session owner(options, model, "owner");
  Session peer(options, model, "member");
  auto const federation = federationName(options, "object-name-reservation-lifecycle");
  std::set<std::wstring> const lifecycleNames{
      L"tck-lifecycle-reservation-a",
      L"tck-lifecycle-reservation-b"};

  auto requireReservationLifecycle = [&](std::wstring const& expected,
                                          std::string const& phase) {
    requireException(
        [&] { unjoined.rtiAmbassador().reserveObjectInstanceName(*lifecycleNames.begin()); },
        expected,
        "reserving an object name " + phase);
    requireException(
        [&] { unjoined.rtiAmbassador().releaseObjectInstanceName(*lifecycleNames.begin()); },
        expected,
        "releasing an object name " + phase);
    requireException(
        [&] { unjoined.rtiAmbassador().reserveMultipleObjectInstanceNames(lifecycleNames); },
        expected,
        "reserving multiple object names " + phase);
    requireException(
        [&] { unjoined.rtiAmbassador().releaseMultipleObjectInstanceNames(lifecycleNames); },
        expected,
        "releasing multiple object names " + phase);
  };

  requireReservationLifecycle(L"NotConnected", "before connect");
  unjoined.connect();
  requireReservationLifecycle(L"FederateNotExecutionMember", "after connect before join");

  owner.connect();
  peer.connect();
  owner.rtiAmbassador().createFederationExecution(
      federation,
      options.fom.wstring(),
      options.logicalTimeImplementationName);
  owner.join(options.ownerFederateName, options.federateType, federation);
  peer.join(options.memberFederateName, options.federateType, federation);

  requireException(
      [&] { owner.rtiAmbassador().reserveObjectInstanceName(L""); },
      L"IllegalName",
      "reserving an empty object name");
  requireException(
      [&] { owner.rtiAmbassador().reserveObjectInstanceName(L"HLA.TckReserved"); },
      L"IllegalName",
      "reserving an HLA-namespace object name");
  requireException(
      [&] { owner.rtiAmbassador().reserveMultipleObjectInstanceNames({}); },
      L"NameSetWasEmpty",
      "reserving an empty object-name set");
  requireException(
      [&] {
        owner.rtiAmbassador().reserveMultipleObjectInstanceNames(
            {L"tck-valid-object-name", L"HLA.TckInvalidObjectName"});
      },
      L"IllegalName",
      "reserving a set containing an HLA-namespace object name");

  auto const singleName = federation + L"-single-reservation";
  owner.recorder().clearReservations();
  owner.rtiAmbassador().reserveObjectInstanceName(singleName);
  if (model == rti::HLA_EVOKED) {
    require(
        !owner.recorder().reservationSucceeded(singleName),
        "evoked reservation callback arrived before callback servicing");
  }
  waitFor(
      owner,
      [&] { return owner.recorder().reservationSucceeded(singleName); },
      options,
      "single object-name reservation success");

  peer.recorder().clearReservations();
  peer.rtiAmbassador().reserveObjectInstanceName(singleName);
  if (model == rti::HLA_EVOKED) {
    require(
        !peer.recorder().reservationFailed(singleName),
        "evoked reservation failure callback arrived before callback servicing");
  }
  waitFor(
      peer,
      [&] { return peer.recorder().reservationFailed(singleName); },
      options,
      "contended object-name reservation failure");

  owner.rtiAmbassador().releaseObjectInstanceName(singleName);
  requireException(
      [&] { owner.rtiAmbassador().releaseObjectInstanceName(singleName); },
      L"ObjectInstanceNameNotReserved",
      "releasing an object name twice");

  peer.recorder().clearReservations();
  peer.rtiAmbassador().reserveObjectInstanceName(singleName);
  waitFor(
      peer,
      [&] { return peer.recorder().reservationSucceeded(singleName); },
      options,
      "reusing a released object name");
  peer.rtiAmbassador().releaseObjectInstanceName(singleName);

  auto const multipleA = federation + L"-multiple-a";
  auto const multipleB = federation + L"-multiple-b";
  auto const multipleC = federation + L"-multiple-c";
  std::set<std::wstring> const ownerNames{multipleA, multipleB};
  std::set<std::wstring> const peerNames{multipleB, multipleC};
  std::set<std::wstring> const peerSucceeded{multipleC};
  std::set<std::wstring> const peerFailed{multipleB};

  owner.recorder().clearReservations();
  owner.rtiAmbassador().reserveMultipleObjectInstanceNames(ownerNames);
  if (model == rti::HLA_EVOKED) {
    require(
        !owner.recorder().multipleReservationSucceeded(ownerNames),
        "evoked multiple-reservation callback arrived before callback servicing");
  }
  waitFor(
      owner,
      [&] { return owner.recorder().multipleReservationSucceeded(ownerNames); },
      options,
      "multiple object-name reservation success");

  peer.recorder().clearReservations();
  peer.rtiAmbassador().reserveMultipleObjectInstanceNames(peerNames);
  if (model == rti::HLA_EVOKED) {
    require(
        !peer.recorder().multipleReservationSucceeded(peerSucceeded) &&
            !peer.recorder().multipleReservationFailed(peerFailed),
        "evoked mixed multiple-reservation callbacks arrived before callback servicing");
  }
  waitFor(
      peer,
      [&] {
        return peer.recorder().multipleReservationSucceeded(peerSucceeded) &&
            peer.recorder().multipleReservationFailed(peerFailed);
      },
      options,
      "mixed multiple object-name reservation results");

  requireException(
      [&] {
        owner.rtiAmbassador().releaseMultipleObjectInstanceNames(
            {multipleA, multipleC});
      },
      L"ObjectInstanceNameNotReserved",
      "releasing a mixed-owner object-name set");
  peer.rtiAmbassador().releaseObjectInstanceName(multipleC);
  owner.rtiAmbassador().releaseMultipleObjectInstanceNames(ownerNames);
  owner.rtiAmbassador().releaseMultipleObjectInstanceNames({});

  auto const resignedName = federation + L"-released-on-resign";
  owner.recorder().clearReservations();
  owner.rtiAmbassador().reserveObjectInstanceName(resignedName);
  waitFor(
      owner,
      [&] { return owner.recorder().reservationSucceeded(resignedName); },
      options,
      "object-name reservation before resignation");
  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);

  peer.recorder().clearReservations();
  peer.rtiAmbassador().reserveObjectInstanceName(resignedName);
  waitFor(
      peer,
      [&] { return peer.recorder().reservationSucceeded(resignedName); },
      options,
      "object-name reuse after owner resignation");
  peer.rtiAmbassador().releaseObjectInstanceName(resignedName);

  peer.resign(rti::NO_ACTION);
  peer.rtiAmbassador().destroyFederationExecution(federation);
  unjoined.disconnect();
  owner.disconnect();
  peer.disconnect();
}

void scenarioFinalFederateResignationCleanup(
    Options const& options,
    rti::CallbackModel model) {
  Session lifecycle(options, model, "final-federate-lifecycle");
  auto const federation = federationName(
      options,
      "final-federate-resignation-cleanup");
  lifecycle.connect();
  lifecycle.rtiAmbassador().createFederationExecution(
      federation,
      options.fom.wstring(),
      options.logicalTimeImplementationName);
  lifecycle.join(
      options.ownerFederateName + L"-final-federate-first",
      options.federateType,
      federation);

  auto const firstClass = lifecycle.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const firstAttribute = lifecycle.rtiAmbassador().getAttributeHandle(
      firstClass,
      options.attributeName);
  require(
      firstClass.isValid() && firstAttribute.isValid(),
      "Final-federate resignation lookup returned an invalid handle");
  rti::AttributeHandleSet const firstAttributes{firstAttribute};
  lifecycle.rtiAmbassador().publishObjectClassAttributes(
      firstClass,
      firstAttributes);

  auto const originalObject = lifecycle.rtiAmbassador().registerObjectInstance(firstClass);
  require(
      originalObject.isValid(),
      "Final-federate resignation returned an invalid original object handle");
  auto const reusableName = lifecycle.rtiAmbassador().getObjectInstanceName(originalObject);
  require(
      !reusableName.empty(),
      "Final-federate resignation returned an empty object instance name");

  // IEEE 1516.1 final-federate resignation applies the cleanup directive
  // required to delete owned objects even when the caller supplies NO_ACTION.
  lifecycle.resign(rti::NO_ACTION);
  lifecycle.join(
      options.ownerFederateName + L"-final-federate-rejoined",
      options.federateType,
      federation);

  auto const secondClass = lifecycle.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const secondAttribute = lifecycle.rtiAmbassador().getAttributeHandle(
      secondClass,
      options.attributeName);
  require(
      secondClass.isValid() && secondAttribute.isValid(),
      "Final-federate rejoin lookup returned an invalid handle");
  rti::AttributeHandleSet const secondAttributes{secondAttribute};
  lifecycle.rtiAmbassador().publishObjectClassAttributes(
      secondClass,
      secondAttributes);

  lifecycle.recorder().clearReservations();
  lifecycle.rtiAmbassador().reserveObjectInstanceName(reusableName);
  if (model == rti::HLA_EVOKED) {
    require(
        !lifecycle.recorder().reservationSucceeded(reusableName),
        "Evoked final-federate reservation callback arrived before servicing");
  }
  waitFor(
      lifecycle,
      [&] { return lifecycle.recorder().reservationSucceeded(reusableName); },
      options,
      "object-name reuse after final-federate resignation");
  auto const replacementObject = lifecycle.rtiAmbassador().registerObjectInstance(
      secondClass,
      reusableName);
  require(
      replacementObject.isValid(),
      "Final-federate resignation did not release the reusable object name");
  require(
      lifecycle.rtiAmbassador().getObjectInstanceHandle(reusableName) == replacementObject,
      "Final-federate named registration did not round-trip its object handle");

  lifecycle.resign(rti::NO_ACTION);
  lifecycle.rtiAmbassador().destroyFederationExecution(federation);
  lifecycle.disconnect();
}

