void scenarioFederationSaveRestore(Options const& options, rti::CallbackModel model) {
  Session lifecycle(options, model, "save-restore-lifecycle");
  std::wstring const lifecycleSaveLabel = L"tck-save-restore-lifecycle-save";
  std::wstring const lifecycleRestoreLabel = L"tck-save-restore-lifecycle-restore";
  auto checkSaveRestoreLifecycle = [&](std::wstring const& expected,
                                        std::string const& phase) {
    requireException(
        [&] { lifecycle.rtiAmbassador().requestFederationSave(lifecycleSaveLabel); },
        expected,
        "requesting a federation save " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().federateSaveBegun(); },
        expected,
        "beginning a federate save " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().federateSaveComplete(); },
        expected,
        "completing a federate save " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().federateSaveNotComplete(); },
        expected,
        "reporting an incomplete federate save " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().abortFederationSave(); },
        expected,
        "aborting a federation save " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().queryFederationSaveStatus(); },
        expected,
        "querying federation save status " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().requestFederationRestore(lifecycleRestoreLabel); },
        expected,
        "requesting a federation restore " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().federateRestoreComplete(); },
        expected,
        "completing a federate restore " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().federateRestoreNotComplete(); },
        expected,
        "reporting an incomplete federate restore " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().abortFederationRestore(); },
        expected,
        "aborting a federation restore " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().queryFederationRestoreStatus(); },
        expected,
        "querying federation restore status " + phase);
  };
  checkSaveRestoreLifecycle(L"NotConnected", "before connection");
  lifecycle.connect();
  checkSaveRestoreLifecycle(L"FederateNotExecutionMember", "before joining an execution");
  lifecycle.disconnect();

  Session owner(options, model, "owner");
  Session peer(options, model, "member");
  auto const federation = federationName(options, "federation-save-restore");
  connectAndJoin(owner, peer, options, federation, options.fom);

  auto lifecycleTime = makeTimeContext(owner);
  requireException(
      [&] {
        lifecycle.rtiAmbassador().requestFederationSave(
            lifecycleSaveLabel,
            *lifecycleTime.initial);
      },
      L"NotConnected",
      "requesting a timestamped federation save before connection");
  lifecycle.connect();
  requireException(
      [&] {
        lifecycle.rtiAmbassador().requestFederationSave(
            lifecycleSaveLabel,
            *lifecycleTime.initial);
      },
      L"FederateNotExecutionMember",
      "requesting a timestamped federation save before joining an execution");
  lifecycle.disconnect();

  requireException(
      [&] { owner.rtiAmbassador().federateSaveBegun(); },
      L"SaveNotInitiated",
      "federateSaveBegun before a save request");
  requireException(
      [&] { owner.rtiAmbassador().federateSaveComplete(); },
      L"FederateHasNotBegunSave",
      "federateSaveComplete before save preparation");
  requireException(
      [&] { owner.rtiAmbassador().federateSaveNotComplete(); },
      L"FederateHasNotBegunSave",
      "federateSaveNotComplete before save preparation");
  requireException(
      [&] { owner.rtiAmbassador().abortFederationSave(); },
      L"SaveNotInProgress",
      "abortFederationSave without a save in progress");
  requireException(
      [&] { owner.rtiAmbassador().federateRestoreComplete(); },
      L"RestoreNotRequested",
      "federateRestoreComplete before a restore request");
  requireException(
      [&] { owner.rtiAmbassador().federateRestoreNotComplete(); },
      L"RestoreNotRequested",
      "federateRestoreNotComplete before a restore request");
  requireException(
      [&] { owner.rtiAmbassador().abortFederationRestore(); },
      L"RestoreNotInProgress",
      "abortFederationRestore without a restore in progress");

  auto const ownerHandle = owner.federateHandle();
  auto const peerHandle = peer.federateHandle();
  std::wstring const saveLabel = L"tck-save-restore";
  owner.rtiAmbassador().requestFederationSave(saveLabel);
  waitForSessions(
      {&owner, &peer},
      [&] {
        return owner.federateSaveInitiations().size() >= 1U &&
            peer.federateSaveInitiations().size() >= 1U;
      },
      options,
      "federate save initiation callbacks");
  require(owner.federateSaveInitiations().front() == saveLabel &&
              peer.federateSaveInitiations().front() == saveLabel,
          "federate save initiation returned the wrong label");
  require(owner.federateSaveTimes().empty() && peer.federateSaveTimes().empty(),
          "untimed federation save unexpectedly used a timestamped callback");

  auto const saveStatusBefore = owner.federationSaveStatusResponses().size();
  owner.rtiAmbassador().queryFederationSaveStatus();
  waitFor(
      owner,
      [&] { return owner.federationSaveStatusResponses().size() > saveStatusBefore; },
      options,
      "in-progress federation save status");
  auto const instructed = owner.federationSaveStatusResponses().back();
  require(instructed.size() == 2U,
          "federation save status omitted a joined federate");
  auto const findSaveStatus = [&](rti::FederateHandle const& handle,
                                  rti::SaveStatus expected,
                                  std::string const& description) {
    auto const found = std::find_if(
        instructed.begin(),
        instructed.end(),
        [&](auto const& entry) { return entry.first == handle; });
    require(found != instructed.end(), description + " omitted a federate handle");
    require(found->second == expected, description + " returned the wrong state");
  };
  findSaveStatus(ownerHandle, rti::FEDERATE_INSTRUCTED_TO_SAVE, "owner save status");
  findSaveStatus(peerHandle, rti::FEDERATE_INSTRUCTED_TO_SAVE, "peer save status");

  owner.rtiAmbassador().federateSaveBegun();
  peer.rtiAmbassador().federateSaveBegun();
  auto const savingStatusBefore = owner.federationSaveStatusResponses().size();
  owner.rtiAmbassador().queryFederationSaveStatus();
  waitFor(
      owner,
      [&] {
        return owner.federationSaveStatusResponses().size() > savingStatusBefore;
      },
      options,
      "saving federation save status");
  auto const saving = owner.federationSaveStatusResponses().back();
  require(saving.size() == 2U,
          "saving federation status omitted a joined federate");
  for (auto const& entry : saving) {
    require(entry.second == rti::FEDERATE_SAVING,
            "federateSaveBegun did not advance the save status");
  }

  owner.rtiAmbassador().federateSaveComplete();
  require(owner.federationSavedCount() == 0U,
          "federationSaved arrived before every federate completed its save");
  peer.rtiAmbassador().federateSaveComplete();
  waitForSessions(
      {&owner, &peer},
      [&] {
        return owner.federationSavedCount() >= 1U &&
            peer.federationSavedCount() >= 1U;
      },
      options,
      "federation saved callbacks");
  require(owner.federationNotSavedReasons().empty() &&
              peer.federationNotSavedReasons().empty(),
          "successful federation save reported a failure");

  auto const restoreRequestBefore = owner.federationRestoreRequestsSucceeded().size();
  owner.rtiAmbassador().requestFederationRestore(saveLabel);
  waitForSessions(
      {&owner, &peer},
      [&] {
        return owner.federationRestoreRequestsSucceeded().size() > restoreRequestBefore &&
            owner.federationRestoreBegunCount() >= 1U &&
            peer.federationRestoreBegunCount() >= 1U &&
            owner.federateRestoreInitiations().size() >= 1U &&
            peer.federateRestoreInitiations().size() >= 1U;
      },
      options,
      "federation restore initiation callbacks");
  require(owner.federationRestoreRequestsSucceeded().back() == saveLabel,
          "restore request confirmation returned the wrong label");
  require(owner.federationRestoreRequestsFailed().empty() &&
              peer.federationRestoreRequestsFailed().empty(),
          "successful restore request reported a failure");

  auto const ownerRestore = owner.federateRestoreInitiations().back();
  auto const peerRestore = peer.federateRestoreInitiations().back();
  require(ownerRestore.label == saveLabel && peerRestore.label == saveLabel,
          "restore initiation returned the wrong save label");
  require(ownerRestore.federateName == options.ownerFederateName &&
              peerRestore.federateName == options.memberFederateName,
          "restore initiation returned the wrong federate name");
  require(ownerRestore.postRestoreFederateHandle.isValid() &&
              peerRestore.postRestoreFederateHandle.isValid(),
          "restore initiation returned an invalid post-restore handle");

  auto const restoreStatusBefore = owner.federationRestoreStatusResponses().size();
  owner.rtiAmbassador().queryFederationRestoreStatus();
  waitFor(
      owner,
      [&] {
        return owner.federationRestoreStatusResponses().size() > restoreStatusBefore;
      },
      options,
      "in-progress federation restore status");
  auto const restoring = owner.federationRestoreStatusResponses().back();
  require(restoring.size() == 2U,
          "restoring federation status omitted a joined federate");
  for (auto const& entry : restoring) {
    require(entry.status == rti::FEDERATE_RESTORING,
            "restore initiation did not advance the restore status");
  }

  owner.rtiAmbassador().federateRestoreComplete();
  peer.rtiAmbassador().federateRestoreComplete();
  waitForSessions(
      {&owner, &peer},
      [&] {
        return owner.federationRestoredCount() >= 1U &&
            peer.federationRestoredCount() >= 1U;
      },
      options,
      "federation restored callbacks");
  require(owner.federationNotRestoredReasons().empty() &&
              peer.federationNotRestoredReasons().empty(),
          "successful federation restore reported a failure");
  require(
      owner.rtiAmbassador().getFederateHandle(options.ownerFederateName) ==
          ownerRestore.postRestoreFederateHandle,
      "owner post-restore federate handle did not become authoritative");
  require(
      peer.rtiAmbassador().getFederateHandle(options.memberFederateName) ==
          peerRestore.postRestoreFederateHandle,
      "peer post-restore federate handle did not become authoritative");
  require(
      owner.rtiAmbassador().getFederateName(ownerRestore.postRestoreFederateHandle) ==
          options.ownerFederateName,
      "owner post-restore handle-to-name lookup did not round-trip");
  require(
      peer.rtiAmbassador().getFederateName(peerRestore.postRestoreFederateHandle) ==
          options.memberFederateName,
      "peer post-restore handle-to-name lookup did not round-trip");

  auto const restoredStatusBefore = owner.federationRestoreStatusResponses().size();
  owner.rtiAmbassador().queryFederationRestoreStatus();
  waitFor(
      owner,
      [&] {
        return owner.federationRestoreStatusResponses().size() > restoredStatusBefore;
      },
      options,
      "completed federation restore status");
  auto const restoredStatus = owner.federationRestoreStatusResponses().back();
  require(restoredStatus.size() == 2U,
          "completed federation restore status omitted a joined federate");
  for (auto const& entry : restoredStatus) {
    require(entry.status == rti::NO_RESTORE_IN_PROGRESS,
            "completed federation restore retained an active status");
  }

  // Exercise the standard negative completion paths after the successful
  // round trip.  These do not depend on a private save-file format.
  std::wstring const failedSaveLabel = L"tck-save-failure";
  owner.rtiAmbassador().requestFederationSave(failedSaveLabel);
  waitForSessions(
      {&owner, &peer},
      [&] {
        return owner.federateSaveInitiations().size() >= 2U &&
            peer.federateSaveInitiations().size() >= 2U;
      },
      options,
      "failed federation save initiation");
  owner.rtiAmbassador().federateSaveBegun();
  peer.rtiAmbassador().federateSaveBegun();
  auto const failedSaveBefore = owner.federationNotSavedReasons().size();
  peer.rtiAmbassador().federateSaveNotComplete();
  waitForSessions(
      {&owner, &peer},
      [&] {
        return owner.federationNotSavedReasons().size() > failedSaveBefore &&
            peer.federationNotSavedReasons().size() > failedSaveBefore;
      },
      options,
      "federation save failure callbacks");
  require(owner.federationNotSavedReasons().back() ==
              rti::FEDERATE_REPORTED_FAILURE_DURING_SAVE &&
              peer.federationNotSavedReasons().back() ==
                  rti::FEDERATE_REPORTED_FAILURE_DURING_SAVE,
          "federateSaveNotComplete returned the wrong failure reason");

  std::wstring const abortedSaveLabel = L"tck-save-abort";
  owner.rtiAmbassador().requestFederationSave(abortedSaveLabel);
  waitForSessions(
      {&owner, &peer},
      [&] {
        return owner.federateSaveInitiations().size() >= 3U &&
            peer.federateSaveInitiations().size() >= 3U;
      },
      options,
      "aborted federation save initiation");
  auto const abortedSaveBefore = owner.federationNotSavedReasons().size();
  owner.rtiAmbassador().abortFederationSave();
  waitForSessions(
      {&owner, &peer},
      [&] {
        return owner.federationNotSavedReasons().size() > abortedSaveBefore &&
            peer.federationNotSavedReasons().size() > abortedSaveBefore;
      },
      options,
      "federation save abort callbacks");
  require(owner.federationNotSavedReasons().back() == rti::SAVE_ABORTED &&
              peer.federationNotSavedReasons().back() == rti::SAVE_ABORTED,
          "abortFederationSave returned the wrong failure reason");

  peer.resign(rti::NO_ACTION);
  owner.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  peer.disconnect();
  owner.disconnect();
}


void scenarioFqrTimedFederationSaveCallback(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.logicalTimeImplementationName.empty(),
      "FQR timed-save callback requires an adapter-supplied logical-time implementation");

  Session constrainedRegulator(options, model, "owner");
  Session sender(options, model, "member");
  auto const federation = federationName(options, "fqr-timed-save-callback");
  connectAndJoin(constrainedRegulator, sender, options, federation, options.fom);

  auto actorTime = makeTimeContext(constrainedRegulator);
  auto senderTime = makeTimeContext(sender);
  rti::ObjectClassHandle objectClass;
  rti::AttributeHandle attribute;
  rti::InteractionClassHandle interaction;
  rti::ParameterHandle parameter;
  handles(constrainedRegulator, options, objectClass, attribute, interaction, parameter);
  auto const senderInteraction = sender.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const senderParameter = sender.rtiAmbassador().getParameterHandle(
      senderInteraction, options.parameterName);
  require(
      senderInteraction.isValid() && senderParameter.isValid() &&
          interaction == senderInteraction && parameter == senderParameter &&
          actorTime.factory->getName() == senderTime.factory->getName(),
      "FQR timed-save interaction/time handles did not agree across members");

  sender.rtiAmbassador().publishInteractionClass(senderInteraction);
  sender.rtiAmbassador().changeInteractionOrderType(senderInteraction, rti::TIMESTAMP);
  constrainedRegulator.rtiAmbassador().subscribeInteractionClass(interaction, true);

  constrainedRegulator.rtiAmbassador().enableTimeConstrained();
  waitFor(
      constrainedRegulator,
      [&] { return constrainedRegulator.recorder().timeConstrainedEnabled().size() == 1U; },
      options,
      "FQR timed-save constrained-role callback");
  constrainedRegulator.rtiAmbassador().enableTimeRegulation(*actorTime.epsilon);
  waitFor(
      constrainedRegulator,
      [&] { return constrainedRegulator.recorder().timeRegulationEnabled().size() == 1U; },
      options,
      "FQR timed-save regulating-role callback");
  sender.rtiAmbassador().enableTimeRegulation(*senderTime.epsilon);
  waitFor(
      sender,
      [&] { return sender.recorder().timeRegulationEnabled().size() == 1U; },
      options,
      "FQR timed-save sender regulating-role callback");

  auto const initialAdvance = timeAfter(
      *actorTime.factory, *actorTime.initial, *actorTime.epsilon, 4U);
  constrainedRegulator.rtiAmbassador().timeAdvanceRequest(*initialAdvance);
  sender.rtiAmbassador().timeAdvanceRequest(*initialAdvance);
  waitForSessions(
      {&constrainedRegulator, &sender},
      [&] {
        return constrainedRegulator.recorder().timeAdvanceGrants().size() == 1U &&
            sender.recorder().timeAdvanceGrants().size() == 1U;
      },
      options,
      "FQR timed-save initial grants");
  auto const queuedTime = timeAfter(
      *senderTime.factory, *senderTime.initial, *senderTime.epsilon, 7U);
  auto const flushTime = timeAfter(
      *actorTime.factory, *actorTime.initial, *actorTime.epsilon, 10U);
  auto const saveTime = timeAfter(
      *actorTime.factory, *actorTime.initial, *actorTime.epsilon, 6U);
  auto const laterAdvance = timeAfter(
      *actorTime.factory, *actorTime.initial, *actorTime.epsilon, 7U);
  std::vector<std::uint8_t> payloadBytes{0x46U, 0x51U, 0x52U};
  std::vector<std::uint8_t> tagBytes{0x53U, 0x41U, 0x56U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      senderParameter,
      rti::VariableLengthData(payloadBytes.data(), payloadBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
  rti::MessageRetractionHandle retraction;
  try {
    retraction = sender.rtiAmbassador().sendInteraction(
        senderInteraction, parameters, tag, *queuedTime);
  } catch (rti::Exception const& error) {
    auto const message = error.what();
    throw std::runtime_error(
        std::string("FQR timed-save sendInteraction failed: ") +
        std::string(message.begin(), message.end()));
  }
  require(retraction.isValid(), "FQR timed-save queued interaction has no retraction handle");

  std::wstring const saveLabel = L"tck-fqr-timed-save-callback";
  try {
    constrainedRegulator.rtiAmbassador().requestFederationSave(saveLabel, *saveTime);
  } catch (rti::Exception const& error) {
    auto const message = error.what();
    throw std::runtime_error(
        std::string("FQR timed-save requestFederationSave failed: ") +
        std::string(message.begin(), message.end()));
  }

  try {
    constrainedRegulator.rtiAmbassador().flushQueueRequest(*flushTime);
  } catch (rti::Exception const& error) {
    auto const message = error.what();
    throw std::runtime_error(
        std::string("FQR timed-save flushQueueRequest failed: ") +
        std::string(message.begin(), message.end()));
  }
  waitFor(
      constrainedRegulator,
      [&] {
        return constrainedRegulator.recorder().timedInteractions().size() == 1U &&
            constrainedRegulator.recorder().flushQueueGrants().size() == 1U;
      },
      options,
      "FQR timed-save queued delivery and grant");
  auto const flushGrants = constrainedRegulator.recorder().flushQueueGrants();
  require(
      flushGrants.front().time == encodeTime(*timeAfter(
          *actorTime.factory, *actorTime.initial, *actorTime.epsilon, 5U)) &&
          flushGrants.front().optimisticTime == encodeTime(*queuedTime),
      "FQR timed-save did not retain distinct actual and optimistic grant times");
  auto logicalTime = actorTime.factory->makeInitial();
  constrainedRegulator.rtiAmbassador().queryLogicalTime(*logicalTime);
  requireTimeEquals(*logicalTime, *timeAfter(
      *actorTime.factory, *actorTime.initial, *actorTime.epsilon, 5U),
      "FQR timed-save logical-time query");

  constrainedRegulator.recorder().clearCallbackOrder();
  try {
    constrainedRegulator.rtiAmbassador().timeAdvanceRequest(*laterAdvance);
    sender.rtiAmbassador().timeAdvanceRequest(*laterAdvance);
  } catch (rti::Exception const& error) {
    auto const message = error.what();
    throw std::runtime_error(
        std::string("FQR timed-save post-flush TAR failed: ") +
        std::string(message.begin(), message.end()));
  }
  waitForSessions(
      {&constrainedRegulator, &sender},
      [&] {
        return constrainedRegulator.federateSaveTimes().size() == 1U &&
            sender.federateSaveTimes().size() == 1U;
      },
      options,
      "FQR timed-save initiation callbacks");
  auto const actorSaveTimes = constrainedRegulator.federateSaveTimes();
  auto const senderSaveTimes = sender.federateSaveTimes();
  require(
      actorSaveTimes.front().encoded == encodeTime(*saveTime) &&
          senderSaveTimes.front().encoded == encodeTime(*saveTime) &&
          constrainedRegulator.federateSaveInitiations().front() == saveLabel &&
          sender.federateSaveInitiations().front() == saveLabel,
      "FQR timed-save callback returned the wrong label or timestamp");
  constrainedRegulator.rtiAmbassador().federateSaveBegun();
  sender.rtiAmbassador().federateSaveBegun();
  constrainedRegulator.rtiAmbassador().federateSaveComplete();
  sender.rtiAmbassador().federateSaveComplete();
  waitForSessions(
      {&constrainedRegulator, &sender},
      [&] {
        return constrainedRegulator.federationSavedCount() == 1U &&
            sender.federationSavedCount() == 1U &&
            constrainedRegulator.recorder().timeAdvanceGrants().size() == 2U &&
            sender.recorder().timeAdvanceGrants().size() == 2U;
      },
      options,
      "FQR timed federation saved callbacks");
  require(
      constrainedRegulator.federationNotSavedReasons().empty() &&
          sender.federationNotSavedReasons().empty(),
      "FQR timed federation save unexpectedly failed");
  auto const callbackOrder = constrainedRegulator.recorder().callbackOrder();
  auto const saveCallback = std::find(
      callbackOrder.begin(), callbackOrder.end(), "federate-save-initiate");
  auto const grantCallback = std::find(callbackOrder.begin(), callbackOrder.end(), "grant");
  require(
      saveCallback != callbackOrder.end() && grantCallback != callbackOrder.end() &&
          saveCallback < grantCallback,
      "FQR timed-save initiation did not precede the constrained federate's later grant");

  constrainedRegulator.rtiAmbassador().disableTimeConstrained();
  constrainedRegulator.rtiAmbassador().disableTimeRegulation();
  sender.rtiAmbassador().disableTimeRegulation();
  constrainedRegulator.rtiAmbassador().unsubscribeInteractionClass(interaction);
  sender.rtiAmbassador().unpublishInteractionClass(senderInteraction);
  sender.resign(rti::NO_ACTION);
  constrainedRegulator.resign(rti::NO_ACTION);
  constrainedRegulator.rtiAmbassador().destroyFederationExecution(federation);
  sender.disconnect();
  constrainedRegulator.disconnect();
}

void scenarioTimedFederationSaveRestore(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timed federation save/restore requires an adapter-supplied logical-time implementation");

  Session regulator(options, model, "owner");
  Session constrained(options, model, "member");
  auto const federation = federationName(options, "timed-federation-save-restore");
  connectAndJoin(regulator, constrained, options, federation, options.fom);

  auto regulatorTime = makeTimeContext(regulator);
  auto constrainedTime = makeTimeContext(constrained);
  enableTimestampedRoles(
      regulator,
      constrained,
      regulatorTime,
      constrainedTime,
      options,
      "timed federation save/restore");

  rti::ObjectClassHandle regulatorClass;
  rti::AttributeHandle regulatorAttribute;
  rti::InteractionClassHandle regulatorInteraction;
  rti::ParameterHandle regulatorParameter;
  handles(
      regulator,
      options,
      regulatorClass,
      regulatorAttribute,
      regulatorInteraction,
      regulatorParameter);
  auto const constrainedInteraction = constrained.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const constrainedParameter = constrained.rtiAmbassador().getParameterHandle(
      constrainedInteraction,
      options.parameterName);
  require(
      constrainedInteraction.isValid() && constrainedParameter.isValid(),
      "Timed federation save/restore constrained interaction lookup returned an invalid handle");

  regulator.rtiAmbassador().publishInteractionClass(regulatorInteraction);
  constrained.rtiAmbassador().subscribeInteractionClass(constrainedInteraction, true);
  regulator.rtiAmbassador().changeInteractionOrderType(
      regulatorInteraction,
      rti::TIMESTAMP);

  std::vector<std::uint8_t> payloadBytes{0x54U, 0x53U, 0x4FU};
  std::vector<std::uint8_t> tagBytes{0x53U, 0x41U, 0x56U, 0x45U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      regulatorParameter,
      rti::VariableLengthData(payloadBytes.data(), payloadBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());

  auto const saveTime = timeAfter(
      *regulatorTime.factory,
      *regulatorTime.initial,
      *regulatorTime.epsilon,
      2U);
  auto const queuedTime = timeAfter(
      *regulatorTime.factory,
      *regulatorTime.initial,
      *regulatorTime.epsilon,
      4U);
  auto const releaseTime = timeAfter(
      *regulatorTime.factory,
      *regulatorTime.initial,
      *regulatorTime.epsilon,
      6U);
  auto const retraction = regulator.rtiAmbassador().sendInteraction(
      regulatorInteraction,
      parameters,
      tag,
      *queuedTime);
  require(
      retraction.isValid(),
      "Timed federation save/restore returned an invalid message retraction handle");

  std::wstring const saveLabel = L"tck-timed-save-restore";
  regulator.rtiAmbassador().requestFederationSave(saveLabel, *saveTime);
  constrained.rtiAmbassador().timeAdvanceRequest(*saveTime);
  regulator.rtiAmbassador().timeAdvanceRequest(*saveTime);
  waitForSessions(
      {&regulator, &constrained},
      [&] {
        return regulator.federateSaveTimes().size() >= 1U &&
            constrained.federateSaveTimes().size() >= 1U;
      },
      options,
      "timed federate save initiation callbacks");
  auto const regulatorSaveTimes = regulator.federateSaveTimes();
  auto const constrainedSaveTimes = constrained.federateSaveTimes();
  require(
      regulatorSaveTimes.front().encoded == encodeTime(*saveTime) &&
          constrainedSaveTimes.front().encoded == encodeTime(*saveTime),
      "timed federate save initiation returned the wrong timestamp");
  require(
      regulator.federateSaveInitiations().front() == saveLabel &&
          constrained.federateSaveInitiations().front() == saveLabel,
      "timed federate save initiation returned the wrong label");

  regulator.rtiAmbassador().federateSaveBegun();
  constrained.rtiAmbassador().federateSaveBegun();
  regulator.rtiAmbassador().federateSaveComplete();
  constrained.rtiAmbassador().federateSaveComplete();
  waitForSessions(
      {&regulator, &constrained},
      [&] {
        return regulator.federationSavedCount() >= 1U &&
            constrained.federationSavedCount() >= 1U;
      },
      options,
      "timed federation saved callbacks");
  require(
      regulator.federationNotSavedReasons().empty() &&
          constrained.federationNotSavedReasons().empty(),
      "successful timed federation save reported a failure");

  regulator.rtiAmbassador().requestFederationRestore(saveLabel);
  waitForSessions(
      {&regulator, &constrained},
      [&] {
        return regulator.federationRestoreRequestsSucceeded().size() >= 1U &&
            regulator.federationRestoreBegunCount() >= 1U &&
            constrained.federationRestoreBegunCount() >= 1U &&
            regulator.federateRestoreInitiations().size() >= 1U &&
            constrained.federateRestoreInitiations().size() >= 1U;
      },
      options,
      "timed federation restore initiation callbacks");
  require(
      regulator.federationRestoreRequestsSucceeded().back() == saveLabel &&
          regulator.federationRestoreRequestsFailed().empty() &&
          constrained.federationRestoreRequestsFailed().empty(),
      "timed federation restore request returned an unexpected result");
  auto const regulatorRestore = regulator.federateRestoreInitiations().back();
  auto const constrainedRestore = constrained.federateRestoreInitiations().back();
  require(
      regulatorRestore.label == saveLabel && constrainedRestore.label == saveLabel &&
          regulatorRestore.federateName == options.ownerFederateName &&
          constrainedRestore.federateName == options.memberFederateName &&
          regulatorRestore.postRestoreFederateHandle.isValid() &&
          constrainedRestore.postRestoreFederateHandle.isValid(),
      "timed federation restore initiation returned incorrect identity data");

  regulator.rtiAmbassador().federateRestoreComplete();
  constrained.rtiAmbassador().federateRestoreComplete();
  waitForSessions(
      {&regulator, &constrained},
      [&] {
        return regulator.federationRestoredCount() >= 1U &&
            constrained.federationRestoredCount() >= 1U;
      },
      options,
      "timed federation restored callbacks");
  require(
      regulator.federationNotRestoredReasons().empty() &&
          constrained.federationNotRestoredReasons().empty(),
      "successful timed federation restore reported a failure");
  require(
      regulator.rtiAmbassador().getFederateHandle(options.ownerFederateName) ==
              regulatorRestore.postRestoreFederateHandle &&
          constrained.rtiAmbassador().getFederateHandle(options.memberFederateName) ==
              constrainedRestore.postRestoreFederateHandle,
      "timed federation restore did not rebind federate handles");

  constrained.recorder().clearTimedInteractions();
  constrained.recorder().clearFlushQueueGrants();
  constrained.recorder().clearCallbackOrder();
  constrained.recorder().clearRetractions();
  constrained.rtiAmbassador().flushQueueRequest(*releaseTime);
  waitFor(
      constrained,
      [&] {
        return constrained.recorder().timedInteractions().size() >= 1U &&
            constrained.recorder().flushQueueGrants().size() >= 1U;
      },
      options,
      "restored timestamped interaction and Flush Queue grant");
  auto const restoredInteractions = constrained.recorder().timedInteractions();
  require(
      restoredInteractions.size() == 1U,
      "timed federation restore delivered an unexpected number of interactions");
  auto const& restoredInteraction = restoredInteractions.front();
  require(
      restoredInteraction.interaction == constrainedInteraction &&
          restoredInteraction.parameters.size() == 1U &&
          restoredInteraction.parameters.count(constrainedParameter) == 1U &&
          copyBytes(restoredInteraction.parameters.at(constrainedParameter)) == payloadBytes &&
          restoredInteraction.tag == tagBytes &&
          restoredInteraction.producer == regulatorRestore.postRestoreFederateHandle &&
          restoredInteraction.time == encodeTime(*queuedTime) &&
          restoredInteraction.sentOrder == rti::TIMESTAMP &&
          restoredInteraction.receivedOrder == rti::TIMESTAMP &&
          restoredInteraction.retractionPresent,
      "restored timestamped interaction changed its public delivery data");
  auto const callbackOrder = constrained.recorder().callbackOrder();
  auto const interactionCallback = std::find(
      callbackOrder.begin(), callbackOrder.end(), "interaction");
  auto const grantCallback = std::find(
      callbackOrder.begin(), callbackOrder.end(), "flush-grant");
  require(
      interactionCallback != callbackOrder.end() && grantCallback != callbackOrder.end() &&
          interactionCallback < grantCallback,
      "restored timestamped interaction was not delivered before its Flush Queue grant");

  regulator.rtiAmbassador().retract(retraction);
  waitFor(
      constrained,
      [&] { return constrained.recorder().retractions().size() >= 1U; },
      options,
      "restored message retraction callback");
  auto const retractions = constrained.recorder().retractions();
  require(
      retractions.front().valid &&
          retractions.front().encoded == copyBytes(retraction.encode()),
      "restored message retraction returned the wrong handle");
  requireException(
      [&] { regulator.rtiAmbassador().retract(retraction); },
      L"MessageCanNoLongerBeRetracted",
      "second retraction of the restored message");

  constrained.rtiAmbassador().disableTimeConstrained();
  regulator.rtiAmbassador().disableTimeRegulation();
  constrained.rtiAmbassador().unsubscribeInteractionClass(constrainedInteraction);
  regulator.rtiAmbassador().unpublishInteractionClass(regulatorInteraction);
  constrained.resign(rti::NO_ACTION);
  regulator.resign(rti::NO_ACTION);
  regulator.rtiAmbassador().destroyFederationExecution(federation);
  constrained.disconnect();
  regulator.disconnect();
}

void scenarioTimedRegionalInteractionSaveRestore(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Timed regional interaction save/restore requires an adapter-supplied dimensional FOM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timed regional interaction save/restore requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session receiver(options, model, "member");
  auto const federation = federationName(
      options,
      "timed-regional-interaction-save-restore");
  connectAndJoin(publisher, receiver, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const receiverHandles = ddmHandles(receiver, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "timed regional interaction save/restore");
  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherHandles.interactionClass,
      rti::TIMESTAMP);

  auto const sourceRegion = createDdmRegion(
      publisher,
      publisherHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  auto const receiverRegion = createDdmRegion(
      receiver,
      receiverHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const sourceRegionSet = rti::RegionHandleSet{sourceRegion};
  auto const receiverRegionSet = rti::RegionHandleSet{receiverRegion};
  receiver.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  require(
      receiver.rtiAmbassador().getConveyRegionDesignatorSetsSwitch(),
      "timed regional interaction save/restore did not enable region designator callbacks");
  receiver.rtiAmbassador().subscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSet,
      true);

  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  enableTimestampedRoles(
      publisher,
      receiver,
      publisherTime,
      receiverTime,
      options,
      "timed regional interaction save/restore");

  std::vector<std::uint8_t> const parameterBytes{
      0x54U, 0x49U, 0x4DU, 0x45U};
  std::vector<std::uint8_t> const tagBytes{0x52U, 0x45U, 0x47U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());

  auto const saveTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      6U);
  auto const queuedTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      8U);
  auto const releaseTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      10U);
  auto const retraction = publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      sourceRegionSet,
      tag,
      *queuedTime);
  require(
      retraction.isValid(),
      "timed regional interaction save/restore returned an invalid retraction handle");
  require(
      receiver.recorder().timedInteractions().empty(),
      "timed regional interaction save/restore delivered before the save frontier");

  std::wstring const saveLabel = L"tck-timed-regional-interaction-save-restore";
  publisher.rtiAmbassador().requestFederationSave(saveLabel, *saveTime);
  receiver.rtiAmbassador().timeAdvanceRequest(*saveTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*saveTime);
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.federateSaveTimes().size() >= 1U &&
            receiver.federateSaveTimes().size() >= 1U;
      },
      options,
      "timed regional interaction save initiation callbacks");
  require(
      publisher.federateSaveTimes().front().encoded == encodeTime(*saveTime) &&
          receiver.federateSaveTimes().front().encoded == encodeTime(*saveTime),
      "timed regional interaction save initiation returned the wrong timestamp");

  publisher.rtiAmbassador().federateSaveBegun();
  receiver.rtiAmbassador().federateSaveBegun();
  publisher.rtiAmbassador().federateSaveComplete();
  receiver.rtiAmbassador().federateSaveComplete();
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.federationSavedCount() >= 1U &&
            receiver.federationSavedCount() >= 1U;
      },
      options,
      "timed regional interaction saved callbacks");
  require(
      publisher.federationNotSavedReasons().empty() &&
          receiver.federationNotSavedReasons().empty(),
      "timed regional interaction save reported a failure");

  // Cancel the queued message in the live execution. Restore must roll back
  // to the saved state and make the same public retraction handle deliverable.
  publisher.rtiAmbassador().retract(retraction);
  publisher.recorder().clearCallbackOrder();
  receiver.recorder().clearTimedInteractions();
  receiver.recorder().clearFlushQueueGrants();
  receiver.recorder().clearRetractions();
  receiver.recorder().clearCallbackOrder();

  publisher.rtiAmbassador().requestFederationRestore(saveLabel);
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.federationRestoreRequestsSucceeded().size() >= 1U &&
            publisher.federationRestoreBegunCount() >= 1U &&
            receiver.federationRestoreBegunCount() >= 1U &&
            publisher.federateRestoreInitiations().size() >= 1U &&
            receiver.federateRestoreInitiations().size() >= 1U;
      },
      options,
      "timed regional interaction restore initiation callbacks");
  require(
      publisher.federationRestoreRequestsSucceeded().back() == saveLabel &&
          publisher.federationRestoreRequestsFailed().empty() &&
          receiver.federationRestoreRequestsFailed().empty(),
      "timed regional interaction restore request returned an unexpected result");
  auto const publisherRestore = publisher.federateRestoreInitiations().back();
  auto const receiverRestore = receiver.federateRestoreInitiations().back();
  require(
      publisherRestore.label == saveLabel && receiverRestore.label == saveLabel &&
          publisherRestore.postRestoreFederateHandle.isValid() &&
          receiverRestore.postRestoreFederateHandle.isValid(),
      "timed regional interaction restore returned invalid identity data");

  publisher.rtiAmbassador().federateRestoreComplete();
  receiver.rtiAmbassador().federateRestoreComplete();
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.federationRestoredCount() >= 1U &&
            receiver.federationRestoredCount() >= 1U;
      },
      options,
      "timed regional interaction restored callbacks");
  require(
      publisher.federationNotRestoredReasons().empty() &&
          receiver.federationNotRestoredReasons().empty(),
      "timed regional interaction restore reported a failure");

  receiver.rtiAmbassador().flushQueueRequest(*releaseTime);
  waitFor(
      receiver,
      [&] {
        return receiver.recorder().timedInteractions().size() >= 1U &&
            receiver.recorder().flushQueueGrants().size() >= 1U;
      },
      options,
      "restored regional interaction and Flush Queue grant");
  auto const interactions = receiver.recorder().timedInteractions();
  require(
      interactions.size() == 1U,
      "timed regional interaction restore delivered an unexpected interaction count");
  auto const& interaction = interactions.front();
  require(
      interaction.interaction == receiverHandles.interactionClass &&
          interaction.parameters.size() == 1U &&
          interaction.parameters.count(receiverHandles.parameter) == 1U &&
          copyBytes(interaction.parameters.at(receiverHandles.parameter)) == parameterBytes &&
          interaction.tag == tagBytes &&
          interaction.producer == publisherRestore.postRestoreFederateHandle &&
          interaction.time == encodeTime(*queuedTime) &&
          interaction.sentOrder == rti::TIMESTAMP &&
          interaction.receivedOrder == rti::TIMESTAMP &&
          interaction.retractionPresent &&
          interaction.retraction == copyBytes(retraction.encode()) &&
          interaction.regions.has_value() && interaction.regions->size() == 1U &&
          interaction.regions->count(sourceRegion) == 1U,
      "timed regional interaction restore changed its public delivery data");
  auto const callbackOrder = receiver.recorder().callbackOrder();
  auto const interactionCallback = std::find(
      callbackOrder.begin(), callbackOrder.end(), "interaction");
  auto const grantCallback = std::find(
      callbackOrder.begin(), callbackOrder.end(), "flush-grant");
  require(
      interactionCallback != callbackOrder.end() && grantCallback != callbackOrder.end() &&
          interactionCallback < grantCallback,
      "restored regional interaction was not delivered before its Flush Queue grant");

  publisher.rtiAmbassador().retract(retraction);
  waitFor(
      receiver,
      [&] { return receiver.recorder().retractions().size() >= 1U; },
      options,
      "restored regional interaction retraction callback");
  require(
      receiver.recorder().retractions().front().valid &&
          receiver.recorder().retractions().front().encoded == copyBytes(retraction.encode()),
      "restored regional interaction retraction returned the wrong handle");
  requireException(
      [&] { publisher.rtiAmbassador().retract(retraction); },
      L"MessageCanNoLongerBeRetracted",
      "second retraction of restored regional interaction");

  receiver.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSet);
  receiver.rtiAmbassador().deleteRegion(receiverRegion);
  publisher.rtiAmbassador().deleteRegion(sourceRegion);
  receiver.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

void scenarioTimedDefaultRegionInteractionSaveRestore(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Timed default-region interaction save/restore requires an adapter-supplied dimensional FOM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timed default-region interaction save/restore requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session receiver(options, model, "member");
  auto const federation = federationName(
      options,
      "timed-default-region-interaction-save-restore");
  connectAndJoin(publisher, receiver, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const receiverHandles = ddmHandles(receiver, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "timed default-region interaction save/restore");
  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherHandles.interactionClass,
      rti::TIMESTAMP);

  auto const receiverRegion = createDdmRegion(
      receiver,
      receiverHandles,
      8UL,
      9UL,
      8UL,
      9UL);
  auto const receiverRegionSet = rti::RegionHandleSet{receiverRegion};
  receiver.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  require(
      receiver.rtiAmbassador().getConveyRegionDesignatorSetsSwitch(),
      "timed default-region interaction save/restore did not enable region designator callbacks");
  receiver.rtiAmbassador().subscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSet,
      true);

  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  enableTimestampedRoles(
      publisher,
      receiver,
      publisherTime,
      receiverTime,
      options,
      "timed default-region interaction save/restore");

  std::vector<std::uint8_t> const parameterBytes{
      0x54U, 0x49U, 0x4DU, 0x45U, 0x44U};
  std::vector<std::uint8_t> const tagBytes{
      0x44U, 0x45U, 0x46U, 0x2DU, 0x54U, 0x53U, 0x4FU};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());

  auto const saveTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      6U);
  auto const queuedTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      8U);
  auto const releaseTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      10U);
  auto const retraction = publisher.rtiAmbassador().sendInteraction(
      publisherHandles.interactionClass,
      parameters,
      tag,
      *queuedTime);
  require(
      retraction.isValid(),
      "timed default-region interaction save/restore returned an invalid retraction handle");
  require(
      receiver.recorder().timedInteractions().empty(),
      "timed default-region interaction save/restore delivered before the save frontier");

  std::wstring const saveLabel = L"tck-timed-default-region-interaction-save-restore";
  publisher.rtiAmbassador().requestFederationSave(saveLabel, *saveTime);
  receiver.rtiAmbassador().timeAdvanceRequest(*saveTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*saveTime);
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.federateSaveTimes().size() >= 1U &&
            receiver.federateSaveTimes().size() >= 1U;
      },
      options,
      "timed default-region interaction save initiation callbacks");
  require(
      publisher.federateSaveTimes().front().encoded == encodeTime(*saveTime) &&
          receiver.federateSaveTimes().front().encoded == encodeTime(*saveTime),
      "timed default-region interaction save initiation returned the wrong timestamp");

  publisher.rtiAmbassador().federateSaveBegun();
  receiver.rtiAmbassador().federateSaveBegun();
  publisher.rtiAmbassador().federateSaveComplete();
  receiver.rtiAmbassador().federateSaveComplete();
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.federationSavedCount() >= 1U &&
            receiver.federationSavedCount() >= 1U;
      },
      options,
      "timed default-region interaction saved callbacks");
  require(
      publisher.federationNotSavedReasons().empty() &&
          receiver.federationNotSavedReasons().empty(),
      "timed default-region interaction save reported a failure");

  // Remove the live message after the save. Restore must reconstruct the
  // default-source queue entry and its public retraction handle.
  publisher.rtiAmbassador().retract(retraction);
  publisher.recorder().clearCallbackOrder();
  receiver.recorder().clearTimedInteractions();
  receiver.recorder().clearFlushQueueGrants();
  receiver.recorder().clearRetractions();
  receiver.recorder().clearCallbackOrder();

  publisher.rtiAmbassador().requestFederationRestore(saveLabel);
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.federationRestoreRequestsSucceeded().size() >= 1U &&
            publisher.federationRestoreBegunCount() >= 1U &&
            receiver.federationRestoreBegunCount() >= 1U &&
            publisher.federateRestoreInitiations().size() >= 1U &&
            receiver.federateRestoreInitiations().size() >= 1U;
      },
      options,
      "timed default-region interaction restore initiation callbacks");
  require(
      publisher.federationRestoreRequestsSucceeded().back() == saveLabel &&
          publisher.federationRestoreRequestsFailed().empty() &&
          receiver.federationRestoreRequestsFailed().empty(),
      "timed default-region interaction restore request returned an unexpected result");
  auto const publisherRestore = publisher.federateRestoreInitiations().back();
  auto const receiverRestore = receiver.federateRestoreInitiations().back();
  require(
      publisherRestore.label == saveLabel && receiverRestore.label == saveLabel &&
          publisherRestore.postRestoreFederateHandle.isValid() &&
          receiverRestore.postRestoreFederateHandle.isValid(),
      "timed default-region interaction restore returned invalid identity data");

  publisher.rtiAmbassador().federateRestoreComplete();
  receiver.rtiAmbassador().federateRestoreComplete();
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.federationRestoredCount() >= 1U &&
            receiver.federationRestoredCount() >= 1U;
      },
      options,
      "timed default-region interaction restored callbacks");
  require(
      publisher.federationNotRestoredReasons().empty() &&
          receiver.federationNotRestoredReasons().empty(),
      "timed default-region interaction restore reported a failure");

  receiver.rtiAmbassador().flushQueueRequest(*releaseTime);
  waitFor(
      receiver,
      [&] {
        return receiver.recorder().timedInteractions().size() >= 1U &&
            receiver.recorder().flushQueueGrants().size() >= 1U;
      },
      options,
      "restored default-region interaction and Flush Queue grant");
  auto const interactions = receiver.recorder().timedInteractions();
  require(
      interactions.size() == 1U,
      "timed default-region interaction restore delivered an unexpected interaction count");
  auto const& interaction = interactions.front();
  require(
      interaction.interaction == receiverHandles.interactionClass &&
          interaction.parameters.size() == 1U &&
          interaction.parameters.count(receiverHandles.parameter) == 1U &&
          copyBytes(interaction.parameters.at(receiverHandles.parameter)) == parameterBytes &&
          interaction.tag == tagBytes &&
          interaction.producer == publisherRestore.postRestoreFederateHandle &&
          interaction.time == encodeTime(*queuedTime) &&
          interaction.sentOrder == rti::TIMESTAMP &&
          interaction.receivedOrder == rti::TIMESTAMP &&
          interaction.retractionPresent &&
          interaction.retraction == copyBytes(retraction.encode()) &&
          interaction.regions.has_value() && interaction.regions->empty(),
      "timed default-region interaction restore changed its public delivery data");
  auto const callbackOrder = receiver.recorder().callbackOrder();
  auto const interactionCallback = std::find(
      callbackOrder.begin(), callbackOrder.end(), "interaction");
  auto const grantCallback = std::find(
      callbackOrder.begin(), callbackOrder.end(), "flush-grant");
  require(
      interactionCallback != callbackOrder.end() && grantCallback != callbackOrder.end() &&
          interactionCallback < grantCallback,
      "restored default-region interaction was not delivered before its Flush Queue grant");

  publisher.rtiAmbassador().retract(retraction);
  waitFor(
      receiver,
      [&] { return receiver.recorder().retractions().size() >= 1U; },
      options,
      "restored default-region interaction retraction callback");
  require(
      receiver.recorder().retractions().front().valid &&
          receiver.recorder().retractions().front().encoded == copyBytes(retraction.encode()),
      "restored default-region interaction retraction returned the wrong handle");
  requireException(
      [&] { publisher.rtiAmbassador().retract(retraction); },
      L"MessageCanNoLongerBeRetracted",
      "second retraction of restored default-region interaction");

  receiver.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSet);
  receiver.rtiAmbassador().deleteRegion(receiverRegion);
  receiver.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

void scenarioTimedDefaultRegionAttributeSaveRestore(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Timed default-region attribute save/restore requires an adapter-supplied dimensional FOM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timed default-region attribute save/restore requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session receiver(options, model, "member");
  auto const federation = federationName(
      options,
      "timed-default-region-attribute-save-restore");
  connectAndJoin(publisher, receiver, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const receiverHandles = ddmHandles(receiver, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "timed default-region attribute save/restore");
  rti::AttributeHandleSet const publisherAttributes{publisherHandles.attribute};
  rti::AttributeHandleSet const receiverAttributes{receiverHandles.attribute};
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherHandles.objectClass,
      publisherAttributes);
  publisher.rtiAmbassador().changeDefaultAttributeOrderType(
      publisherHandles.objectClass,
      publisherAttributes,
      rti::TIMESTAMP);

  auto const receiverRegion = createDdmRegion(
      receiver,
      receiverHandles,
      2UL,
      3UL,
      2UL,
      3UL);
  auto const receiverRegionSet = rti::RegionHandleSet{receiverRegion};
  rti::AttributeHandleSetRegionHandleSetPairVector const receiverPair{{
      receiverAttributes,
      receiverRegionSet,
  }};
  receiver.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  require(
      receiver.rtiAmbassador().getConveyRegionDesignatorSetsSwitch(),
      "timed default-region attribute save/restore did not enable region designator callbacks");
  receiver.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      receiverHandles.objectClass,
      receiverPair,
      true,
      L"");

  auto const object = publisher.rtiAmbassador().registerObjectInstance(
      publisherHandles.objectClass);
  require(
      object.isValid(),
      "timed default-region attribute save/restore returned an invalid object handle");
  waitFor(
      receiver,
      [&] { return receiver.recorder().hasDiscovery(object); },
      options,
      "timed default-region attribute save/restore object discovery");

  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  enableTimestampedRoles(
      publisher,
      receiver,
      publisherTime,
      receiverTime,
      options,
      "timed default-region attribute save/restore");

  std::vector<std::uint8_t> const valueBytes{
      0x55U, 0x4EU, 0x54U, 0x2DU, 0x41U, 0x54U, 0x54U};
  std::vector<std::uint8_t> const tagBytes{
      0x55U, 0x4EU, 0x54U, 0x2DU, 0x54U, 0x53U, 0x4FU};
  rti::AttributeHandleValueMap values;
  values.emplace(
      publisherHandles.attribute,
      rti::VariableLengthData(valueBytes.data(), valueBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());

  auto const saveTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      5U);
  auto const queuedTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      7U);
  auto const releaseTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      10U);
  auto const retraction = publisher.rtiAmbassador().updateAttributeValues(
      object,
      values,
      tag,
      *queuedTime);
  require(
      retraction.isValid(),
      "timed default-region attribute save/restore returned an invalid retraction handle");
  require(
      receiver.recorder().timedReflections().empty(),
      "timed default-region attribute save/restore delivered before the save frontier");

  std::wstring const saveLabel = L"tck-timed-default-region-attribute-save-restore";
  publisher.rtiAmbassador().requestFederationSave(saveLabel, *saveTime);
  receiver.rtiAmbassador().timeAdvanceRequest(*saveTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*saveTime);
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.federateSaveTimes().size() >= 1U &&
            receiver.federateSaveTimes().size() >= 1U;
      },
      options,
      "timed default-region attribute save initiation callbacks");
  require(
      publisher.federateSaveTimes().front().encoded == encodeTime(*saveTime) &&
          receiver.federateSaveTimes().front().encoded == encodeTime(*saveTime),
      "timed default-region attribute save initiation returned the wrong timestamp");

  publisher.rtiAmbassador().federateSaveBegun();
  receiver.rtiAmbassador().federateSaveBegun();
  publisher.rtiAmbassador().federateSaveComplete();
  receiver.rtiAmbassador().federateSaveComplete();
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.federationSavedCount() >= 1U &&
            receiver.federationSavedCount() >= 1U;
      },
      options,
      "timed default-region attribute saved callbacks");
  require(
      publisher.federationNotSavedReasons().empty() &&
          receiver.federationNotSavedReasons().empty(),
      "timed default-region attribute save reported a failure");

  // Terminalize the live passel after the save. Restore must reconstitute the
  // queued default-source reflection and the same public retraction handle.
  publisher.rtiAmbassador().retract(retraction);
  publisher.recorder().clearCallbackOrder();
  receiver.recorder().clearTimedReflections();
  receiver.recorder().clearFlushQueueGrants();
  receiver.recorder().clearRetractions();
  receiver.recorder().clearCallbackOrder();

  publisher.rtiAmbassador().requestFederationRestore(saveLabel);
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.federationRestoreRequestsSucceeded().size() >= 1U &&
            publisher.federationRestoreBegunCount() >= 1U &&
            receiver.federationRestoreBegunCount() >= 1U &&
            publisher.federateRestoreInitiations().size() >= 1U &&
            receiver.federateRestoreInitiations().size() >= 1U;
      },
      options,
      "timed default-region attribute restore initiation callbacks");
  require(
      publisher.federationRestoreRequestsSucceeded().back() == saveLabel &&
          publisher.federationRestoreRequestsFailed().empty() &&
          receiver.federationRestoreRequestsFailed().empty(),
      "timed default-region attribute restore request returned an unexpected result");
  auto const publisherRestore = publisher.federateRestoreInitiations().back();
  auto const receiverRestore = receiver.federateRestoreInitiations().back();
  require(
      publisherRestore.label == saveLabel && receiverRestore.label == saveLabel &&
          publisherRestore.postRestoreFederateHandle.isValid() &&
          receiverRestore.postRestoreFederateHandle.isValid(),
      "timed default-region attribute restore returned invalid identity data");

  publisher.rtiAmbassador().federateRestoreComplete();
  receiver.rtiAmbassador().federateRestoreComplete();
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.federationRestoredCount() >= 1U &&
            receiver.federationRestoredCount() >= 1U;
      },
      options,
      "timed default-region attribute restored callbacks");
  require(
      publisher.federationNotRestoredReasons().empty() &&
          receiver.federationNotRestoredReasons().empty(),
      "timed default-region attribute restore reported a failure");

  receiver.rtiAmbassador().flushQueueRequest(*releaseTime);
  waitFor(
      receiver,
      [&] {
        return receiver.recorder().timedReflections().size() >= 1U &&
            receiver.recorder().flushQueueGrants().size() >= 1U;
      },
      options,
      "restored default-region attribute and Flush Queue grant");
  auto const reflections = receiver.recorder().timedReflections();
  require(
      reflections.size() == 1U,
      "timed default-region attribute restore delivered an unexpected reflection count");
  auto const& reflection = reflections.front();
  require(
      reflection.object == object &&
          reflection.values.size() == 1U &&
          reflection.values.count(receiverHandles.attribute) == 1U &&
          copyBytes(reflection.values.at(receiverHandles.attribute)) == valueBytes &&
          reflection.tag == tagBytes &&
          reflection.producer == publisherRestore.postRestoreFederateHandle &&
          reflection.time == encodeTime(*queuedTime) &&
          reflection.sentOrder == rti::TIMESTAMP &&
          reflection.receivedOrder == rti::TIMESTAMP &&
          reflection.retractionPresent &&
          reflection.retraction == copyBytes(retraction.encode()) &&
          reflection.regions.has_value() && reflection.regions->empty(),
      "timed default-region attribute restore changed its public delivery data");
  auto const callbackOrder = receiver.recorder().callbackOrder();
  auto const reflectionCallback = std::find(
      callbackOrder.begin(),
      callbackOrder.end(),
      "reflect");
  auto const grantCallback = std::find(
      callbackOrder.begin(),
      callbackOrder.end(),
      "flush-grant");
  require(
      reflectionCallback != callbackOrder.end() && grantCallback != callbackOrder.end() &&
          reflectionCallback < grantCallback,
      "restored default-region attribute was not delivered before its Flush Queue grant");
  auto const flushGrants = receiver.recorder().flushQueueGrants();
  auto const& flushGrant = flushGrants.front();
  require(
      !flushGrant.time.empty() && !flushGrant.timeText.empty() &&
          flushGrant.optimisticTime == encodeTime(*queuedTime) &&
          flushGrant.optimisticTimeText == queuedTime->toString(),
      "restored default-region attribute Flush Queue grant returned the wrong "
      "saved or optimistic frontier");

  publisher.rtiAmbassador().retract(retraction);
  waitFor(
      receiver,
      [&] { return receiver.recorder().retractions().size() >= 1U; },
      options,
      "restored default-region attribute retraction callback");
  require(
      receiver.recorder().retractions().front().valid &&
          receiver.recorder().retractions().front().encoded == copyBytes(retraction.encode()),
      "restored default-region attribute retraction returned the wrong handle");
  requireException(
      [&] { publisher.rtiAmbassador().retract(retraction); },
      L"MessageCanNoLongerBeRetracted",
      "second retraction of restored default-region attribute");

  receiver.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      receiverHandles.objectClass,
      receiverPair);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherHandles.objectClass,
      publisherAttributes);
  receiver.rtiAmbassador().deleteRegion(receiverRegion);
  receiver.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

void scenarioTimedRegionalAttributeNegotiatedRegularCandidateContinuationImpl(
    Options const& options,
    rti::CallbackModel model,
    bool cancelAfterConfirmation,
    bool cancelBeforeConfirmation) {
  require(
      !options.multiAttributeFom.empty(),
      "Timed negotiated regional attribute continuation requires an adapter-supplied multi-attribute FOM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timed negotiated regional attribute continuation requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "timed-negotiated-publisher");
  Session firstReceiver(options, model, "timed-negotiated-first");
  Session secondReceiver(options, model, "timed-negotiated-second");
  Session clock(options, model, "timed-negotiated-clock");
  auto const federation = federationName(
      options,
      cancelBeforeConfirmation
          ? "timed-regional-attribute-negotiated-regular-pre-delivery-cancel-after-restore"
          : cancelAfterConfirmation
              ? "timed-regional-attribute-negotiated-regular-confirmation-cancel-after-restore"
              : "timed-regional-attribute-negotiated-regular-candidate-continuation-after-restore");

  publisher.connect();
  firstReceiver.connect();
  secondReceiver.connect();
  clock.connect();
  publisher.rtiAmbassador().createFederationExecution(
      federation,
      options.multiAttributeFom.wstring(),
      options.logicalTimeImplementationName);
  publisher.join(
      options.ownerFederateName + L"-timed-negotiated-publisher",
      options.federateType,
      federation);
  firstReceiver.join(
      options.memberFederateName + L"-timed-negotiated-first",
      options.federateType,
      federation);
  secondReceiver.join(
      options.memberFederateName + L"-timed-negotiated-second",
      options.federateType,
      federation);
  clock.join(
      options.memberFederateName + L"-timed-negotiated-clock",
      options.federateType,
      federation);

  auto const publisherHandles = multiAttributeDdmHandles(publisher, options);
  auto const firstHandles = multiAttributeDdmHandles(firstReceiver, options);
  auto const secondHandles = multiAttributeDdmHandles(secondReceiver, options);
  auto const clockHandles = multiAttributeDdmHandles(clock, options);
  verifyDdmObjectClassDimensions(
      publisher,
      options,
      publisherHandles.objectClass,
      publisherHandles.firstDimension,
      publisherHandles.secondDimension,
      "timed negotiated regional attribute publisher");
  verifyDdmObjectClassDimensions(
      firstReceiver,
      options,
      firstHandles.objectClass,
      firstHandles.firstDimension,
      firstHandles.secondDimension,
      "timed negotiated regional attribute first receiver");
  verifyDdmObjectClassDimensions(
      secondReceiver,
      options,
      secondHandles.objectClass,
      secondHandles.firstDimension,
      secondHandles.secondDimension,
      "timed negotiated regional attribute second receiver");
  verifyDdmObjectClassDimensions(
      clock,
      options,
      clockHandles.objectClass,
      clockHandles.firstDimension,
      clockHandles.secondDimension,
      "timed negotiated regional attribute clock");

  rti::AttributeHandleSet const publisherAttributes{publisherHandles.firstAttribute};
  rti::AttributeHandleSet const firstAttributes{firstHandles.firstAttribute};
  rti::AttributeHandleSet const secondAttributes{secondHandles.firstAttribute};
  rti::AttributeHandleSet const clockAttributes{clockHandles.firstAttribute};
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherHandles.objectClass,
      publisherAttributes);
  publisher.rtiAmbassador().changeDefaultAttributeOrderType(
      publisherHandles.objectClass,
      publisherAttributes,
      rti::TIMESTAMP);

  auto const sourceRegion = createDdmRegionForDimensions(
      publisher,
      publisherHandles.firstDimension,
      publisherHandles.secondDimension,
      0UL,
      2UL,
      0UL,
      2UL);
  auto const firstRegion = createDdmRegionForDimensions(
      firstReceiver,
      firstHandles.firstDimension,
      firstHandles.secondDimension,
      1UL,
      3UL,
      0UL,
      2UL);
  auto const secondRegion = createDdmRegionForDimensions(
      secondReceiver,
      secondHandles.firstDimension,
      secondHandles.secondDimension,
      0UL,
      1UL,
      0UL,
      2UL);
  rti::AttributeHandleSetRegionHandleSetPairVector const publisherPair{{
      publisherAttributes,
      rti::RegionHandleSet{sourceRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const firstPair{{
      firstAttributes,
      rti::RegionHandleSet{firstRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const secondPair{{
      secondAttributes,
      rti::RegionHandleSet{secondRegion},
  }};
  firstReceiver.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  secondReceiver.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  require(
      firstReceiver.rtiAmbassador().getConveyRegionDesignatorSetsSwitch() &&
          secondReceiver.rtiAmbassador().getConveyRegionDesignatorSetsSwitch(),
      "timed negotiated regional attribute did not enable region designator callbacks");
  firstReceiver.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      firstHandles.objectClass,
      firstPair);
  secondReceiver.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      secondHandles.objectClass,
      secondPair);
  clock.rtiAmbassador().subscribeObjectClassAttributes(
      clockHandles.objectClass,
      clockAttributes,
      true,
      L"");

  auto const object = publisher.rtiAmbassador().registerObjectInstanceWithRegions(
      publisherHandles.objectClass,
      publisherPair);
  require(
      object.isValid(),
      "timed negotiated regional attribute registration returned an invalid object handle");
  waitForSessions(
      {&firstReceiver, &secondReceiver, &clock},
      [&] {
        return firstReceiver.recorder().hasDiscovery(object) &&
            secondReceiver.recorder().hasDiscovery(object) &&
            clock.recorder().hasDiscovery(object);
      },
      options,
      "timed negotiated regional attribute object discovery");

  auto publisherTime = makeTimeContext(publisher);
  auto firstTime = makeTimeContext(firstReceiver);
  auto secondTime = makeTimeContext(secondReceiver);
  auto clockTime = makeTimeContext(clock);
  require(
      publisherTime.factory->getName() == firstTime.factory->getName() &&
          publisherTime.factory->getName() == secondTime.factory->getName() &&
          publisherTime.factory->getName() == clockTime.factory->getName(),
      "timed negotiated regional attribute members selected different logical-time factories");

  firstReceiver.rtiAmbassador().enableTimeConstrained();
  waitFor(
      firstReceiver,
      [&] { return firstReceiver.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "timed negotiated regional attribute first time-constrained callback");
  secondReceiver.rtiAmbassador().enableTimeConstrained();
  waitFor(
      secondReceiver,
      [&] { return secondReceiver.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "timed negotiated regional attribute second time-constrained callback");
  publisher.rtiAmbassador().enableTimeRegulation(*publisherTime.epsilon);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timed negotiated regional attribute publisher time-regulation callback");
  clock.rtiAmbassador().enableTimeRegulation(*clockTime.epsilon);
  waitFor(
      clock,
      [&] { return clock.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timed negotiated regional attribute clock time-regulation callback");

  auto const saveTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      6U);
  auto const messageTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      8U);
  auto const publisherGrantTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      9U);
  auto const flushTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      10U);
  std::vector<std::uint8_t> const valueBytes{
      0x44U, 0x45U, 0x4CU, 0x45U, 0x54U, 0x45U};
  std::vector<std::uint8_t> const tagBytes{
      0x52U, 0x45U, 0x53U, 0x54U, 0x4FU, 0x52U, 0x45U};
  rti::AttributeHandleValueMap values;
  values.emplace(
      publisherHandles.firstAttribute,
      rti::VariableLengthData(valueBytes.data(), valueBytes.size()));
  rti::VariableLengthData updateTag(tagBytes.data(), tagBytes.size());
  auto const retraction = publisher.rtiAmbassador().updateAttributeValues(
      object,
      values,
      updateTag,
      *messageTime);
  require(
      retraction.isValid(),
      "timed negotiated regional attribute update returned an invalid retraction handle");
  require(
      firstReceiver.recorder().timedReflections().empty() &&
          secondReceiver.recorder().timedReflections().empty(),
      "timed negotiated regional attribute update reflected before the constrained grants");

  std::wstring const saveLabel =
      L"timed-regional-attribute-negotiated-regular-candidate-continuation";
  publisher.rtiAmbassador().requestFederationSave(saveLabel, *saveTime);
  firstReceiver.rtiAmbassador().timeAdvanceRequest(*saveTime);
  secondReceiver.rtiAmbassador().timeAdvanceRequest(*saveTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*saveTime);
  clock.rtiAmbassador().timeAdvanceRequest(*saveTime);
  waitForSessions(
      {&publisher, &firstReceiver, &secondReceiver, &clock},
      [&] {
        return publisher.federateSaveTimes().size() >= 1U &&
            firstReceiver.federateSaveTimes().size() >= 1U &&
            secondReceiver.federateSaveTimes().size() >= 1U &&
            clock.federateSaveTimes().size() >= 1U;
      },
      options,
      "timed negotiated regional attribute save initiation callbacks");
  auto const publisherSaveLabels = publisher.federateSaveInitiations();
  auto const firstSaveLabels = firstReceiver.federateSaveInitiations();
  auto const secondSaveLabels = secondReceiver.federateSaveInitiations();
  auto const clockSaveLabels = clock.federateSaveInitiations();
  require(
      publisherSaveLabels.front() == saveLabel &&
          firstSaveLabels.front() == saveLabel &&
          secondSaveLabels.front() == saveLabel &&
          clockSaveLabels.front() == saveLabel,
      "timed negotiated regional attribute save initiation returned the wrong label");
  require(
      publisher.federateSaveTimes().front().encoded == encodeTime(*saveTime) &&
          firstReceiver.federateSaveTimes().front().encoded == encodeTime(*saveTime) &&
          secondReceiver.federateSaveTimes().front().encoded == encodeTime(*saveTime) &&
          clock.federateSaveTimes().front().encoded == encodeTime(*saveTime),
      "timed negotiated regional attribute save initiation returned the wrong timestamp");

  publisher.rtiAmbassador().federateSaveBegun();
  firstReceiver.rtiAmbassador().federateSaveBegun();
  secondReceiver.rtiAmbassador().federateSaveBegun();
  clock.rtiAmbassador().federateSaveBegun();
  publisher.rtiAmbassador().federateSaveComplete();
  firstReceiver.rtiAmbassador().federateSaveComplete();
  secondReceiver.rtiAmbassador().federateSaveComplete();
  clock.rtiAmbassador().federateSaveComplete();
  waitForSessions(
      {&publisher, &firstReceiver, &secondReceiver, &clock},
      [&] {
        return publisher.federationSavedCount() >= 1U &&
            firstReceiver.federationSavedCount() >= 1U &&
            secondReceiver.federationSavedCount() >= 1U &&
            clock.federationSavedCount() >= 1U;
      },
      options,
      "timed negotiated regional attribute saved callbacks");
  require(
      publisher.federationNotSavedReasons().empty() &&
          firstReceiver.federationNotSavedReasons().empty() &&
          secondReceiver.federationNotSavedReasons().empty() &&
          clock.federationNotSavedReasons().empty(),
      "timed negotiated regional attribute save reported a failure");
  require(
      firstReceiver.recorder().timedReflections().empty() &&
          secondReceiver.recorder().timedReflections().empty(),
      "timed negotiated regional attribute save delivered the queued reflection early");

  publisher.rtiAmbassador().setRangeBounds(
      sourceRegion,
      publisherHandles.firstDimension,
      rti::RangeBounds(0UL, 1UL));
  publisher.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{sourceRegion});
  auto const mutatedBounds = publisher.rtiAmbassador().getRangeBounds(
      sourceRegion,
      publisherHandles.firstDimension);
  require(
      mutatedBounds.getLowerBound() == 0UL && mutatedBounds.getUpperBound() == 1UL,
      "timed negotiated regional attribute pre-restore region mutation was not applied");

  publisher.rtiAmbassador().requestFederationRestore(saveLabel);
  waitForSessions(
      {&publisher, &firstReceiver, &secondReceiver, &clock},
      [&] {
        return publisher.federationRestoreRequestsSucceeded().size() >= 1U &&
            publisher.federationRestoreBegunCount() >= 1U &&
            firstReceiver.federationRestoreBegunCount() >= 1U &&
            secondReceiver.federationRestoreBegunCount() >= 1U &&
            clock.federationRestoreBegunCount() >= 1U &&
            publisher.federateRestoreInitiations().size() >= 1U &&
            firstReceiver.federateRestoreInitiations().size() >= 1U &&
            secondReceiver.federateRestoreInitiations().size() >= 1U &&
            clock.federateRestoreInitiations().size() >= 1U;
      },
      options,
      "timed negotiated regional attribute restore initiation callbacks");
  require(
      publisher.federationRestoreRequestsSucceeded().back() == saveLabel &&
          publisher.federationRestoreRequestsFailed().empty() &&
          firstReceiver.federationRestoreRequestsFailed().empty() &&
          secondReceiver.federationRestoreRequestsFailed().empty() &&
          clock.federationRestoreRequestsFailed().empty(),
      "timed negotiated regional attribute restore request returned an unexpected result");
  auto const publisherRestore = publisher.federateRestoreInitiations().back();
  auto const firstRestore = firstReceiver.federateRestoreInitiations().back();
  auto const secondRestore = secondReceiver.federateRestoreInitiations().back();
  auto const clockRestore = clock.federateRestoreInitiations().back();
  require(
      publisherRestore.label == saveLabel && firstRestore.label == saveLabel &&
          secondRestore.label == saveLabel && clockRestore.label == saveLabel &&
          publisherRestore.postRestoreFederateHandle.isValid() &&
          firstRestore.postRestoreFederateHandle.isValid() &&
          secondRestore.postRestoreFederateHandle.isValid() &&
          clockRestore.postRestoreFederateHandle.isValid(),
      "timed negotiated regional attribute restore returned invalid identity data");

  publisher.rtiAmbassador().federateRestoreComplete();
  firstReceiver.rtiAmbassador().federateRestoreComplete();
  secondReceiver.rtiAmbassador().federateRestoreComplete();
  clock.rtiAmbassador().federateRestoreComplete();
  waitForSessions(
      {&publisher, &firstReceiver, &secondReceiver, &clock},
      [&] {
        return publisher.federationRestoredCount() >= 1U &&
            firstReceiver.federationRestoredCount() >= 1U &&
            secondReceiver.federationRestoredCount() >= 1U &&
            clock.federationRestoredCount() >= 1U;
      },
      options,
      "timed negotiated regional attribute restored callbacks");
  require(
      publisher.federationNotRestoredReasons().empty() &&
          firstReceiver.federationNotRestoredReasons().empty() &&
          secondReceiver.federationNotRestoredReasons().empty() &&
          clock.federationNotRestoredReasons().empty(),
      "timed negotiated regional attribute restore reported a failure");
  auto const restoredBounds = publisher.rtiAmbassador().getRangeBounds(
      sourceRegion,
      publisherHandles.firstDimension);
  require(
      restoredBounds.getLowerBound() == 0UL && restoredBounds.getUpperBound() == 2UL,
      "timed negotiated regional attribute restore did not recover the saved source region");

  publisher.rtiAmbassador().setRangeBounds(
      sourceRegion,
      publisherHandles.firstDimension,
      rti::RangeBounds(3UL, 4UL));
  publisher.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{sourceRegion});
  auto const disjointBounds = publisher.rtiAmbassador().getRangeBounds(
      sourceRegion,
      publisherHandles.firstDimension);
  require(
      disjointBounds.getLowerBound() == 3UL && disjointBounds.getUpperBound() == 4UL,
      "timed negotiated regional attribute post-restore region mutation was not applied");

  firstReceiver.rtiAmbassador().publishObjectClassAttributes(
      firstHandles.objectClass,
      firstAttributes);
  clock.rtiAmbassador().publishObjectClassAttributes(
      clockHandles.objectClass,
      clockAttributes);
  std::vector<std::uint8_t> const firstAcquisitionTagBytes{
      0x41U, 0x43U, 0x51U, 0x2DU, 0x31U};
  std::vector<std::uint8_t> const secondAcquisitionTagBytes{
      0x41U, 0x43U, 0x51U, 0x2DU, 0x32U};
  std::vector<std::uint8_t> const negotiatedTagBytes{
      0x4EU, 0x45U, 0x47U, 0x2DU, 0x54U};
  std::vector<std::uint8_t> const confirmationTagBytes{
      0x43U, 0x4FU, 0x4EU, 0x2DU, 0x54U};
  rti::VariableLengthData firstAcquisitionTag(
      firstAcquisitionTagBytes.data(),
      firstAcquisitionTagBytes.size());
  rti::VariableLengthData secondAcquisitionTag(
      secondAcquisitionTagBytes.data(),
      secondAcquisitionTagBytes.size());
  rti::VariableLengthData negotiatedTag(
      negotiatedTagBytes.data(),
      negotiatedTagBytes.size());
  rti::VariableLengthData confirmationTag(
      confirmationTagBytes.data(),
      confirmationTagBytes.size());
  publisher.recorder().clearOwnershipRecords();
  firstReceiver.recorder().clearOwnershipRecords();
  secondReceiver.recorder().clearOwnershipRecords();
  clock.recorder().clearOwnershipRecords();
  publisher.recorder().clearCallbackOrder();

  bool immediateOwnershipTransfer = false;
  if (model == rti::HLA_IMMEDIATE) {
    // Immediate delivery closes every pre-confirmation cancellation window.
    // Verify the standard unavailable boundary before the saved timestamped
    // update is released; the ownership handoff is checked after that
    // delivery.
    firstReceiver.rtiAmbassador().attributeOwnershipAcquisitionIfAvailable(
        object,
        firstAttributes,
        firstAcquisitionTag);
    require(
        !firstReceiver.recorder().ownershipAcquisition().has_value() &&
            !firstReceiver.rtiAmbassador().isAttributeOwnedByFederate(
                object,
                firstHandles.firstAttribute),
        "timed negotiated regional attribute unavailable first candidate changed ownership");
    firstReceiver.resign(rti::NO_ACTION);
  } else {
    firstReceiver.rtiAmbassador().attributeOwnershipAcquisition(
        object,
        firstAttributes,
        firstAcquisitionTag);
    clock.rtiAmbassador().attributeOwnershipAcquisition(
        object,
        clockAttributes,
        secondAcquisitionTag);
    require(
        !firstReceiver.recorder().ownershipAcquisition().has_value(),
        "timed negotiated regional attribute first regular candidate completed too early");
    require(
        !clock.recorder().ownershipAcquisition().has_value(),
        "timed negotiated regional attribute clock regular candidate completed too early");
    require(
        !publisher.recorder().divestitureConfirmation().has_value(),
        "timed negotiated regional attribute owner received confirmation too early");
    // A regular acquisition is allowed to request an ordinary release before
    // the owner starts negotiated divestiture. Clear that delivered callback so
    // the continuation assertion below observes the surviving candidate's
    // request rather than the first candidate's earlier request.
    publisher.recorder().clearOwnershipRecords();
    publisher.recorder().clearCallbackOrder();

    publisher.rtiAmbassador().negotiatedAttributeOwnershipDivestiture(
        object,
        publisherAttributes,
        negotiatedTag);
    require(
        publisher.rtiAmbassador().isAttributeOwnedByFederate(
            object,
            publisherHandles.firstAttribute),
        "timed negotiated regional attribute divestiture changed publisher ownership too early");
    require(
        !clock.rtiAmbassador().isAttributeOwnedByFederate(
            object,
            clockHandles.firstAttribute),
        "timed negotiated regional attribute divestiture transferred to the retained candidate too early");
    require(
        !publisher.recorder().divestitureConfirmation().has_value(),
        "timed negotiated regional attribute divestiture delivered confirmation too early");

    firstReceiver.resign(rti::CANCEL_PENDING_OWNERSHIP_ACQUISITIONS);
    for (int pass = 0; pass != 8; ++pass) {
      publisher.pump();
    }
    auto const releaseRequest = publisher.recorder().ownershipReleaseRequest();
    if (releaseRequest.has_value()) {
      require(
          releaseRequest->object == object &&
              releaseRequest->attributes == publisherAttributes &&
              releaseRequest->tag == secondAcquisitionTagBytes,
          "timed negotiated regional attribute release request returned the retained candidate");
    }
    auto const releaseCallbackOrder = publisher.recorder().callbackOrder();
    require(
        releaseCallbackOrder.empty() ||
            std::find(
                releaseCallbackOrder.begin(),
                releaseCallbackOrder.end(),
                "ownership-release") != releaseCallbackOrder.end(),
        "timed negotiated regional attribute owner callback order changed after resignation");
    require(
        !publisher.recorder().divestitureConfirmation().has_value(),
        "timed negotiated regional attribute delivered a stale confirmation after resignation");
    require(
        !clock.recorder().ownershipAcquisition().has_value(),
        "timed negotiated regional attribute delivered a stale acquisition after resignation");

    publisher.rtiAmbassador().negotiatedAttributeOwnershipDivestiture(
        object,
        publisherAttributes,
        negotiatedTag);
    if (cancelBeforeConfirmation) {
      require(
          !publisher.recorder().divestitureConfirmation().has_value(),
          "timed negotiated regional attribute pre-delivery cancellation crossed the callback boundary");
      publisher.rtiAmbassador().cancelNegotiatedAttributeOwnershipDivestiture(
          object,
          publisherAttributes);
      require(
          publisher.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              publisherHandles.firstAttribute) &&
              !clock.rtiAmbassador().isAttributeOwnedByFederate(
                  object,
                  clockHandles.firstAttribute),
          "timed negotiated regional attribute pre-delivery cancellation changed ownership");
      require(
          !publisher.recorder().divestitureConfirmation().has_value() &&
              !clock.recorder().ownershipAcquisition().has_value(),
          "timed negotiated regional attribute pre-delivery cancellation delivered stale ownership callbacks");
      clock.rtiAmbassador().cancelAttributeOwnershipAcquisition(
          object,
          clockAttributes);
      waitFor(
          clock,
          [&] { return clock.recorder().ownershipAcquisitionCancellation().has_value(); },
          options,
          "timed negotiated regional attribute pre-delivery acquisition cancellation");
      auto const acquisitionCancellation = clock.recorder().ownershipAcquisitionCancellation();
      require(
          acquisitionCancellation->object == object &&
              acquisitionCancellation->attributes == clockAttributes,
          "timed negotiated regional attribute pre-delivery cancellation returned the wrong metadata");
    } else {
      waitFor(
          publisher,
          [&] { return publisher.recorder().divestitureConfirmation().has_value(); },
          options,
          "timed negotiated regional attribute retained-candidate confirmation request");
      auto const confirmation = publisher.recorder().divestitureConfirmation();
      require(
          confirmation->object == object &&
              confirmation->attributes == publisherAttributes &&
              confirmation->tag == secondAcquisitionTagBytes &&
              publisher.rtiAmbassador().isAttributeOwnedByFederate(
                  object,
                  publisherHandles.firstAttribute) &&
              !clock.recorder().ownershipAcquisition().has_value(),
          "timed negotiated regional attribute confirmation selected the wrong candidate");
    }
  }

  secondReceiver.recorder().clearTimedReflections();
  secondReceiver.recorder().clearFlushQueueGrants();
  secondReceiver.recorder().clearCallbackOrder();
  secondReceiver.rtiAmbassador().flushQueueRequest(*flushTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*publisherGrantTime);
  clock.rtiAmbassador().timeAdvanceRequest(*publisherGrantTime);
  waitForSessions(
      {&publisher, &clock, &secondReceiver},
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 1U &&
            clock.recorder().timeAdvanceGrants().size() >= 1U &&
            secondReceiver.recorder().timedReflections().size() >= 1U &&
            secondReceiver.recorder().flushQueueGrants().size() >= 1U;
      },
      options,
      "timed negotiated regional attribute surviving recipient delivery and grant");
  auto const reflections = secondReceiver.recorder().timedReflections();
  require(
      reflections.size() == 1U &&
          secondReceiver.recorder().timedRemovals().empty(),
      "timed negotiated regional attribute delivered the wrong surviving callback count");
  auto const& reflection = reflections.front();
  require(
      reflection.object == object &&
          reflection.values.size() == 1U &&
          reflection.values.count(secondHandles.firstAttribute) == 1U &&
          copyBytes(reflection.values.at(secondHandles.firstAttribute)) == valueBytes &&
          reflection.tag == tagBytes &&
          reflection.producer == publisherRestore.postRestoreFederateHandle &&
          reflection.time == encodeTime(*messageTime) &&
          reflection.sentOrder == rti::TIMESTAMP &&
          reflection.receivedOrder == rti::TIMESTAMP &&
          reflection.retractionPresent &&
          reflection.retraction == copyBytes(retraction.encode()) &&
          reflection.transportation.isValid() &&
          !secondReceiver.rtiAmbassador()
               .getTransportationTypeName(reflection.transportation)
               .empty() &&
          reflection.regions.has_value() &&
          reflection.regions->size() == 1U &&
          reflection.regions->count(sourceRegion) == 1U,
      "timed negotiated regional attribute changed the saved reflection metadata");
  require(
      secondReceiver.recorder().callbackOrder() ==
          std::vector<std::string>{"reflect", "flush-grant"},
      "timed negotiated regional attribute delivered the reflection after its Flush Queue grant");
  auto const flushGrants = secondReceiver.recorder().flushQueueGrants();
  require(
      flushGrants.front().optimisticTime == encodeTime(*messageTime) &&
          !flushGrants.front().time.empty() &&
          !flushGrants.front().timeText.empty(),
      "timed negotiated regional attribute returned the wrong Flush Queue frontier");
  auto const secondDiscovery = secondReceiver.recorder().discovery();
  require(
      secondReceiver.rtiAmbassador().getObjectInstanceHandle(secondDiscovery.name) == object,
      "timed negotiated regional attribute changed the object identity after restore");

  if (model == rti::HLA_IMMEDIATE) {
    publisher.recorder().clearOwnershipRecords();
    clock.recorder().clearOwnershipRecords();
    clock.rtiAmbassador().attributeOwnershipAcquisition(
        object,
        clockAttributes,
        secondAcquisitionTag);
    waitFor(
        publisher,
        [&] { return publisher.recorder().ownershipReleaseRequest().has_value(); },
        options,
        "timed negotiated regional attribute immediate ownership-release request");
    auto const releaseRequest = publisher.recorder().ownershipReleaseRequest();
    require(
        releaseRequest->object == object &&
            releaseRequest->attributes == publisherAttributes &&
            releaseRequest->tag == secondAcquisitionTagBytes,
        "timed negotiated regional attribute immediate release request returned the wrong candidate");
    rti::AttributeHandleSet divestedAttributes;
    publisher.rtiAmbassador().attributeOwnershipDivestitureIfWanted(
        object,
        publisherAttributes,
        negotiatedTag,
        divestedAttributes);
    require(
        divestedAttributes == publisherAttributes,
        "timed negotiated regional attribute immediate divestiture returned the wrong attributes");
    waitFor(
        clock,
        [&] { return clock.recorder().ownershipAcquisition().has_value(); },
        options,
        "timed negotiated regional attribute immediate ownership notification");
    auto const immediateAcquisition = clock.recorder().ownershipAcquisition();
    require(
        immediateAcquisition->object == object &&
            immediateAcquisition->attributes == clockAttributes &&
            immediateAcquisition->tag == negotiatedTagBytes &&
            !publisher.rtiAmbassador().isAttributeOwnedByFederate(
                object,
                publisherHandles.firstAttribute) &&
            clock.rtiAmbassador().isAttributeOwnedByFederate(
                object,
                clockHandles.firstAttribute),
        "timed negotiated regional attribute immediate ownership transfer returned the wrong state");
    immediateOwnershipTransfer = true;
  }

  if (cancelAfterConfirmation && !immediateOwnershipTransfer) {
    publisher.rtiAmbassador().cancelNegotiatedAttributeOwnershipDivestiture(
        object,
        publisherAttributes);
    require(
        publisher.rtiAmbassador().isAttributeOwnedByFederate(
            object,
            publisherHandles.firstAttribute) &&
            !clock.rtiAmbassador().isAttributeOwnedByFederate(
                object,
                clockHandles.firstAttribute),
        "timed negotiated regional attribute cancellation changed ownership");
    requireException(
        [&] {
          publisher.rtiAmbassador().confirmDivestiture(
              object,
              publisherAttributes,
              confirmationTag);
        },
        L"AttributeDivestitureWasNotRequested",
        "timed negotiated regional attribute confirmation after cancellation");
    require(
        publisher.recorder().divestitureConfirmation().has_value() &&
            !clock.recorder().ownershipAcquisition().has_value(),
        "timed negotiated regional attribute cancellation delivered stale ownership callbacks");
    clock.rtiAmbassador().cancelAttributeOwnershipAcquisition(
        object,
        clockAttributes);
    waitFor(
        clock,
        [&] { return clock.recorder().ownershipAcquisitionCancellation().has_value(); },
        options,
        "timed negotiated regional attribute acquisition cancellation");
    auto const acquisitionCancellation = clock.recorder().ownershipAcquisitionCancellation();
    require(
        acquisitionCancellation->object == object &&
            acquisitionCancellation->attributes == clockAttributes,
        "timed negotiated regional attribute cancellation returned the wrong metadata");
  } else if (!cancelBeforeConfirmation && !immediateOwnershipTransfer) {
    publisher.rtiAmbassador().confirmDivestiture(
        object,
        publisherAttributes,
        confirmationTag);
    require(
        !publisher.rtiAmbassador().isAttributeOwnedByFederate(
            object,
            publisherHandles.firstAttribute) &&
            clock.rtiAmbassador().isAttributeOwnedByFederate(
                object,
                clockHandles.firstAttribute),
        "timed negotiated regional attribute confirmation did not transfer ownership");
    waitFor(
        clock,
        [&] { return clock.recorder().ownershipAcquisition().has_value(); },
        options,
        "timed negotiated regional attribute acquisition notification");
    auto const acquisition = clock.recorder().ownershipAcquisition();
    require(
        acquisition->object == object &&
            acquisition->attributes == clockAttributes &&
            acquisition->tag == confirmationTagBytes,
        "timed negotiated regional attribute acquisition returned the wrong metadata");
  }

  secondReceiver.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  clock.rtiAmbassador().disableTimeRegulation();
  secondReceiver.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      secondHandles.objectClass,
      secondPair);
  clock.rtiAmbassador().unsubscribeObjectClassAttributes(
      clockHandles.objectClass,
      clockAttributes);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherHandles.objectClass,
      publisherAttributes);
  clock.rtiAmbassador().unpublishObjectClassAttributes(
      clockHandles.objectClass,
      clockAttributes);
  secondReceiver.rtiAmbassador().deleteRegion(secondRegion);
  secondReceiver.resign(rti::NO_ACTION);
  publisher.resign(rti::DELETE_OBJECTS_THEN_DIVEST);
  clock.resign(rti::NO_ACTION);
  clock.rtiAmbassador().destroyFederationExecution(federation);
  firstReceiver.disconnect();
  secondReceiver.disconnect();
  clock.disconnect();
  publisher.disconnect();
}

